INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9e5bad9c-c326-568e-ad45-05e2856e5086', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 3, 25, 'እኔ እንድሻገርና፥ በዮርዳኖስም ማዶ ያለችውን መልካሚቱን ምድር፥ ያንም መልካሙን ተራራማውን ሀገር አንጢ ሊባኖስንም እንዳይ ፍቀድልኝ።'),
  ('6b05e914-7355-542f-aa06-0d880cb17879', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 4, 26, 'እግዚአብሔር ግን በእናንተ ምክንያት ተቈጣኝ፤ አልሰማኝምም፤ እግዚአብሔርም አለኝ፦ ‘ይበቃሃል፤ በዚህ ነገር ደግመህ አትናገረኝ።’'),
  ('5e719b5a-b4ed-596f-afdc-354627ebcc36', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 5, 27, 'ይህን ዮርዳኖስን አትሻገርምና ወደ ተራራው ራስ ውጣ፤ ዐይንህንም ወደ ባሕር ወደ መስዕም፥ ወደ አዜብም ወደ ምሥራቅም አንሥተህ በዐይንህ ተመልከት።'),
  ('05b649e7-0a4e-50be-a87e-d4751a0e87db', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 6, 28, 'ኢያሱ በዚህ ሕዝብ ፊት ይሻገራልና፥ አንተም የምታያትን ምድር እርሱ ያወርሳቸዋልና ኢያሱን እዘዘው፤ አደፋፍረውም፥ አጽናውም።'),
  ('13cad180-8d86-5ccd-a4d8-50fdd724311a', 'f2284491-3b35-5048-a5ff-401018315b9c', '4e50d6f4-3758-5b4f-a9f4-73f694d70ae5', 7, 29, 'በቤተ ፌጎርም ፊት ለፊት በሸለቆው ውስጥ ተቀመጥን።'),
  ('0abb4169-d504-5fe2-acaf-72e48f3dd6eb', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 1, 1, '“አሁንም እስራኤል ሆይ፥ እንድታደርጉአቸው፥ በሕይወትም እንድትኖሩ፥ እንድትበዙም፥ የአባቶቻችሁም አምላክ እግዚአብሔር ወደሚሰጣችሁ ምድር ገብታችሁ እንድትወርሱ፥ ዛሬ የማስተምራችሁን ሥርዐትና ፍርድ ስሙ።'),
  ('a44857c8-84a2-502b-af6a-e66f7b7d79ea', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 2, 2, 'ዛሬ እኔ ያዘዝኋችሁን የአምላካችሁን የእግዚአብሔርን ትእዛዝ ትጠብቃላችሁ እንጂ ባዘዝኋችሁ ቃል ላይ አትጨምሩም፤ ከእርሱም አታጐድሉም።'),
  ('bada6582-b0e5-5ee6-abcb-57d36e391c0b', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 3, 3, 'ብዔልፌጎርን የተከተለውን ሰው ሁሉ አምላካችሁ እግዚአብሔር ከእናንተ ለይቶ አጥፍቶታልና አምላካችሁ እግዚአብሔር በብዔልፌጎር ያደረገውን ዐይኖቻችሁ አይተዋል።'),
  ('d9ed5964-a6b4-5793-adec-b01e735c1acf', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 4, 4, 'እናንተ ግን አምላካችሁን እግዚአብሔርን የተከተላችሁ እስከ ዛሬ ድረስ ሁላችሁ በሕይወት ትኖራላችሁ።'),
  ('582fe676-39ba-5a2a-a703-b37a84a0e326', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 5, 5, 'እነሆ፥ እናንተ ገብታችሁ በምትወርሱአት ምድር ውስጥ እንዲህ ታደርጉ ዘንድ አምላኬ እግዚአብሔር እንዳዘዘኝ ሥርዐትና ፍርድን አሳየኋችሁ።'),
  ('2e29396b-17d4-5094-a4c8-70bbb80583b8', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 6, 6, 'ጠብቁት፤ አድርጉትም፤ ይህን ሥርዐት ሁሉ ሰምተው፦ እነሆ፥ ‘ይህ ታላቅ ሕዝብ ጠቢብና አስተዋይ ሕዝብ ነው’ በሚሉ በአሕዛብ ፊት ጥበባችሁና ማስተዋላችሁ ይህ ነውና፤'),
  ('01265857-3b21-5381-ac13-ce1055cd4309', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 7, 7, 'አምላካችን እግዚአብሔር በምንጠራው ጊዜ ሁሉ እንደሚቀርበን፥ አምላኩ ወደ እርሱ የቀረበው ታላቅ ሕዝብ ማን ነው?'),
  ('90254d96-17af-5b76-ac75-d407affdba42', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 8, 8, 'ዛሬ በፊታችሁ እንደማኖራት እንደዚህች ሕግ ሁሉ ጽድቅ የሆነች ሥርዐትና ፍርድ ያለው ታላቅ ሕዝብ ማን ነው?'),
  ('de5d86e1-e26d-5135-a881-cd6e3c8ddadb', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 9, 9, '“ለራስህ ዕወቅ፤ ሰውነትህን ፈጽመህ ጠብቅ፤ ዐይኖችህ ያዩትን ይህን ሁሉ ነገር አትርሳ፤ በሕይወትህ ዘመን ሁሉ ከልቡናህ አይውጣ፤ ለልጆችህና ለልጅ ልጆችህም አስተምራቸው።'),
  ('c35913fb-9263-5ab1-a231-3f777a0b7585', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 10, 10, 'እግዚአብሔር ሕዝቡን ወደ እኔ ሰብስባቸው፤ እነርሱ በምድር ላይ በሕይወት በሚኖሩበት ዘመን ሁሉ እኔን መፍራት ይማሩና ለልጆቻቸውም ያስተምሩ ዘንድ ቃሌን ይስሙ ብሎኛልና በኮሬብ በተሰበሰባችሁ ጊዜ በፈጣሪያችሁ በእግዚአብሔር ፊት እንደ ቆማችሁ ንገራቸው።'),
  ('b518def1-a798-595a-ad08-8104faf730f2', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 11, 11, 'እናንተም ቀርባችሁ ከተራራው በታች ቆማችሁ ነበር፤ ተራራውም እስከ ሰማይ ድረስ በእሳት ይነድድ ነበር፤ ጨለማና አውሎ ነፋስ፥ ድቅድቅ ጨለማም ነበረ።'),
  ('8957b72c-3918-52a7-a35f-c3ebe8abf200', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 12, 12, 'እግዚአብሔርም በእሳት መካከል ሆኖ ተናገራችሁ፤ የቃልን ድምፅ ሰማችሁ፤ ከድምፅ በቀር መልክን ግን አላያችሁም።'),
  ('e5b83b8a-0e69-5e09-ad1b-6c3952ccebb3', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 13, 13, 'ታደርጉትም ዘንድ ያዘዛችሁን ቃል ኪዳን ዐሥሩን ቃላት ነገራችሁ፤ በሁለቱም የድንጋይ ጽላት ላይ ጻፋቸው።'),
  ('d3b1fda8-4ad4-520b-ae8d-6f1bc00b928d', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', 'a29d6965-a1e6-5967-a16a-97c63a18758d', 14, 14, 'ትወርሱአት ዘንድ ተሻግራችሁ በምትገቡባት ምድር የምታደርጉአትን ሥርዐትና ፍርድ አስተምራችሁ ዘንድ እግዚአብሔር በዚያን ጊዜ አዘዘኝ።'),
  ('a549b027-31c7-5ae1-ab6c-c537a6bac2a3', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 1, 15, '“እግዚአብሔር በኮሬብ ተራራ በእሳት መካከል ሆኖ በተናገራችሁ ቀን መልኩን ከቶ አላያችሁምና ሰውነታችሁን እጅግ ጠብቁ፤'),
  ('63f1a55b-bf05-59d3-a0e0-10a8f4ba104c', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 2, 16, 'እንዳትበድሉ፥ የተቀረጸውን ምስል፥ የማናቸውንም ነገር ምሳሌ፥ በወንድ ወይም በሴት መልክ የተሠራውን፥ በምድር ላይ ያለውን፥'),
  ('b156ae1e-84f1-5ab3-aeb4-1723c7098a7a', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 3, 17, 'የእንስሳን ሁሉ ምሳሌ ፥ ከሰማይም በታች የሚበርረውን የወፍን ሁሉ ምሳሌ፥'),
  ('d55a4bf6-2f2a-5f68-a76b-06344e7e3e71', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 4, 18, 'በምድርም ላይ የሚሽከረከረውን ሁሉ ምሳሌ፥ ከምድርም በታች በውኃ ውስጥ የሚኖረውን የዓሣን ሁሉ ምሳሌ አታድርጉ፤'),
  ('88b4c680-4130-5bdd-aea1-451ebe51f6ec', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 5, 19, 'ወደ ሰማይ አትመልከት፤ አምላክህ እግዚአብሔር ከሰማይ ሁሉ በታች ላሉት አሕዛብ ሁሉ የሰጣቸውን ፀሐይንና ጨረቃን፥ ከዋክብትንና የሰማይን ሠራዊት ሁሉ አይተህ፥ ሰግደህላቸው፥ አምልከሃቸውም እንዳትስት ተጠንቀቅ።'),
  ('378da43e-9a03-5b1a-ad1b-5273ce1efc98', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 6, 20, 'እናንተን ግን እንደ ዛሬው ሁሉ የርስቱ ሕዝብ ትሆኑለት ዘንድ እግዚአብሔር ወስዶ ከብረት እቶን ከግብፅ አወጣችሁ።'),
  ('03296171-9556-57b5-affc-cd69ba6af3dd', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 7, 21, 'እግዚአብሔርም እናንተ በተናገራችሁት ምክንያት ተቈጣኝ፤ ዮርዳኖስንም እንዳልሻገር፥ አምላክህም እግዚአብሔር ርስት አድርጎ ወደሚሰጥህ ወደ መልካሚቱ ምድር እንዳልገባ ማለ።'),
  ('556b4e32-8a9e-5c15-a05c-ecdbaf93485a', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 8, 22, 'እኔ ግን በዚህች ምድር እሞታለሁ። ይህን ዮርዳኖስንም አልሻገርም፤ እናንተ ግን ትሻገራላችሁ፤ ያችንም መልካሚቱን ምድር ትወርሳላችሁ።'),
  ('608a04d0-fcdb-5122-ac3c-c22e097ed37e', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 9, 23, 'ከእናንተ ጋር የተማማለውን የአምላካችንን የእግዚአብሔርን ቃል ኪዳን እንዳትረሱ፤ አምላክህ እግዚአብሔር የከለከለውን፥ በማናቸውም ቅርጽ የተቀረጸውን ምስል እንዳታደርጉ እንግዲህ ተጠንቀቁ።'),
  ('6416abf9-ed9b-5a5b-a7ef-4eeb446017b7', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 10, 24, 'አምላክህ እግዚአብሔር የሚበላ እሳት፥ ቀናተኛም አምላክ ነውና።'),
  ('281740dd-2ee8-50d1-a04b-dff7072febee', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 11, 25, '“ልጆችን፥ የልጅ ልጆችንም በወለዳችሁ ጊዜ፥ በምድሪቱም ረዥም ዘመን በተቀመጣችሁ ጊዜ፥ በበደላችሁም ጊዜ፥ በማናቸውም ቅርጽ የተቀረጸውን ምስል ባደረጋችሁ ጊዜ፥ ታስቈጡትም ዘንድ በአምላካችሁ በእግዚአብሔር ፊት ክፉ የሆነውን ነገር በሠራችሁ ጊዜ፥'),
  ('628782f5-271c-56a7-a758-b64abc6f1748', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 12, 26, 'ትወርሱአት ዘንድ ዮርዳኖስን ተሻግራችሁ ከምትገቡባት ምድር ፈጥናችሁ እንድትጠፉ እኔ ዛሬ ሰማይንና ምድርን በእናንተ አስመሰክራለሁ፤ ፈጽሞም ትጠፋላችሁ እንጂ ረዥም ዘመን አትቀመጡባትም።'),
  ('1d48da4b-04e2-5d57-a0a4-cc93a0cd1332', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 13, 27, 'እግዚአብሔርም በአሕዛብ መካከል ይበትናችኋል፤ እግዚአብሔር በውስጣቸው በሚያኖራችሁ በአሕዛብ መካከልም በቍጥር ጥቂቶች ሆናችሁ ትቀራላችሁ።'),
  ('b7b2ed2c-82ac-5f2e-a198-53f3865aab29', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 14, 28, 'በዚያም የማያዩትን፥ የማይሰሙትንም፥ የማይበሉትንም፥ የማያሸቱትንም፥ በሰው እጅ ከእንጨትና ከድንጋይ የተሠሩትን ሌሎች አማልክት ታመልካላችሁ።'),
  ('dbae2436-f6f2-58b7-a754-6c81ee26541c', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 15, 29, 'ነገር ግን ከዚያ አምላካችሁን እግዚአብሔርን ትሻላችሁ፤ በመከራህም ጊዜ በልብህም ሁሉ፥ በነፍስህም ሁሉየፈለግኸው እንደ ሆነ ታገኘዋለህ።'),
  ('78df8f07-6195-55f3-ad40-34660cde8a50', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 16, 30, 'ይህም ሁሉ ነገር በመጨረሻው ዘመን ይደርስብሃል፤ ወደ አምላክህ ወደ እግዚአብሔርም ትመለሳለህ፤ ቃሉንም ትሰማለህ።'),
  ('e9630a4e-b5e3-5a05-ae32-60a2874a1c4c', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 17, 31, 'አምላክህ እግዚአብሔር መሓሪ አምላክ ነውና አይተውህም፤ አያጠፋህምም፤ ለአባቶችህም የማለላቸውን ቃል ኪዳኑን አይረሳም።'),
  ('3051238a-4dc4-582b-a4d1-5431325a1d94', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 18, 32, '“እግዚአብሔር ሰውን በምድር ላይ ከፈጠረው ጀምሮ፥ ከሰማይ ዳር እስከ ሰማይ ዳርቻ ድረስ ከቶ እንዲህ ያለ ታላቅ ነገር ሆኖ፥ ወይም እንደ እርሱ ያለ ተሰምቶ እንደ ሆነ ከአንተ በፊት የነበረውን የቀደመውን ዘመን ጠይቅ።'),
  ('5ee19111-082c-5458-ae11-ec3d44861217', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 19, 33, 'አንተ ከእሳት መካከል ሆኖ ሲናገር የሕያው እግዚአብሔርን ድምፅ እንደ ሰማህና በሕይወት እንዳለህ ሌላ ሕዝብ ሰምቶ እንደ ሆነ፥'),
  ('7188c333-b512-5db6-a136-a663233d1fbc', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 20, 34, 'አምላካችን እግዚአብሔር በዐይናችሁ ፊት በግብፅ ለእናንተ እንደ ሠራው ሁሉ ፥ በፈተናና በተአምራት፥ በድንቅና በሰልፍ፥ በጸናች እጅና በተዘረጋ ክንድ፥ በታላቅም ማስፈራራት እግዚአብሔር ከሌላ ሕዝብ መካከል ገብቶ ለእርሱ ሕዝብን ይወስድ ዘንድ ሞክሮ እንደ ሆነ፥'),
  ('85a3352c-e75f-5015-a659-ff92d8430488', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 21, 35, 'እግዚአብሔርም አምላክ እንደ ሆነና ከእርሱም ሌላ አምላክ እንደ ሌለ እንድታውቅ፥'),
  ('923450fb-2a76-539d-a517-7564cc9f3ee9', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 22, 36, 'ያስተምርህ ዘንድ ከሰማይ ድምፁን አሰማህ፤ በምድርም ላይ ታላቁን እሳት አሳየህ፤ ከእሳቱም መካከል ቃሉን ሰማህ።'),
  ('75c814f1-e811-52c2-a4a2-446a4ce0aee8', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 23, 37, 'አባቶችህን ወድዶአልና ከእነርሱ በኋላ ዘራቸውን መረጠ፤ ከአንተም ጋር ሆኖ በታላቅ ኀይሉ ከግብፅ አወጣህ፤'),
  ('e1bf271a-86f6-59e9-a3f0-1825dc059e03', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 24, 38, 'ዛሬ እንደ ሆነው ሁሉ ከግብፅ ከአንተ የጸኑትን ታላላቆቹን አሕዛብ በፊትህ እንዲያወጣ፥ አንተንም እንዲያገባህ፥ ምድራቸውንም ርስት አድርጎ እንዲሰጥህ፥'),
  ('67cba7d1-f4af-58f6-a4b3-7d930df6cd40', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 25, 39, 'እንግዲህ እግዚአብሔር በላይ በሰማይ በታችም በምድር አምላክ እንደ ሆነ፥ ሌላም እንደ ሌለ ዛሬ ዕወቅ፤ በልብህም ያዝ።'),
  ('31c1459b-d576-5719-aeb9-b3cc22a523b9', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '0ae8991a-4894-51f9-a888-8efc5d3253b9', 26, 40, 'ለእናንተ፥ ከእናንተም በኋላ ለልጆቻችሁ መልካም ይሆን ዘንድ፥ አምላካችሁ እግዚአብሔር ለዘለዓለም በሚሰጣችሁ ምድር ዕድሜአችሁ ይረዝም ዘንድ፥ እኔ ዛሬ የማዝዛችሁን ሥርዐቱንና ትእዛዙን ጠብቁ።”'),
  ('0a53da8c-e330-5375-a1d1-1319d9d38ea2', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '3c3f59de-aa49-5e9e-a50a-ee40c2f34bc7', 1, 41, 'በዚያን ጊዜ ሙሴ በምሥራቅ በኩል በዮርዳኖስ ማዶ ሦስት ከተሞችን ለየ።'),
  ('fea70f5b-a10c-5b6a-a6df-aa99e783fcb6', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '3c3f59de-aa49-5e9e-a50a-ee40c2f34bc7', 2, 42, 'ትናንት፥ ከትናት በስቲያም ጠላቱ ያልሆነውን ባልንጀራውን ሳያውቅ የገደለ ገዳዩ ይማፀንባቸው ዘንድ፥ ከእነዚህም ከተሞች በአንዲቱ ተማፅኖ በሕይወት ይኖር ዘንድ፤'),
  ('3f8cdb5d-01af-5280-ad1a-5e26512f2ddf', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '3c3f59de-aa49-5e9e-a50a-ee40c2f34bc7', 3, 43, 'ለሮቤል ነገድ በምድረ በዳ በደልዳላ ስፍራ ያለ ባሶር፥ ለጋድም ነገድ በገለዓድ ያለ ራሞት፥ ለምናሴም ነገድ በባሳን ያለ ጎላን ነበሩ።'),
  ('955350f9-ee2c-50e7-a069-295fc8d4668a', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '79fc0210-545b-5725-adff-aa5e23f83bf0', 1, 44, 'ሙሴም በእስራኤል ልጆች ፊት ያኖራት ሕግ ይህች ናት፤'),
  ('69716c18-2516-5b2d-a14f-cd14c513dac4', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '79fc0210-545b-5725-adff-aa5e23f83bf0', 2, 45, 'ከግብፅ በወጡ ጊዜ ሙሴ ለእስራኤል ልጆች የተናገረው ምስክርና ሥርዐት፤ ፍርድም ይህ ነው።'),
  ('55b9de51-ef0c-51a6-af67-1a86773ea389', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '79fc0210-545b-5725-adff-aa5e23f83bf0', 3, 46, 'ሙሴና የእስራኤል ልጆች ከግብፅ ከወጡ በኋላ በመቱት፥ በሐሴቦን ተቀምጦ በነበረው በአሞሬዎን ንጉሥ በሴዎን ምድር፥ በቤተ ፌጎር አቅራቢያ ባለው ሸለቆ በዮርዳኖስ ማዶ፤'),
  ('1b17ae4b-2b06-5088-afe4-222ce67d191c', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '79fc0210-545b-5725-adff-aa5e23f83bf0', 4, 47, 'የእርሱንና የባሳንን ንጉሥ፥ የዐግን ምድር፥ በምሥራቅ በኩል በዮርዳኖስ ማዶ የነበሩትን የሁለቱን የአሞሬዎንን ነገሥታት ምድር ወሰዱ።'),
  ('60ecd1ee-ed09-5317-a2ef-6c9698e9c8ea', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '79fc0210-545b-5725-adff-aa5e23f83bf0', 5, 48, 'በአርኖን ወንዝ ዳር ካለችው ከአሮዔር ጀምሮ እስከ ሴዎን ተራራ እስከ ኤርሞን ድረስ፥'),
  ('7ee1008f-65ec-51ae-a3e3-68ec83dd0220', 'e818f44b-ff2b-59fa-a963-1f7ca6a54f8b', '79fc0210-545b-5725-adff-aa5e23f83bf0', 6, 49, 'በምሥራቅም በኩል በዮርዳኖስ ማዶ መሿለኪያ ካለው ከአሴዶን ተራራ በታች ያለውን ዓረባ ሁሉ ወሰዱ።'),
  ('0e045cfd-fa1b-5064-a5b9-eac8739fea01', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 1, 1, 'ሙሴም እስራኤልን ሁሉ ጠርቶ አላቸው፥ “እስራኤል ሆይ እንድትማሩአትም፥ በማድረግም እንድትጠብቁአት ዛሬ በጆሮአችሁ የምናገራትን ሥርዐትና ፍርድ ስሙ።'),
  ('2c501301-82af-5290-aa17-3e90386401d7', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 2, 2, 'አምላካችሁ እግዚአብሔር በኮሬብ ከእናንተ ጋር ቃል ኪዳኑን አጸና።'),
  ('d88bb862-f699-5bcf-a51d-fc44c89ad20f', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 3, 3, 'እግዚአብሔር ዛሬ በዚህ በሕይወት ካላችሁት ከእናንተ ከሁላችሁ ጋር እንጂ ከአባቶቻችሁ ጋር ይህችን ቃል ኪዳን አላጸናም።'),
  ('9166a02f-0666-559b-ac2e-aa8953dbcad0', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 4, 4, 'በተራራው ላይ በእሳት መካከል እግዚአብሔር ፊት ለፊት ተናገራችሁ።'),
  ('d27fe975-a9ca-5a25-ae5f-ade4de68bf1c', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 5, 5, 'እኔ የእግዚአብሔርን ቃል እነግራችሁ ዘንድ በዚያን ጊዜ በእግዚአብሔርና በእናንተ መካከል ቆሜ ነበር፤ እናንተ ከእሳቱ ፊት ፈርታችኋልና፥ ወደ ተራራው አልወጣችሁምና። እርሱም አለ፦'),
  ('4cdcad73-a508-5751-a8ca-c76712471a62', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 6, 6, '“ከግብፅ ምድር ከባርነት ቤት ያወጣሁህ እግዚአብሔር አምላክህ እኔ ነኝ።'),
  ('2d6c169a-1cc3-518f-abea-ef23941f5802', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 7, 7, '“ከእኔ በቀር ሌሎች አማልክት አይሁኑልህ።'),
  ('fc8d267c-bcfb-5ea2-affb-688b09016baa', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 8, 8, '“በላይ በሰማይ ካለው፥ በታችም በምድር ካለው፥ ከምድርም በታች በውኃ ካለው ነገር ማንኛውንም ምሳሌ፥ የተቀረጸውንም ምስል ለአንተ አታድርግ፤'),
  ('f024ecf4-18bb-5674-aa2e-d4edb253e15a', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 9, 9, 'አትስገድላቸው፤ አታምልካቸውም፤ እኔ እግዚአብሔር አምላክህ ቀናተኛ አምላክ ነኝና፤ በሚጠሉኝ እስከ ሦስተኛና እስከ አራተኛ ትውልድ ድረስ የአባቶችን ኀጢአት በልጆች ላይ የማመጣ፤'),
  ('b85babdc-bc14-5232-a1f9-9864df366357', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 10, 10, 'ለሚወድዱኝ፥ ትእዛዜንም ለሚጠብቁ እስከ ሺህ ትውልድ ድረስ ምሕረትን የማደርግ።'),
  ('5caf8cf5-5a2f-5e27-a82f-ef07812eb8bc', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 11, 11, '“የእግዚአብሔርን የአምላክህን ስም በሐሰት አትጥራ፤ እግዚአብሔር ስሙን በሐሰት የሚጠራውን ከበደል አያነጻውምና።'),
  ('da872162-fde3-5abf-a4d7-dcbdc5e6de53', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 12, 12, '“ዕለተ ሰንበትን ጠብቅ፤ እግዚአብሔር አምላክህ እንዳዘዘህም ቀድሳት።'),
  ('3466c3fd-c540-53ee-aa39-4c14705b2c86', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 13, 13, 'ስድስት ቀን ሥራ፤ ተግባርህንም ሁሉ አድርግ፥'),
  ('51258943-78a1-5334-ade6-7452dc3d4211', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 14, 14, 'ሰባተኛው ቀን ግን ለእግዚአብሔር ለአምላክህ ሰንበት ነው፤ አንተ እንደምታርፍ ሎሌህና ገረድህ ያርፉ ዘንድ፥ አንተ፥ ወንድ ልጅህም፥ ሴት ልጅህም፥ ሎሌህም፥ ገረድህም፥ በሬህም፥ አህያህም፥ ከብትህም ሁሉ፥ በደጆችህም ውስጥ ያለ መጻተኛ በእርሱ ምንም ሥራ አትሥሩ።'),
  ('b01bff0d-6f51-5976-adef-41bdf45c6aac', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 15, 15, 'አንተም በግብፅ ባሪያ እንደ ነበርህ አስብ፤ እግዚአብሔር አምላክህ በጸናች እጅና በተዘረጋ ክንድ ከዚያ አወጣህ፤ ስለዚህ እግዚአብሔር አምላክህ ዕለተ ሰንበትን ትጠብቃትና ትቀድሳት ዘንድ አዘዘህ።'),
  ('243b94e7-6fcd-5e5e-af3d-980dccdfefb2', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 16, 16, 'እግዚአብሔር አምላክህ እንዳዘዘህ አባትህንና እናትህን አክብር፤ እግዚአብሔር አምላክህ በሚሰጥህ ምድር ላይ ዕድሜህ እንዲረዝም፥ መልካምም እንዲሆንልህ።'),
  ('99aa0774-66e4-5a84-a098-7707714ccf24', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 17, 17, '“አታመንዝር።'),
  ('8dcf34ba-fb35-5ddb-a7f4-4c2b0f5c6698', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 18, 18, '“ነፍስ አትግደል።'),
  ('0820f85b-07fe-5441-a25a-210024b74e76', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 19, 19, '“አትስረቅ።'),
  ('fc19aaa2-5223-5c8b-af31-e0bf5a71fa17', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 20, 20, '“በባልንጀራህ ላይ በሐሰት አትመስክር፤ ምስክርንም አታሳብል።'),
  ('4c6eb049-efab-5621-aa2b-e704d5f2a5df', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 21, 21, '“የባልንጀራህን ሚስት አትመኝ፤ የባልንጀራህንም ቤት፥ እርሻውንም፥ ሎሌውንም፥ ገረዱንም፥ በሬውንም፥ አህያውንም፥ ከባልንጀራህ ገንዘብ ሁሉ ማናቸውንም አትመኝ።'),
  ('f800177b-2148-5b79-ab05-5af5f7491374', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', '1dfa064f-2c8d-5685-a219-ba0c99ece589', 22, 22, '“እግዚአብሔር በተራራው ላይ፤ በእሳትና በጨለማ፥ በጭጋግና በዓውሎ ነፋስ መካከል ሆኖ በታላቅ ድምፅ እነዚህን ቃሎች ለጉባኤያችሁ ሁሉ ተናገረ፤ ምንም አልጨመረም። በሁለቱም የድንጋይ ጽላት ላይ ጻፋቸው፤ ለእኔም ሰጣቸው።'),
  ('8c630b48-d66a-576c-a6a1-eba1711869b9', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 1, 23, '“እንዲህም ሆነ፤ በእሳት መካከል ድምፁን በሰማችሁ ጊዜ፥ ተራራውም በእሳት ሲነድድ እናንተ፥ የነገዶቻችሁ አለቆች፥ ሽማግሌዎቻችሁም፥ ወደ እኔ ቀረባችሁ፤'),
  ('2e2546f9-aa71-5475-aaf7-3ddaa21a2798', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 2, 24, 'አላችሁም፦ እነሆ፥ አምላካችን እግዚአብሔር ክብሩንና ታላቅነቱን አሳይቶናል፤ ከእሳቱም መካከል ድምፁን ሰምተናል፤ እግዚአብሔርም ከሰው ጋር ሲነጋገር፥ ሰውዬው በሕይወት ሲኖር ዛሬ አይተናል።'),
  ('ad7111ab-3d8a-5abb-afb4-b29da1688385', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 3, 25, 'አሁንም አንሙት፤ ይህችም ታላቅ እሳት አታጥፋን፤ እኛ የአምላካችን የእግዚአብሔርን ድምፅ ዳግመኛ ብንሰማ እንሞታለን።'),
  ('2d35bf16-6f18-5aa1-ab67-bec5912e0cee', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 4, 26, 'ከሥጋ ለባሽ ሁሉ እኛ እንደ ሰማን በእሳት መካከል ሆኖ ሲናገር የሕያው አምላክን ድምፅ ሰምቶ በሕይወት የኖረ ማን ነው?'),
  ('e49049c3-5f30-547f-a341-c588dd474a08', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 5, 27, 'አንተ ቅረብ፤ አምላካችን እግዚአብሔር የሚለውን ሁሉ ስማ፤ እምላካችን እግዚአብሔርም ለአንተ የሚናገረውን ሁሉ ለእኛ ንገረን፤ እኛም ሰምተን እናደርገዋለን።'),
  ('fae8a902-cad1-50c9-a759-4ad9818a54a0', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 6, 28, '“በተናገራችሁኝም ጊዜ እግዚአብሔር የእናንተን ቃል ድምፅ ሰማ፤ እግዚአብሔርም አለኝ፦ ይህ ሕዝብ የተናገሩህን ቃል ድምፅ ሰምቼአለሁ፤ የተናገሩህ ሁሉ ትክክል ነው።'),
  ('baa868d4-5446-5a98-a3ba-e969c56ccd60', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 7, 29, 'ለእነርሱ፥ ለዘለዓለምም ለልጆቻቸው መልካም ይሆንላቸው ዘንድ፥ እንዲፈሩኝ፥ ሁልጊዜም ትእዛዜን ሁሉ እንዲጠብቁ እንዲህ ያለ ልብ ማን በሰጣቸው፥'),
  ('ca864cd2-b039-50b0-a815-1ba024427135', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 8, 30, 'ሄደህ፦ ወደ ቤቶቻችሁ ተመለሱ በላቸው።'),
  ('e53c2091-6b8d-5b87-a80d-7368f1af9702', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 9, 31, 'አንተ ግን በዚህ በእኔ ዘንድ ቁም፤ ርስት አድርጌ በምሰጣቸው ምድር ላይ ያደርጉአት ዘንድ የምታስተምራቸውን ትእዛዜንና ሥርዐቴን፥ ፍርዴንም ሁሉ እነግርሃለሁ።'),
  ('f48c0e39-c9bb-5f30-a2f5-5134cb82eeb4', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 10, 32, 'እግዚአብሔርም አምላካችሁ እንዳዘዛችሁ ታደርጉ ዘንድ ጠብቁ፤ ከእርሱም ወደ ቀኝም ወደ ግራም ፈቀቅ አትበሉ።'),
  ('9ad9ad01-0b09-5b14-aef6-d197379947e3', 'd43a2654-f938-5290-acd5-46f8f7f2fddb', 'a6d1b976-f430-59e1-aeb0-8e03dd504dc0', 11, 33, 'በሕይወት እንድትኖሩ፥ መልካምም እንዲሆንላችሁ፥ በምትወርሱአትም ምድር ዕድሜአችሁ እንዲረዝም፥ እግዚአብሔር አምላካችሁ ባዘዛችሁ መንገድ ሁሉ ሂዱ።”'),
  ('b306e6bd-3e43-5140-a4ed-cf00635a4cce', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 1, 1, '“ልትወርሱአት በምትገቡባት ምድር ታደርጉት ዘንድ አምላካችሁ እግዚአብሔር እንዳስተምራችሁ ያዘዘው ትእዛዝና ሥርዐት፥ ፍርድም ይህ ነው።'),
  ('11195fa6-f6be-5c73-af06-f754ee9fb69f', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 2, 2, 'እናንተ፥ ልጆቻችሁም፥ የልጅ ልጆቻችሁም በዕድሜአችሁ ሁሉ አምላካችሁን እግዚአብሔርን ፈርታችሁ እኔ ለእናንተ ያዘዝሁትን ሥርዐቱንና ትእዛዙን ሁሉ ትጠብቁ ዘንድ፥ ዕድሜአችሁም ይረዝም ዘንድ፤'),
  ('d13bd931-30ca-545e-a925-bae651d53c69', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 3, 3, 'እስራኤል ሆይ፥ ስማ፦ ማርና ወተት የምታፈስሰውን ምድር ይሰጥህ ዘንድ የአባቶችህ አምላክ እግዚአብሔር እንደ ተናገረ እጅግ እንድትበዛ፥ መልካምም እንዲሆንልህ ታደርጋት ዘንድ ጠብቅ።” ከግብፅ ምድር ከወጡ በኋላ ሙሴ ለእስራኤል ልጆች በምድረ በዳ ያዘዛቸው ሥርዐትና ፍርድ ሁሉ ይህ ነው።'),
  ('00534830-0efe-5712-ae4b-5878ed61836c', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 4, 4, '“እስራኤል ሆይ፥ ስማ፤ አምላካችን እግዚአብሔር አንድ እግዚአብሔር ነው፤'),
  ('1c5411dd-b1c0-5ad2-a43f-78d3356c7b6a', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 5, 5, 'አምላክህንም እግዚአብሔርን በፍጹም ልብህ፥ በፍጹምም ነፍስህ፥ በፍጹምም ኀይልህ ውደድ።'),
  ('ce3cedc9-e4c5-5be5-ab52-06046eb348ae', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 6, 6, 'እኔም ዛሬ አንተን የማዝዘውን ይህን ቃል በልብህ፥ በነፍስህም ያዝ።'),
  ('20a74027-2740-5d2f-a1a4-317bc4689c95', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 7, 7, 'ለልጆችህም አስተምረው፤ በቤትህም ስትቀመጥ፥ በመንገድም ስትሄድ፥ ስትተኛም፥ ስትነሣም አስተምረው።'),
  ('c1aaf23b-4c6a-525c-a8fd-466181f21d66', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 8, 8, 'በእጅህም እንደ ምልክት አድርገው፤ በዐይኖችህም መካከል እንደማይንቀሳቀስ ይሁንልህ።'),
  ('3e355400-b3df-5506-af17-ca57c5130158', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'b1a27a98-6017-52df-ae5b-32ed20258716', 9, 9, 'በቤትህም መቃኖች፥ በደጃፍህም በሮች ላይ ጻፈው።'),
  ('f205a4ae-4fc2-5e7f-aece-cd05b218d95a', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 1, 10, '“አምላክህ እግዚአብሔር ለአንተ ሊሰጣት ለአባቶችህ ለአብርሃምና ለይስሐቅ፥ ለያዕቆብም ወደ ማለላቸው ምድር ባገባህ ጊዜ፤ ያልሠራሃቸውንም ታላቅና መልካም ከተሞች፥'),
  ('0bd50145-8275-53c3-a2b2-b2bdec92a81b', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 2, 11, 'ያልሞላሃቸውንም ሀብትን የሞሉ ቤቶች፥ ያልማስሃቸውንም የተማሱ ጕድጓዶች፥ ያልተከልሃቸውንም ወይንና ወይራ በሰጠህ ጊዜ፥ በበላህና በጠገብህም ጊዜ፤'),
  ('e95c441e-27b7-5a96-a013-e9d5f249232c', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 3, 12, 'ከግብፅ ምድር ከባርነት ቤት ያወጣህን እግዚአብሔርን እንዳትረሳ ተጠንቀቅ።'),
  ('27803f6d-8cc0-5fdc-aa82-95e242a15a40', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 4, 13, 'አምላክህን እግዚአብሔርን ፍራ፤ እርሱንም ብቻ አምልክ፤ እርሱንም ተከተል በስሙም ማል።'),
  ('3b41d7b1-b3bc-5461-a85c-2402e637309b', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 5, 14, 'በዙሪያችሁ ያሉት አሕዛብ የሚያመልኩአቸውን ሌሎች አማልክት አትከተሉ።'),
  ('ed160226-0441-588c-aad2-f661611a4b90', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 6, 15, 'በመካከልህ ያለው አምላክህ እግዚአብሔር ቀናተኛ አምላክ ነውና የአምላክህ የእግዚአብሔር ቁጣ እንዳይነድድብህ፥ ከምድርም ፊት እንዳያጠፋህ ተጠንቀቅ።'),
  ('0004bbce-a66b-5a26-a5a5-b61564b56d06', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 7, 16, '“በፈተና ቀን እንደ ፈተንኸው አምላክህ እግዚአብሔርን አትፈታተነው።'),
  ('b9172d4d-fe28-5a04-a7f4-42123e595b88', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 8, 17, 'ለአንተ ያዘዘውን የአምላክህን የእግዚአብሔርን ትእዛዝ፥ ምስክሩንም፥ ሥርዐቱንም አጥብቀህ ጠብቅ።'),
  ('c7f333e0-f4a3-59d1-a615-370cca5ab8ba', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 9, 18, 'መልካምም ይሆንልህ ዘንድ፥ እግዚአብሔርም ለአባቶችህ ወደ ማለላቸው ወደ መልካሚቱ ምድር ገብተህ እርስዋን ትወርስ ዘንድ በእግዚአብሔር ፊት ቅኑንና መልካሙን አድርግ።'),
  ('4a57b5ae-8f68-5d33-a413-777a7e7bf134', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 10, 19, 'እግዚአብሔር እንደ ተናገረ ጠላቶችህን ሁሉ ከፊትህ ያሳድድልህ ዘንድ።'),
  ('91f0e910-ebe4-5c78-a9ca-6274be88474d', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 11, 20, '“ነገ ልጅህ፦ አምላካችን እግዚአብሔር ያዘዛችሁ ምስክርና ሥርዐት፥ ፍርድስ ምንድን ነው? ብሎ በጠየቀህ ጊዜ፥'),
  ('87c49a94-f943-5606-a151-b9ed2b650f04', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 12, 21, 'አንተ ልጅህን በለው፦ በግብፅ የፈርዖን ባሪያዎች ነበርን፤ እግዚአብሔርም በጽኑ እጅ፥ በተዘረጋችም ክንድ ከዚያ አወጣን፤'),
  ('dd818033-814a-52ad-adb9-a78fc0275d33', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 13, 22, 'እግዚአብሔርም በግብፅና በፈርዖን በቤቱም ሁሉ ላይ በፊታችን ታላቅና ክፉ ምልክት፥ ተአምራትም አደረገ።'),
  ('eb07b5b3-15ef-562f-a67f-03781ad63cdf', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 14, 23, 'ለአባቶቻችን ወደ ማለላቸው ምድር ያገባንና እርስዋን ይሰጠን ዘንድ እኛን ከዚያ አወጣን።'),
  ('d92c3484-3fb3-54d9-a3e8-eb85dcb6e681', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 15, 24, 'እንደ ዛሬም በሕይወት እንዲያኖረን፥ ሁልጊዜም መልካም እንዲሆንልን፥ አምላካችንን እግዚአብሔርን እንፈራ ዘንድ፥ ይህችንም ሥርዐት ሁሉ እናደርግ ዘንድ እግዚአብሔር አዘዘን።'),
  ('cd58d364-7043-5949-a613-1d08147c10fa', '56f4e7b5-60b9-5a43-a1e7-e38826112625', 'ef06c739-7784-52c2-a2f2-28fca3a6237d', 16, 25, 'እግዚአብሔርም እንዳዘዘን በአምላካችን በእግዚአብሔር ፊት እናደርጋት ዘንድ ይህችን ትእዛዝ ሁሉ ብንጠብቅ ለእኛ ምሕረት ይሆንልናል።”'),
  ('289ff885-02f2-50d2-a151-674cd1103c73', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 1, 1, '“አምላክህ እግዚአብሔር ልትወርሳት ወደምትገባባት ምድር ባመጣህ ጊዜ፥ ከፊትህም ብዙና ታላላቅ አሕዛብን፥ ከአንተ የበለጡትን፥ የበረቱትንም ሰባቱን አሕዛብ፥ ኬጤዎናዊውን፥ ጌርጌሴዎናዊውንም፥ አሞሬዎናዊውንም፥ ከነዓናዊውንም፥ ፌርዜዎናዊውንም፥ ኤዌዎናዊውንም፥ ኢያቡሴዎናዊውንም ባወጣ ጊዜ፥'),
  ('14d7bbda-6a21-5131-a953-37acf6b6f6a6', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 2, 2, 'አምላክህ እግዚአብሔርም በእጅህ አሳልፎ በሰጣቸውና በመታሃቸው ጊዜ፥ ፈጽመህ አጥፋቸው፤ ከእነርሱም ጋር ቃል ኪዳን አታድርግ፤ አትማራቸውም፤'),
  ('497692e4-6436-53af-a196-bbd0b8c4ad7a', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 3, 3, 'ከእነርሱም ጋር አትጋባ፤ ሴት ልጅህን ለወንድ ልጁ አትስጥ፥ ሴት ልጁንም ለወንድ ልጅህ አትውሰድ።'),
  ('a541ab0b-66f0-5181-ad28-35a87cec7890', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 4, 4, 'ልጅህን ከእኔ ያርቀዋልና፤ ሌሎችን አማልክትም ያመልካልና። የእግዚአብሔርም ቍጣ ይነድድባችኋል፤ ፈጥኖም ያጠፋችኋል።'),
  ('ffca2c43-d4c5-53ed-abe0-45d6f344450b', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 5, 5, 'ነገር ግን እንዲህ አድርጉባቸው፤ መሠዊያቸውን አፍርሱ፤ ሐውልቶቻቸውንም ሰባብሩ፥ የማምለኪያ ዐፀዶቻቸውንም ቍረጡ፥ የአማልክቶቻቸውንም ምስል በእሳት አቃጥሉ።'),
  ('e3f0a0f4-abc0-50f3-a8e3-f0810f5e927e', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 6, 6, '“ለአምላክህ ለእግዚአብሔር አንተ ቅዱስ ሕዝብ ነህና፤ በምድር ፊት ከሚኖሩ አሕዛብ ሁሉ ይልቅ ለእርሱ ለራሱ ሕዝብ ትሆንለት ዘንድ አምላክህ እግዚአብሔር መርጦሃልና።'),
  ('004d0bfc-6d7c-5314-af92-b18ad3b6ec8c', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 7, 7, 'እግዚአብሔርም የወደዳችሁና የመረጣችሁ፥ ከአሕዛብ ሁሉ ስለ በዛችሁ አይደለም፤ እናንት ከአሕዛብ ሁሉ ጥቂቶች ነበራችሁና፤'),
  ('788bfbd5-dded-5fce-ac32-5a0fc3f6d597', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 8, 8, 'ነገር ግን እግዚአብሔር ስለ ወደዳችሁ፥ ለአባቶቻችሁም የማለላቸውን መሐላ ስለ ጠበቀ፥ ስለዚህ እግዚአብሔር በጽኑ እጅ፥ በተዘረጋችም ክንድ አወጣችሁ፤ ከባርነትም ቤት ከግብፅ ንጉሥ ከፈርዖን እጅ አዳናችሁ።'),
  ('dd0b750d-1f25-5f24-aef4-796a45aef899', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 9, 9, 'አንተም አምላክህ እግዚአብሔር እርሱ አምላክ እንደ ሆነ፥ ለሚወድዱትም፥ ትእዛዙንም ለሚጠብቁ ቃል ኪዳኑንና ምሕረቱን እስከ ሺህ ትውልድ ድረስ የሚጠብቅ የታመነ አምላክ እንደ ሆነ ዕወቅ፤'),
  ('c84e4178-997b-5687-a6c7-cb2aaec6e0c7', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 10, 10, 'የሚጠሉትን ለማጥፋት በፊታቸው ብድራት ይመልስባቸዋል፤ ለሚጠላው አይዘገይም፤ ነገር ግን በፊቱ ብድራትን ይመልስበታል።'),
  ('7dc6085b-be14-5734-acdb-8dbd0b8d3933', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '108e3302-ca93-5fb0-a1ec-06fcd5f8f471', 11, 11, 'እንግዲህ ታደርጓት ዘንድ እኔ ዛሬ ለእናንተ የማዝዛትን ትእዛዝና ሥርዐት፥ ፍርድንም ጠብቁ።'),
  ('7830f356-176d-55de-a025-2af3dfbaaaec', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 1, 12, '“እንዲህም ይሆናል፤ ይህችን ፍርድ ሰምታችሁ ብትጠብቋት፥ ብታደርጓትም፥ አምላካችሁ እግዚአብሔር ለአባቶቻችሁ የማለውን ቃል ኪዳንና ምሕረት ለእናንተ ይጠብቅላችኋል፤'),
  ('7dc39854-7ada-5785-a9b5-7c47aac0def7', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 2, 13, 'ይወድድህማል፤ ይባርክህማል፤ ያባዛህማል፤ ይሰጥህም ዘንድ ለአባቶችህ በማለላቸው ምድር የሆድህን ፍሬ፥ የመሬትህንም ፍሬ፥ እህልህን፥ ወይንህንም፥ ዘይትህንም፥ የከብትህንም ብዛት፥ የበግህንም መንጋ ይባርክልሃል።'),
  ('d55e5050-4c55-5f77-a86d-e9a6db1e2c7e', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 3, 14, 'ከአሕዛብም ሁሉ ይልቅ የተባረክህ ትሆናለህ፤ ከሴቶችህ መካን አትኖርም፤ ልጆች የሌሏት አገልጋይም አትኖርም፤ ከከብትህም መካን አይኖርም።'),
  ('a9bf4123-f613-52b1-adaa-4689a4853d59', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 4, 15, 'በግብፃውያን ላይ ሲመጣ ያየኸውን ክፉ ሕማምና ደዌ ሁሉ እግዚአብሔር ከአንተ ያርቅልሃል፤ ያየኸውንም መከራ ሁሉ ወደ አንተ አያመጣውም፤ ከአንተም በሚጠሉህ ሁሉ ላይ ይመልሰዋል።'),
  ('8cb266ee-186a-5afd-a0d2-f295985b1ae8', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 5, 16, 'አምላክህም እግዚአብሔር የሚሰጥህን የአሕዛብ ምርኮ ትበላለህ፤ ዐይንህም አታዝንላቸውም፤ ያም ለአንተ ክፉ ይሆንብሃልና አማልክቶቻቸውን አታምልካቸው።'),
  ('a5e4e39d-5dc3-5475-a1e0-40bc497c81a1', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 6, 17, '“በልብህም፦ እነዚህ አሕዛብ ከእኔ ይልቅ ይበዛሉና አወጣቸው ዘንድ እንዴት እችላለሁ? ብለህ፥ አትፍራቸው፤'),
  ('f837e765-3e90-5819-a03c-fae5c1ae3fac', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 7, 18, 'ነገር ግን አምላክህ እግዚአብሔር በፈርዖንና በግብፃውያን ሁሉ ያደረገውን ፈጽመህ አስብ፤'),
  ('13d6c43c-45f8-56a3-ae5e-88b64547e1e7', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 8, 19, 'አምላክህ እግዚአብሔር ዓይንህ እያየች፥ ታላቅ መቅሠፍትን፥ ምልክትንም፥ ተአምራትንም፥ የጸናችውንም እጅ፥ የተዘረጋውንም ክንድ አድርጎ እንዳወጣህ፤ እንዲሁ አምላክህ እግዚአብሔር አንተ በምትፈራቸው በአሕዛብ ሁሉ ላይ ያደርጋል።'),
  ('99378730-1af4-563c-ad6a-781842926d65', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 9, 20, 'ደግሞም አምላክህ እግዚአብሔር የቀሩት፥ ከፊትህም የተሸሸጉት እስኪጠፉ ድረስ መቅሠፍትን ይልክባቸዋል።'),
  ('67e4a610-ffa9-5247-a5b4-e21f41e32559', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 10, 21, 'ከፊታቸው አትደንግጥ፤ አምላክህ እግዚአብሔር፥ ከአንተ ጋር ነውና፥ እርሱም አምላክህ እግዚአብሔር ታላቅና ጽኑዕ ነውና።'),
  ('80e0958e-60f7-57db-a27d-5dfa0ad09f10', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 11, 22, 'አምላክህም እግዚአብሔር እነዚህን አሕዛብ በጥቂት በጥቂቱ ከፊትህ ያጠፋቸዋል፤ ምድርም ምድረ በዳ እንዳትሆን የምድረ በዳ አራዊትም እንዳይበዙብህ ፈጥኜ አጠፋቸዋለሁ አትበል።'),
  ('50ef5431-98e3-55ce-a9f8-e690fc3d6093', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 12, 23, 'አምላክህ እግዚአብሔር ግን እነርሱን በእጅህ አሳልፎ ይሰጣቸዋል፥ እስኪጠፉም ድረስ በታላቅ ውርደት ይደመስሳቸዋል።'),
  ('b871532d-7d93-5f0a-a380-3f6261f002f3', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 13, 24, 'ነገሥታቶቻቸውንም በእጅህ አሳልፎ ይሰጣቸዋል፤ ስማቸውንም ከዚያ ቦታ ያጠፋል፤ እስክታጠፋቸው ድረስ ማንም ከፊትህ ይቆም ዘንድ አይችልም።'),
  ('faa300a6-7de1-5841-a040-119e8c3b59df', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 14, 25, 'የአምላኮቻቸውን ምስል በእሳት ታቃጥላለህ፤ ከእነርሱም የተሠራባቸውን ብርንና ወርቅን፥ አትመኝ፤ በአምላክህም በእግዚአብሔር ዘንድ ርኩስ ነውና እንዳትበድልበት ከእርሱ ምንም አትውሰድ።'),
  ('ddae913a-1228-5896-a2c8-11aac003ff2f', 'dcf35a7c-6da1-5244-aa59-45aa67bee706', '066b18b7-6d33-52dc-a288-31204b739d28', 15, 26, 'ርኩስን ነገር ወደ ቤትህ አታግባ፤ እንደ እርሱም ርጉም ትሆናለህ፤ ርጉም ነውና መጸየፍን ተጸየፈው፤ መጥላትንም ጥላው።'),
  ('838ae019-9aaa-5343-aa06-6924e68a8906', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 1, 1, '“በሕይወት እንድትኖሩ፥ እንድትበዙም፥ እግዚአብሔርም ለአባቶቻችሁ ወደ ማለላቸው ምድር ገብታችሁ እንድትወርሱአት፥ ዛሬ ለአንተ የማዝዘውን ትእዛዝ ሁሉ ታደርጉ ዘንድ ጠብቁ።'),
  ('da91ddb4-a62c-502e-a659-ebce7a8b58a5', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 2, 2, 'አምላክህ እግዚአብሔር ይፈትንህ ዘንድ፥ በልብህም ያለውን ትእዛዙን ትጠብቅ ወይም አትጠብቅ እንደ ሆነ ያውቅ ዘንድ፥ ሊያስጨንቅህ በምድረ በዳ የመራህን መንገድ ሁሉ አስብ።'),
  ('f5a2977b-48c1-554b-addf-65bd0c0c83a1', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 3, 3, 'ሰውም ከእግዚአብሔር አፍ በሚወጣ ነገር ሁሉ በሕይወት እንዲኖር እንጂ ሰው በእንጀራ ብቻ በሕይወት እንዳይኖር ያስታውቅህ ዘንድ አስጨነቀህ፥ አስራበህም፤ አንተም ያላወቅኸውን፥ አባቶችህም ያላወቁትን መና መገበህ።'),
  ('802a438c-6b83-50e4-a22b-c17de74a9bd7', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 4, 4, 'የለበስኸው ልብስ አላረጀም፤ እግርህም አልነቃም፤ እነሆ፥ አርባ ዓመት ሆነ።'),
  ('d7b16899-852e-5a2b-a4fb-f7cd69b60a44', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 5, 5, 'ሰውም ልጁን እንደሚገሥጽ እንዲሁ አምላክህ እግዚአብሔር አንተን እንዲገሥጽ በልብህ ዕወቅ።'),
  ('f1ea158b-55d0-5dd3-a070-fac8ef3b76d6', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 6, 6, 'በመንገዱም እንድትሄድ፥ እርሱንም እንድትፈራ የአምላክህን የእግዚአብሔርን ትእዛዝ ጠብቅ።'),
  ('b88b9333-3db4-5d30-a34f-68c7b4de4f7b', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 7, 7, 'አምላክህ እግዚአብሔር ወደ መልካምና ሰፊ ምድር፥ ከሜዳና ከተራሮች የሚመነጩ የውኃ ጅረቶችና ፈሳሾችም ወዳሉባት ምድር፥'),
  ('5008102e-6530-5ee2-a1be-b19bd16f019d', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 8, 8, 'ስንዴ፥ ገብስም፥ ወይንም፥ በለስም፥ ሮማንም ወደ ሞሉባት፥ ወይራም፥ ቅቤም፥ ማርም ወደ ሞሉባት ምድር፥'),
  ('f4fbdf5a-f0a2-5f96-a796-bd3d26f9ff93', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 9, 9, 'ሳይጐድልህ እንጀራን ወደምትበላባት፥ አንዳችም ወደማታጣባት ምድር፥ ድንጋይዋ ብረት ወደ ሆነ፥ ከተራራዋም መዳብ ወደሚማስባት ምድር ያገባሃል።'),
  ('b27b3b7b-2e36-5116-a5cd-1db8847ce3af', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', '4561e2ec-3399-59f7-a2e8-f081fa8adbef', 10, 10, 'ትበላማለህ፤ ትጠግብማለህ፤ ስለ ሰጠህም ስለ መልካሚቱ ምድር አምላክህን እግዚአብሔርን ታመሰግናለህ።'),
  ('b8545280-1d38-5158-a45f-fb92eff5146e', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 1, 11, '“ዛሬ እኔ አንተን የማዝዘውን ትእዛዙንና ፍርዱን፥ ሥርዐቱንም ባለመጠበቅ አምላክህን እግዚአብሔርን እንዳትረሳ ተጠንቀቅ፤'),
  ('a2923074-86fb-5fea-a832-ca50353beb41', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 2, 12, 'ከበላህና ከጠገብህ በኋላ፥ መልካምም ቤት ሠርተህ ከተቀመጥህባት በኋላ፤'),
  ('5f279150-fdb4-53a1-ae07-021d0a9c7a27', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 3, 13, 'የላምና የበግ መንጋ ከበዛልህ በኋላ፥ ብርህና ወርቅህም፥ ያለህም ሁሉ ከበዛልህ በኋላ፥ ልብህ እንዳይታበይ፤'),
  ('8c75adac-5d17-5624-a979-b82d7497c2f7', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 4, 14, 'ከግብፅ ምድር ከባርነት ቤት ያወጣህን፥'),
  ('0aedbb97-2eed-55b6-a0fe-664076366445', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 5, 15, 'የሚናደፍ እባብና ጊንጥ፥ ጥማትም ባለባት፥ ውኃም በሌለባት፥ በታላቂቱና በምታስፈራው ምድረ በዳ የመራህን፥ ከጭንጫ ድንጋይም ጣፋጭ ውኃን ያወጣልህን፥'),
  ('e487c4b1-6040-5742-a13b-c543123aeece', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 6, 16, 'በመጨረሻም ዘመን መልካም ያደርግልህ ዘንድ ሊፈትንህ፥ ሊያዋርድህም አባቶችህ ያላወቁትን መና በምድረ በዳ የመገበህን አምላክህን እግዚአብሔርን እንዳትረሳ፥'),
  ('ed59858c-4bf4-59b1-a5b7-97b6bdfacfe1', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 7, 17, 'በልብህም፦ በጕልበቴ፥ በእጄም ብርታት ይህን ሁሉ ታላቅ ኀይል አደረግሁ እንዳትል።'),
  ('d0090a36-06ab-5687-a168-bb2e3c5401ad', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 8, 18, 'ነገር ግን ዛሬ እንደ ሆነ ለአባቶችህ የማለውን ቃል ኪዳን ያጸና ዘንድ እርሱ ኀይልን ስለሚሰጥህ አምላክህን እግዚአብሔርን አስበው።'),
  ('abebd5e8-14ae-5551-acc0-f05b63f905f9', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 9, 19, 'አምላክህንም እግዚአብሔርን ፈጽሞ ብትረሳ፥ ሌሎችንም አማልክት ብትከተል፥ ብታመልካቸውም፥ ብትሰግድላቸውም፥ ፈጽሞ እንደምትጠፋ እኔ ዛሬውኑ ሰማይንና ምድርን አስመሰክርብሃለሁ።'),
  ('ec6f1ba8-a1ed-5aa5-a800-38bf07e976c7', 'cfd415fc-fc74-5052-ae0a-b06f08ccb694', 'fd894299-77bf-561e-a8df-b4a8a358e023', 10, 20, 'የአምላካችሁን የእግዚአብሔርን ቃል ስለ አልሰማችሁ እግዚአብሔር ከፊታችሁ እንደሚአጠፋቸው እንደ አሕዛብ ሁሉ እናንተም እንዲሁ ትጠፋላችሁ።'),
  ('215bc731-5c00-5241-a070-f5946edbdd6c', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 1, 1, '“እስራኤል ሆይ፥ ስማ፤ ከአንተ የበለጡትንና የበረቱትን አሕዛብ፥ የቅጽራቸው ግንብ እስከ ሰማይ የሚደርስ ታላላቆች ከተሞችን ለመውረስ ትገቡ ዘንድ ዛሬ ዮርዳኖስን ትሻገረዋለህ።'),
  ('8a7d7d27-93af-5cab-a658-b2818815cf51', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 2, 2, 'አንተም የምታውቃቸው፥ ስለ እነርሱም፦ በዔናቅ ልጆች ፊት መቆም ማን ይችላል? ሲባል የሰማኸው ታላቅ፥ ብዙና ረዥም ሕዝብ የዔናቅ ልጆች ናቸው።'),
  ('3d7b96f8-06ee-5bb9-abc9-76df427a8ec0', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 3, 3, 'አምላክህም እግዚአብሔር በፊትህ እንዲያልፍ ዛሬ ዕወቅ፤ እርሱ የሚበላ እሳት ነው፤ እርሱ ያጠፋቸዋል፤ በፊትህም ያዋርዳቸዋል፤ እግዚአብሔርም እንደ ነገረህ ከፊትህ ያርቃቸዋል፥ ፈጥኖም ያጠፋቸዋል።'),
  ('238887b8-25ec-5f27-a3a8-83d61e3c68f9', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 4, 4, 'አምላክህ እግዚአብሔር እነዚያን አሕዛብ ከፊትህ ባወጣቸው ጊዜ፦ ስለ ጽድቄ እወርሳት ዘንድ ወደዚች መልካም ምድር እግዚአብሔር አገባኝ ብለህ በልብህ አትናገር፤'),
  ('c3b44b4f-d5a2-58a2-a84e-2dca1c53d3d1', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 5, 5, 'ምድራቸውን ትወርሳት ዘንድ የምትገባው ስለ ጽድቅህና ስለ ልብህ ቅንነት አይደለም፤ ነገር ግን አምላክህ እግዚአብሔር ከፊትህ በሚያጠፋቸው በእነዚያ አሕዛብ ኀጢአት ምክንያትና ለአባቶችህ ለአብርሃምና ለይስሐቅ ለያዕቆብም የማለላቸውን ቃል ያጸና ዘንድ ነው።'),
  ('879164e5-f8ba-5826-ac73-97b9ec954f9e', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 6, 6, 'እንግዲህ አንተ አንገተ ደንዳና ሕዝብ ነህና አምላክህ እግዚአብሔር ይህችን መልካም ምድር ርስት አድርጎ የሰጠህ ስለ ጽድቅህ እንዳይደለ ዛሬ ዕወቅ።'),
  ('d2d6d283-9d3b-57fc-adbc-80399959f35d', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 7, 7, '“አምላክህን እግዚአብሔርን በምድረ በዳ ምን ያህል እንዳሳዘንኸው፥ ከግብፅ ሀገር ከወጣህበት ቀን ጀምሮ ወደዚህ ስፍራ እስከ መጣችሁ ድረስ በእግዚአብሔር ላይ እንዳመፃችሁ አስብ፤ አትርሳም።'),
  ('94347d7b-d855-5bb9-a7fe-4c58e36d927a', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 8, 8, 'በኮሬብ ደግሞ እግዚአብሔርን አሳዘናችሁት፤ እግዚአብሔርም ሊያጠፋችሁ በእናንተ ላይ ተቈጣ።'),
  ('9b0ceed6-bd74-51d2-afb8-cab76ceea2b6', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 9, 9, 'ሁለቱን የድንጋይ ጽላት፥ እግዚአብሔር ከእናንተ ጋር የተማማለባቸውን የቃል ኪዳን ጽላት እቀበል ዘንድ ወደ ተራራ በወጣሁ ጊዜ፥ በተራራው አርባ ቀንና አርባ ሌሊት ተቀምጬ ነበር፤ እንጀራ አልበላሁም፤ ውኃም አልጠጣሁም።'),
  ('b2a736c8-3c34-5cce-adf6-3b0465209b6f', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 10, 10, 'እግዚአብሔርም በእግዚአብሔር ጣት የተጻፉትን ሁለት የድንጋይ ጽላት ሰጠኝ፤ በተሰበሰባችሁ ጊዜ እግዚአብሔር በተራራው ላይ የነገረኝ ቃል ሁሉ ተጽፎባቸው ነበር።'),
  ('b69fd233-cdbb-518d-a889-1c21c5e2d221', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 11, 11, 'ከአርባ ቀንና ከአርባ ሌሊትም በኋላ እግዚአብሔር ሁለቱን የድንጋይ ጽላት፥ የቃል ኪዳኑን ጽላት ሰጠኝ።'),
  ('4706bc43-324e-533f-ad81-e7eaa62bd0b2', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 12, 12, 'እግዚአብሔርም አለኝ፦ ተነሥተህ ከዚህ ፈጥነህ ውረድ፤ ከግብፅ ያወጣሃቸው ሕዝብህ በድለዋልና፤ ፈጥነው ካዘዝኋቸው መንገድ ፈቀቅ ብለዋልና፥ ቀልጦ የተሠራ ምስልም ለራሳቸው አድርገዋልና።'),
  ('976b68a0-b929-5993-a784-dbb418dfd1f0', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 13, 13, 'እግዚአብሔርም አለኝ፦ ‘አንድ ጊዜም ሁለት ጊዜም እንዲህ ብዬ ነገርሁህ፤ ይህ ሕዝብ አንገተ ደንዳና ሕዝብ እንደ ሆነ አይችአለሁ፤'),
  ('28f7a3cd-eb80-574a-ae0f-e1974b94ff0c', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 14, 14, 'አጠፋቸው ዘንድ፥ ስማቸውንም ከሰማይ በታች እደመስስ ዘንድ ተወኝ፤ አንተንም ከእነርሱ ለሚበረታና እጅግ ለሚበዛ ሕዝብ አደርግሃለሁ።’'),
  ('bf172ada-d110-5a8a-adda-c1296e4d122b', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 15, 15, 'እኔም ተመልሼ ከተራራው ወረድሁ፤ ተራራውም በእሳት ይነድድ ነበር፤ ሁለቱም የቃል ኪዳን ጽላት በሁለቱ እጆች ነበሩ።'),
  ('a3885cb7-d301-5687-a187-37e58b74795b', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 16, 16, 'እነሆ፥ በአምላካችሁ እግዚአብሔር ፊት እንደ በደላችሁ፥ ለእናንተም ቀልጦ የተሠራ ምስል ሠርታችሁ ልትጠብቁት እግዚአብሔር ካዘዛችሁ መንገድ ፈጥናችሁ ፈቀቅ እንዳላችሁ ባየሁ ጊዜ፥'),
  ('35940c46-3a87-582d-a007-2a23c005c1e9', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 17, 17, 'ሁለቱንም ጽላት ያዝሁ፤ ከሁለቱም እጆች ጣልኋቸው፤ በእናንተም ፊት ሰበርኋቸው።'),
  ('25456b73-c4b7-5076-aa9c-8dddc1ebc344', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 18, 18, 'ስለ ሠራችሁት ኀጢአት ሁሉ፥ እርሱንም ለማስቈጣት በእግዚአብሔር ፊት ክፉ የሆነውን ነገር ስላደረጋችሁ፥ እንደ ፊተኛው በእግዚአብሔር ፊት አርባ ቀንና አርባ ሌሊት ዳግመኛ ለመንሁ፤ እንጀራ አልበላሁም፥ ውኃም አልጠጣሁም።'),
  ('8e5989b6-bbc8-5258-abb3-29e143c59a56', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 19, 19, 'እግዚአብሔርም ሊያጠፋችሁ ከተቈጣባችሁ ከቍጣውና ከመዓቱ የተነሣ ፈራሁ፤ እግዚአብሔርም በዚያን ጊዜ ደግሞ ሰማኝ።'),
  ('3379f0fc-9597-565d-ad32-d1f4541cd334', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 20, 20, 'እግዚአብሔርም አሮንን ሊያጠፋው እጅግ ተቈጣው፤ ስለ አሮንም ደግሞ በዚያን ጊዜ ጸለይሁ።'),
  ('5e0b243d-1512-543d-afdb-fd992edc44b0', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 21, 21, 'ስለ አደረጋችሁትም ኀጢአት የጥጃውን ምስል ወሰድሁ፤ በእሳትም አቃጠልሁት፤ አደቀቅሁትም፤ እንደ ትቢያም እስኪሆን ድረስ ፈጨሁት፤ እንደ ትቢያም ሆነ፤ ትቢያውንም ከተራራው በሚወርድ ወንዝ ጨመርሁት።'),
  ('7a4d5938-5cb0-5e66-ad35-441ded34e7bc', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 22, 22, '“በውዕየት፥ በፈተናም በምኞት መቃብርም እግዚአብሔርን አስቈጣችሁት።'),
  ('3608335a-c619-5ae2-a590-a7c8a4b7c6fb', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 23, 23, 'እግዚአብሔርም፦ ውጡ፤ የሰጠኋችሁንም ምድር ውረሱ ብሎ ከቃዴስ በርኔ በላካችሁ ጊዜ በአምላካችሁ በእግዚአብሔር ቃል ዐመፃችሁ፤ በእርሱም አላመናችሁም፤ ቃሉንም አልሰማችሁም።'),
  ('27567e7d-72b7-5580-a064-ec4dde7c9ac0', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 24, 24, 'ለእናንተ ከታወቀበት ቀን ጀምሮ በእግዚአብሔር ዐመፀኞች ነበራችሁ።'),
  ('6d68b126-d474-5d41-a3a4-35478e5d37d3', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 25, 25, '“እግዚአብሔርም፦ ያጠፋችሁ ዘንድ ስለ ተናገረ ቀድሞ እንደ ለመንሁ አርባ ቀንና አርባ ሌሊት በእግዚአብሔር ፊት ለመንሁ።'),
  ('24fa4b72-3b85-50ba-a0b8-5422521e945c', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 26, 26, 'በእግዚአብሔርም ፊት እንዲህ ብዬ ጸለይሁ፦ የአማልክት ንጉሥ እግዚአብሔር ሆይ፥ በታላቅ ኀይልህ የተቤዠሃቸውን፥ በጠነከረችውም እጅህና በተዘረጋች ክንድህ ከግብፅ ያወጣሃቸውን ሕዝብህንና ርስትህን አታጥፋ።'),
  ('9bb6f0a3-a6b1-52be-a68a-9deb4a7cf14f', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 27, 27, 'በራስህ የማልህላቸውን አገልጋዮችህን አብርሃምንና ይስሐቅን፥ ያዕቆብንም አስብ፤ የዚህን ሕዝብ ልበ ደንዳናነት፥ ክፋቱንም፥ ኀጢአቱንም አትመልከት፤'),
  ('27e1ec6b-fed2-5057-a28f-f30b0ab0f3c0', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 28, 28, 'ከእርስዋ እኛን ያወጣህባት ምድር ሰዎች፦ እግዚአብሔር ተስፋ ወደ ሰጣቸው ምድር ያገባቸው ዘንድ አልቻለምና፥ ጠልቶአቸውማልና ስለዚህ በምድረ በዳ ሊገድላቸው አወጣቸው እንዳይሉ።'),
  ('f1e8a44d-6c57-5be3-acba-f05e1dfceb77', 'f73cc2f3-e3f3-51bb-a21f-ba4ab14c3f3f', '499e7098-3831-52f8-adf6-139c56fc06f3', 29, 29, 'እነርሱም በታላቅ ኀይልህ፥ በጸናውና በተዘረጋውም ክንድህ ከግብፅ ምድር ያወጣሃቸው ሕዝብህና ርስትህ ናቸው።'),
  ('9d65ec0e-ac07-5229-a524-2a69ca963c7c', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 1, 1, '“በዚያን ጊዜ እግዚአብሔር እንደ ፊተኞች ያሉትን ሁለት የድንጋይ ጽላት ለአንተ ቀርፀህ ወደ እኔ ወደ ተራራው ውጣ፤ ለአንተም የእንጨት ታቦት ሥራ፤'),
  ('9d95746b-b375-5b5b-aed4-daa8834c8504', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 2, 2, 'በሰበርሃቸው በፊተኞቹ ጽላት የነበሩትን ቃሎች ሁሉ በእነዚህ ጽላት እጽፋለሁ፤ በታቦቱም ውስጥ ታደርጋቸዋለህ አለኝ።'),
  ('35a21383-f535-525d-ae8b-52e7ea98583b', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 3, 3, 'ከማይነቅዝ እንጨትም ታቦቱን ሠራሁ፤ እንደ ፊተኞችም ሁለት የድንጋይ ጽላት ቀረፅሁ፤ ወደ ተራራውም ወጣሁ፤ ሁለቱም ጽላት በእጄ ነበሩ፤'),
  ('82d333e6-139a-52e7-a042-7973c8a3c3bc', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 4, 4, 'እግዚአብሔርም በተራራው ላይ በእሳት መካከል የተናገራችሁን ዐሠርቱን ቃላት ቀድሞ ተጽፈው እንደ ነበረ በጽላቱ ላይ ጻፈ፤ እግዚአብሔርም እነርሱን ለእኔ ሰጠኝ።'),
  ('8fcb78a5-a370-5314-ad3a-82b5eca79066', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 5, 5, 'ተመልሼም ከተራራው ወረድሁ፤ ጽላቱንም በሠራሁት ታቦት ውስጥ አደረግኋቸው፤ እግዚአብሔርም እንዳዘዘኝ በዚያ ኖሩ።'),
  ('ff3fafb4-ca98-53db-acb4-ea7b87f08eba', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 6, 6, '“የእስራኤልም ልጆች የማስቢ ወገን ከሚሆን ከኢያቅም ልጆች ቦታ ከቤሮስ ተጓዙ። በዚያም አሮን ሞተ፤ ተቀበረም፤ በእርሱም ፋንታ ልጁ አልዓዛር ካህን ሆነ።'),
  ('7fd18fdd-5ab4-56fc-a4db-3aaf136244cd', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 7, 7, 'ከዚያም ወደ ገድገድ ተጓዙ፤ ከገድገድም ወደ ውኃ ፈሳሾች ምድር ወደ ኤጤባታ ተጓዙ።'),
  ('712f746e-10a1-5075-af54-8f3c06f017ae', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 8, 8, 'በዚያን ጊዜ የእግዚአብሔርን ቃል ኪዳን ታቦት ይሸከም ዘንድ፥ እርሱንም ለማገልገል በእግዚአብሔር ፊት ይቆም ዘንድ፥ በስሙም ይባርክ ዘንድ እግዚአብሔር እስከ ዛሬ ድረስ የሌዊን ነገድ ለየ።'),
  ('b39bce05-a8af-5dbd-a061-62f55a73a83d', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 9, 9, 'ስለዚህ ለሌዋውያን ከወንድሞቻቸው ጋር ክፍልና ርስት የላቸውም፤ አምላክህ እግዚአብሔር እንደ ነገራቸው እግዚአብሔር ርስታቸው ነውና።'),
  ('3d43c195-0c2c-5250-ae4e-3e11768db31f', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 10, 10, '“እኔም እንደ ፊተኛው ጊዜ አርባ ቀንና አርባ ሌሊት በተራራው ላይ ቆምሁ፤ እግዚአብሔርም በዚህ ጊዜ ደግሞ ሰማኝ፤ እግዚአብሔርም ሊያጠፋችሁ አልወደደም።'),
  ('dfcd41a2-34d9-50a6-a212-98bba9bdbb2e', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '236eabe2-6bac-5ab7-a6a2-31b57dbe1ca2', 11, 11, 'እግዚአብሔርም፦ ‘ተነሥተህ በሕዝቡ ፊት ተጓዝ፤ ለአባቶቻቸውም ልሰጣቸው ወደ ማልሁላቸው ምድር ይግቡ፤ ይውረሱአትም’ አለኝ።'),
  ('bd538605-4bbd-5faa-ae41-f212aca15e84', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 1, 12, '“እስራኤል ሆይ፥ አሁንስ አምላክህ እግዚአብሔር ከአንተ የሚፈልገው ምንድን ነው? አምላክህን እግዚአብሔርን ትፈራ ዘንድ፥ በመንገዱም ሁሉ ትሄድ ዘንድ፥ አምላክህንም እግዚአብሔርን ትወድድ ዘንድ፥ በፍጹምም ልብህ፥ በፍጹምም ነፍስህ ታመልከው ዘንድ ነው እንጂ፥'),
  ('64b6083c-962b-582b-a235-ebff13a77cf4', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 2, 13, 'መልካምም እንዲሆንልህ ዛሬ ለአንተ የማዝዘውን የአምላክህን የእግዚአብሔርን ትእዛዝና ሥርዐት ትጠብቅ ዘንድ ነው እንጂ፤'),
  ('0abcfdad-fd50-51d3-aa3e-220736fd34ae', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 3, 14, 'እነሆ፥ ሰማይ፥ ሰማየ ሰማያትም፥ ምድርም፥ በእርስዋም ያለው ሁሉ የአምላክህ የእግዚአብሔር ነው።'),
  ('e520de3d-f02f-5361-a3e8-9ee29d5e5422', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 4, 15, 'ብቻ እግዚአብሔር አባቶቻችሁን መረጣቸው፤ ወደዳቸውም፤ ከእነርሱም በኋላ እናንተን ዘራቸውን እንደ ዛሬው ሁሉ ከአሕዛብ ሁሉ መረጠ።'),
  ('731218d6-0c7a-59a1-a842-d4eb65ca2904', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 5, 16, 'እናንተ የልባችሁን ክፋት ግዘሩ፤ ከእንግዲህ ወዲህ አንገታችሁን አታደንድኑ።'),
  ('683b075f-cc45-588d-a5ad-c4ee4061d3f1', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 6, 17, 'አምላካችሁ እግዚአብሔር የአማልክት አምላክ፥ የጌቶች ጌታ፥ ታላቅ አምላክ፥ ኀያልም፥ የሚያስፈራም፥ በፍርድም የማያደላ፥ መማለጃም የማይቀበል ነውና።'),
  ('60211090-0592-5f5e-ad9b-ae51b517d10f', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 7, 18, 'ለመጻተኛ፥ ለድሃ አደጉና ለመበለቲቱ ይፈርዳል፤ መብልና ልብስም ይሰጠው ዘንድ ስደተኛውን ይወድዳል።'),
  ('f719faec-a289-57fe-acee-8e548ee78705', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 8, 19, 'እናንተ በግብፅ ሀገር ስደተኞች ነበራችሁና ስለዚህ ስደተኛውን ውደዱ።'),
  ('87290cb2-b95e-501a-ae35-046afcf00d9f', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 9, 20, 'አምላክህን እግዚአብሔርን ፍራ፤ እርሱንም አምልክ፤ እርሱንም ተከተል፤ በስሙም ማል።'),
  ('c27ef8a8-2744-5370-a680-2818c1100924', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 10, 21, 'ዐይኖችህ ያዩአቸውን እነዚህን ታላላቆች የከበሩትን ነገሮች ያደረገልህ እርሱ መመኪያችሁ ነው፤ እርሱም አምላክህ ነው።'),
  ('665bb31c-8a3b-5ae0-adc4-f8427e176b58', '890af5f2-1e0c-5c61-a42f-23901e72ec41', '90572d29-bdb2-5ee7-a336-5559f5122ab8', 11, 22, 'አባቶችህ ሰባ ነፍስ ሆነው ወደ ግብፅ ወረዱ፤ አሁን ግን አምላክህ እግዚአብሔር ብዛትህን እንደ ሰማይ ከዋክብት አደረገ።'),
  ('bf8c5e44-7b51-556c-a44d-6ef1a6a15cad', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 1, 1, '“አምላክህን እግዚአብሔርን ውደድ፤ ሕጉንም፥ ሥርዐቱንም፥ ትእዛዙንም፥ ፍርዱንም በዘመንህ ሁሉ ጠብቅ።'),
  ('27654a3e-84cd-57a1-ad41-80a1bb57ec58', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 2, 2, 'ዛሬ ልጆቻችሁ የአምላካችሁን የእግዚአብሔርን ተግሣጽ፥ ታላቅነቱንም፥ የጸናችም እጁን፥ የተዘረጋውንም ክንዱን፥ ያዩና ያወቁ እንዳይደሉ ዕወቁ።'),
  ('217e5b10-5b54-5c0a-a148-719adbfa1aa7', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 3, 3, 'በግብፅም መካከል በግብፅ ንጉሥ በፈርዖንና በሀገሩ ሁሉ ላይ ያደረጋትን ተአምራቱንና ድንቅ ሥራዉን፥'),
  ('3f089419-1369-594b-a5a0-a061c3eb1a6a', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 4, 4, 'በተከተሉአችሁም ጊዜ በኤርትራ ባሕር ውኃ እንዳሰጠማቸው፥ እግዚአብሔርም እስከ ዛሬ ድረስ እንዳጠፋቸው፥ በግብፅ ጭፍራ በፈረሶቻቸውም፥ በሰረገሎቻቸውም ያደረገውን፥'),
  ('763e8829-3fed-5498-a958-de2cbfcda854', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 5, 5, 'ወደዚህ ስፍራ እስክትመጡ ድረስ በምድረ በዳ ያደረገላችሁን ሁሉ፥'),
  ('9419bd67-6a59-517b-a258-93ebf9406307', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 6, 6, 'በእስራኤልም ሁሉ መካከል ምድር አፍዋን ከፍታ እነርሱንና ቤተ ሰቦቻቸውን፥ ድንኳኖቻቸውንም፥ ለእነርሱም የነበራቸውን ሁሉ በዋጠቻቸው በሮቤል ልጅ በኤልያብ ልጆች በዳታንና በአቤሮን ያደረገውን ሁሉ፤'),
  ('5729483d-0ee2-5aae-a78f-df33f8c813db', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', 'c38de607-9de6-5bf4-a78c-a73d5b76431c', 7, 7, 'እግዚአብሔር ያደረጋቸውን ታላላቅ ሥራዎች ሁሉ ዐይኖቻችሁ አይተዋልና።'),
  ('db466804-86b1-5067-a5cd-ad345063eef1', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 1, 8, '“በሕይወት ትኖሩ ዘንድ፥ ትበዙም ዘንድ፥ ትወርሱአትም ዘንድ ዮርዳኖስን የምትሻገሩላትን ምድር እንድትወርሷት ዛሬ ለእናንተ የማዝዘውን ትእዛዝ ሁሉ ጠብቁ፤'),
  ('c2838e3f-f0e7-5d39-ae24-996c30ef5fdd', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 2, 9, 'እግዚአብሔር ለእነርሱና ከእነርሱም በኋላ ለዘራቸው ወተትና ማር የምታፈስሰውን ምድር ይሰጣቸው ዘንድ ለአባቶቻችሁ በማለላቸው ምድር ላይ ዕድሜያችሁ እንዲረዝም።'),
  ('d66b4d8e-b5f1-57c1-a01f-5c35b6f8e304', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 3, 10, 'ትወርሳት ዘንድ የምትገባባት ምድር፥ በአትክልት ስፍራ እንደሚዘሩ ዘርህን እንደ ዘራህባት፥ በእግርህም እንዳጠጣሃት፥ እንደ ወጣህባት እንደ ግብፅ ምድር አይደለችም።'),
  ('e5f942fe-1475-525f-a63b-9dfbde73398d', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 4, 11, 'ነገር ግን ትወርሱአት ዘንድ ተሻግራችሁ የምትገቡባት ምድር ተራሮችና ሜዳዎች ያሉባት ሀገር ናት፤ በሰማይ ዝናብ ውኃ ትረካለች።'),
  ('2018ca4a-225b-5a38-a8ec-d9cd969a16af', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 5, 12, 'አምላክህ እግዚአብሔር የሚጐበኛት ሀገር ናት፤ ከዓመቱ መጀመሪያ እስከ ዓመቱ መጨረሻ ድረስ የአምላክህ የእግዚአብሔር ዐይን ሁል ጊዜ በእርስዋ ላይ ነው።'),
  ('faa1d602-e12c-5f03-a0ac-acaddb0a9d72', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 6, 13, '“እናንተ አምላካችሁን እግዚአብሔርን ትወድዱ ዘንድ፥ በፍጹም ልባችሁ፥ በፍጹምም ነፍሳችሁ ታመልኩት ዘንድ ዛሬ ለእናንተ የማዝዘውን ትእዛዜን ፈጽማችሁ ብትሰሙ፥'),
  ('9a573140-6acf-58c1-a14e-beae1b70c7ab', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 7, 14, 'እህልህን፥ ወይንህንም፥ ዘይትህንም ትሰበስብ ዘንድ በየጊዜው የበልጉን ዝናብና የክረምቱን ዝናብ ለምድርህ ይሰጣል።'),
  ('d4b5c2b4-0b20-5cc1-ab57-51b74733b3cd', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 8, 15, 'በሜዳህ ለእንስሶችህ ሣርን ይሰጣል፤ ትበላማለህ፤ ትጠግብማለህ።'),
  ('e67e7868-fdeb-5ede-a2af-9efeeff96c57', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 9, 16, 'ልባችሁ እንዳይስት፥ ፈቀቅ እንዳትሉ፥ ሌሎችንም አማልክት እንዳታመልኩ፥ እንዳትሰግዱላቸውም ተጠንቀቁ።'),
  ('b5cc3973-4ecd-5708-a660-f0b995219f54', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 10, 17, 'የእግዚአብሔርም ቍጣ እንዳይነድድባችሁ፥ ዝናብም እንዳይዘንብ፥ ምድሪቱም ፍሬዋን እንዳትሰጥ ሰማይን እንዳይዘጋባችሁ፥ እግዚአብሔርም ከሚሰጣችሁ ከመልካሚቱ ምድር ፈጥናችሁ እንዳትጠፉ ተጠንቀቁ።'),
  ('f5144ec4-4d98-5c5b-a059-8c868718e19c', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 11, 18, '“እንግዲህ እነዚህን ቃሎች በልባችሁና በነፍሳችሁ አኑሩ፤ እነርሱንም ለምልክት በእጃችሁ ላይ እሰሩአቸው፤ በዐይኖቻችሁም መካከል እንደማይንቀሳቀስ ይሁኑ።'),
  ('a76eeb7b-ed33-5f78-a4fc-2d73e9740608', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 12, 19, 'ልጆቻችሁንም አስተምሩአቸው፤ በቤትም ሲቀመጡ፥ በመንገድም ሲሄዱ፥ ሲተኙም፥ ሲነሡም እንዲነጋገሩበት፤'),
  ('e886c46f-a50c-531b-a4e7-1974f6602c36', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 13, 20, 'በቤትህ መቃኖችና በደጃፍህም በሮች ላይ ጻፈው።'),
  ('171b1b69-d4fa-59a4-a34a-c537bab11d8c', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 14, 21, 'በምድር ላይ የሰማይን ዘመን ያህል ይሰጣቸው ዘንድ እግዚአብሔር ለአባቶቻችሁ በማለላቸው ምድር ዘመናችሁ የልጆቻችሁም ዘመን ይረዝም ዘንድ፤'),
  ('ff3f12b2-f802-5ea5-abe7-e93b0397d6fc', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 15, 22, 'አምላካችሁን እግዚአብሔርን ትወድዱ ዘንድ፥ በመንገዱም ሁሉ ትሄዱ ዘንድ፥ እርሱንም ትከተሉ ዘንድ፥ ዛሬ ለእናንተ የማዝዘውን ትእዛዝ ሁሉ ብትጠብቁ ብታደርጉአትም፥'),
  ('10ccd8ae-2612-5ffa-a2a7-0481f5bd6646', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 16, 23, 'እግዚአብሔር እነዚህን አሕዛብ ሁሉ ከፊታችሁ ያወጣል፤ ከእናንተም የሚበልጡትን፥ የሚበረቱትንም አሕዛብ ትወርሳላችሁ።'),
  ('0be7d62d-91c8-5f50-a46e-5cdcb7ef0cfe', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 17, 24, 'የእግራችሁ ጫማ የምትረግጣት ስፍራ ሁሉ ለእናንተ ትሆናለች፤ ከምድረ በዳም፥ ከአንጢሊባኖስም፥ ከታላቁም ከኤፍራጥስ ወንዝ ጀምሮ እስከ ምዕራብ ባሕር ድረስ ዳርቻችሁ ይሆናል።'),
  ('77d880c0-b5da-5e9e-a637-909e7eaf4428', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 18, 25, 'በእናንተም ፊት ማንም መቆም አይችልም፤ አምላካችሁ እግዚአብሔር እርሱ እንደ ተናገራችሁ፥ ማስፈራታችሁን፥ ማስደንገጣችሁንም በምትረግጡአት ምድር ሁሉ ላይ ያኖራል።'),
  ('57aeebf7-98ec-5203-a9fa-335d388e77d8', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 19, 26, '“እነሆ፥ እኔ ዛሬ በፊታችሁ በረከትንና መርገምን አኖራለሁ፤'),
  ('725ab2f5-2143-5a26-aa1f-9ffc2aed6916', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 20, 27, 'በረከትም፥ እኔ ዛሬ ለእናንተ የማዝዘውን የአምላካችሁን የእግዚአብሔርን ትእዛዝ ብትሰሙ ነው፤'),
  ('b32b19da-6938-57d3-ad52-0734a735eb87', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 21, 28, 'መርገምም፥ የአምላካችሁን የእግዚአብሔርን ትእዛዝ ባትሰሙ፥ ዛሬ ካዘዝኋችሁ መንገድ ፈቀቅ ብትሉ፥ ሌሎችንም የማታውቁአቸውን አማልክት ብትከተሉ፥ ብታመልኳቸውም ነው።'),
  ('fb0ef057-9aa1-50a4-abf1-757aa99a845f', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 22, 29, 'አምላክህም እግዚአብሔር ትወርሳት ዘንድ አንተን ወደምትሄድባት ምድር ባገባህ ጊዜ፥ በረከቱን በገሪዛን ተራራ፥ መርገሙንም በጌባል ተራራ ታኖራለህ።'),
  ('30a709d7-bb10-59dc-a76b-06dcaf6232ef', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 23, 30, 'እነርሱም በዮርዳኖስ ማዶ፥ ከፀሐይ መግቢያ ካለችው መንገድ በኋላ በዓረባ በተቀመጡት በከነዓናውያን ምድር፥ በጌልጌላ ፊት ለፊት በረዥሙ ዛፍ አጠገብ ናቸው።'),
  ('60140500-5be1-54ed-ab4a-89fce59e960a', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 24, 31, 'አምላካችሁ እግዚአብሔር በዕጣችሁ ለሁልጊዜ የሚሰጣችሁን ምድር ትገቡና ትወርሱ ዘንድ ዮርዳኖስን ትሻገራላችሁ፤ ትወርሱአታላችሁም፤ ትቀመጡባታላችሁም።'),
  ('87b4f3b8-eb29-5d38-a3b0-0fecdc0285a2', '4d310963-3530-52ed-ae16-a3fc8b9cfefa', '9d33d705-95fc-57e0-a3c1-960f773fa2df', 25, 32, 'እኔም ዛሬ በፊታችሁ የማኖራትን ሥርዐትና ፍርድ ሁሉ ታደርጉ ዘንድ ጠብቁ።'),
  ('037bf305-00cd-5683-afb0-a74110b07d82', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 1, 1, '“በምድር ላይ በምትኖሩበት ዘመን ሁሉ የአባቶቻችሁ አምላክ እግዚአብሔር ትወርሷት ዘንድ በሚሰጣችሁ ሀገር ታደርጉት ዘንድ የምትጠብቁት ሥርዐት፥ ፍርድም ይህ ነው።'),
  ('8a3a293b-a26e-58f3-a5b5-3e245960570f', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 2, 2, 'እናንተ የምትወርሱአቸው አሕዛብ አማልክቶቻቸውን ያመለኩባቸውን፥ በረዥም ተራሮች፥ በኮረብቶችም ላይ ከለምለምም ዛፍ በታች ያለውን ስፍራ ሁሉ ፈጽማችሁ አጥፉት፤'),
  ('c0783df6-0063-5b1f-a91b-44ca90ffb18f', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 3, 3, 'መሠዊያቸውንም አፍርሱ፤ ሐውልቶቻቸውንም ሰባብሩ፤ የማምለኪያ ዐጸዶቻቸውንም ቁረጡ፤ የአማልክቶቻቸውንም ምስሎች በእሳት አቃጥሉ፤ ከዚያም ስፍራ ስማቸውን አጥፉ።'),
  ('4b26f997-1540-5ece-a05b-ff03f5d00490', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 4, 4, 'ለአምላካችሁ ለእግዚአብሔር እንዲህ ያለ ሥራ በዚያ አትሥሩ።'),
  ('2df4c488-5887-5581-aba7-6e9024f1f960', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 5, 5, 'ነገር ግን አምላካችሁ እግዚአብሔር ከከተሞቻችሁ ሁሉ በአንዱ ስሙ ይጠራ ዘንድ የመረጠውን ስፍራ ትሻላችሁ፤ ወደዚያም ትመጣላችሁ።'),
  ('1398e654-c2a6-57cd-a7d0-74012a6cb588', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 6, 6, 'ወደዚያም የሚቃጠለውን መሥዋዕታችሁን፥ ቍርባናችሁንም፥ ዐሥራታችሁንም፥ ቀዳምያታችሁን፥ ስዕለታችሁንም፥ በፈቃዳችሁ የምታቀርቡትን፥ የላማችሁንና የበጋችሁንም በኵራት ውሰዱ።'),
  ('6b06fe41-6193-5c11-a638-51b94fdc36b9', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 7, 7, 'በዚያም በአምላካችሁ በእግዚአብሔር ፊት ብሉ፤ እጃችሁንም በምትዘረጉበት፥ አምላካችሁ እግዚአብሔር በባረካችሁ ነገር ሁሉ፥ እናንተና ቤተሰባችሁ ደስ ይበላችሁ።'),
  ('8b11bc9d-3ebd-5d01-a3f2-59d5bf91669d', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 8, 8, 'ሰው ሁሉ በፊቱ መልካም መስሎ የታየውን፥ እኛ በዚህ ዛሬ የምናደርገውን ሁሉ አታድርጉ፤'),
  ('9710b83f-3fe2-5fa0-af1c-d853b32e3d74', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 9, 9, 'አምላካችሁ እግዚአብሔር ወደሚሰጣችሁ ማረፊያና ርስት እስከ ዛሬ ድረስ አልደረሳችሁምና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0efb4ffa-bcba-5256-abc7-71efaa6afcb8', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 10, 10, 'ዮርዳኖስን ግን በተሻገራችሁ ጊዜ፥ አምላካችሁም እግዚአብሔር በሚያወርሳችሁ ምድር በተቀመጣችሁ ጊዜ፥ ያለ ፍርሀትም እንድትኖሩ ከከበቡአችሁ ጠላቶች ሁሉ ዕረፍት በሰጣችሁ ጊዜ፥'),
  ('14dee4b7-6ea2-568a-aef8-3ed4943b1889', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 11, 11, 'በዚያን ጊዜ አምላካችሁ እግዚአብሔር ስሙ ይጠራበት ዘንድ ወደዚያ ወደ መረጠው ስፍራ፥ እኔ የማዝዛችሁን ሁሉ፥ የሚቃጠለውን መሥዋዕታችሁን፥ ቍርባናችሁንም፥ ዐሥራታችሁንም፥ ከእጃችሁ ሥራ ቀዳምያቱን የተመረጠውንም መባችሁን ሁሉ፥ ለአምላካችሁም የተሳላችሁትን ሁሉ ውሰዱ።'),
  ('cfdeef95-a65a-5dce-a95e-f63d5c02a359', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 12, 12, 'እናንተም፥ ወንዶች ልጆቻችሁና ሴቶች ልጆቻችሁም፥ ወንዶችና ሴቶች አገልጋዮቻችሁም፥ ከእናንተ ጋር ክፍልና ርስት ስለሌለው በደጆቻችሁ ውስጥ የተቀመጠው ሌዋዊም በአምላካችሁ በእግዚአብሔር ፊት ደስ ይበላችሁ።'),
  ('d7310174-a0e2-5961-ae9a-5e99d7d9caaf', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 13, 13, 'የሚቃጠለውን መሥዋዕትህን በሚታይህ ስፍራ ሁሉ እንዳታቀርብ ተጠንቀቅ።'),
  ('dabb2d19-e8c0-5408-acce-1a3e0446d57f', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 14, 14, 'ነገር ግን አምላክህ እግዚአብሔር ከነገዶችህ ከአንዱ ዘንድ በመረጠው ስፍራ በዚያ የሚቃጠለውን መሥዋዕትህን አቅርብ፤ በዚያም ዛሬ እኔ የማዝዝህን ሁሉ አድርግ።'),
  ('2dfcb3e1-2d57-52c4-a386-3dc18b9545f4', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 15, 15, '“ነገር ግን አምላክህ እግዚአብሔር እንደ ሰጠህ በረከት፥ እንደ ፈቀድህ፥ በሀገርህ ሁሉ ውስጥ አርደህ ሥጋን ብላ፤ ከአንተ ንጹሕ ሰው፥ ንጹሕም ያልሆነ ሰው እንደ ሚዳቋና እንደ ዋላ ያለውን ይብላው።'),
  ('be2ec355-4e3b-5010-afc2-8b1840e3ee17', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 16, 16, 'ደሙን ግን እንደ ውኃ በምድር ላይ አፍስሱት እንጂ አትብሉት።'),
  ('f3b3471e-d294-5547-af08-c1dc34f0c58a', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 17, 17, 'የእህልህን፥ የወይን ጠጅህን፥ የዘይትህንም ዐሥራት፥ የላምህንና የበግህንም በኵራት፥ የተሳልኸውንም ስእለት ሁሉ፥ በፈቃድህ ያቀረብኸውን፥ የእጅህንም ቀዳምያት በከተሞችህ ሁሉ ውስጥ መብላት አትችልም።'),
  ('bc266efb-fd61-5cb5-a3b3-ebb9759c888d', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 18, 18, 'ነገር ግን አንተ፥ ወንድና ሴት ልጅህም፥ ወንድና ሴት አገልጋይህም፥ በሀገርህም ውስጥ ያለው መጻተኛ አምላክህ እግዚአብሔር በመረጠው ስፍራ በአምላክህ በእግዚአብሔር ፊት ብሉት፤ እጅህንም በምትዘረጋበት ነገር ሁሉ በአምላክህ በእግዚአብሔር ፊት ደስ ይበልህ።'),
  ('766bbc66-2aaa-5474-a83e-4824dd8fa7ca', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 19, 19, 'በምድርህ ላይ በምትኖርበት ዘመን ሁሉ ሌዋዊዉን ቸል እንዳትል ተጠንቀቅ።'),
  ('67ecae43-2928-5e5f-abfb-b9f9d39deabd', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 20, 20, '“አምላክህ እግዚአብሔር እንደ ነገረህ ድንበርህን ባሰፋልህ ጊዜ፥ ሰውነትህም ሥጋ መብላት ስለ ወደደች፦ ሥጋ ልብላ ስትል፥ ሰውነትህ ከወደደችው ሁሉ ብላ።'),
  ('56fd35ff-b457-5a41-a039-45199e78e057', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 21, 21, 'አምላክህ እግዚአብሔር በዚያ ስሙ ይጠራ ዘንድ የመረጠው ስፍራ ከአንተ ሩቅ ቢሆንም፥ እግዚአብሔር ከሰጠህ ከላምና ከበግ መንጋህ እንዳዘዝሁህ እረድ፤ ሰውነትህም የወደደችውን በሀገርህ ውስጥ ብላው።'),
  ('7f5f1339-968a-58c9-a082-1d47108664d5', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 22, 22, 'ሚዳቋና ዋላ እንደሚበሉ እንዲሁ ብላው፤ ከአንተ ንጹሕ ሰው፥ ንጹሕም ያልሆነ ይብላው።'),
  ('7410826a-b8c6-5b76-a9c5-6de488aedf19', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 23, 23, 'ደምን እንዳትበላ ተጠንቀቅ፤ ደሙ ነፍሱ ነውና፥ ነፍስም ከሥጋ ጋር አይበላምና።'),
  ('3bd792fe-154d-5c86-acec-5a250758a08a', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 24, 24, 'በምድር ላይ እንደ ውኃ አፍስሰው እንጂ አትብላው።'),
  ('9759d30b-d5c0-58ff-adee-e5d4abddc5db', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 25, 25, 'በአምላክህ በእግዚአብሔር ፊት መልካምና ጥሩ የሆነውን ነገር ስታደርግ ለአንተ፥ ከአንተም በኋላ ለልጆችህ መልካም እንዲሆንላችሁ፥ አትብላው።'),
  ('61d4e66c-89ce-5c56-aeda-9b272333bfa3', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 26, 26, 'ነገር ግን የተቀደሰውን ነገርህን፥ ስእለትህንም ይዘህ አምላክህ እግዚአብሔር ስሙ በዚያ እንዲጠራ ወደ መረጠው ስፍራ ሂድ።'),
  ('94a5510e-42da-5de1-a476-43d8a00c2dd0', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 27, 27, 'ሥጋውን የሚቃጠል መሥዋዕት አድርገህ፥ በአምላክህ በእግዚአብሔር መሠዊያ ላይ አቅርብ፤ የመሥዋዕትህም ደም በአምላክህ በእግዚአብሔር መሠዊያ ላይ ይፍሰስ፥ ሥጋውንም ብላው።'),
  ('2cdc9610-cfac-52d6-a2d7-ea63b7b425fa', 'cd912a90-bb84-59d6-a269-b506555d3c05', 'a34408cb-8cac-529d-adaa-dafee6122148', 28, 28, 'በአምላክህ በእግዚአብሔር ፊት መልካምና ጥሩ የሆነውን ነገር ስታደርግ ለአንተ፥ ከአንተም በኋላ ለልጆችህ ለዘለዓለም መልካም ይሆንላችሁ ዘንድ እኔ የማዝዝህን እነዚህን ቃሎች ሁሉ ሰምተህ ጠብቅ።'),
  ('8e48145b-b61f-5633-a2a1-1af554eee496', 'cd912a90-bb84-59d6-a269-b506555d3c05', '4162d5d9-cdc5-564c-ab76-fb454e999e1c', 1, 29, '“አምላክህ እግዚአብሔር ትወርሳቸው ዘንድ የምትሄድባቸውን አሕዛብ በፊትህ ባጠፋ ጊዜ፥ አንተም በወረስሃቸው ጊዜ፥ በምድራቸውም በተቀመጥህ ጊዜ፥ ከፊትህ ከጠፉ በኋላ እነርሱን ለመከተል እንዳትሻ፥'),
  ('75f2ccd4-648d-5b1b-a8c7-0e2624b68df5', 'cd912a90-bb84-59d6-a269-b506555d3c05', '4162d5d9-cdc5-564c-ab76-fb454e999e1c', 2, 30, 'አምላኮቻቸውንም እንዳትሻ፥ አሕዛብም ለአምላኮቻቸው እንደሚያደርጉ እኔም አደርጋለሁ እንዳትል ራስህን ጠብቅ።'),
  ('ca460797-7740-569b-aac7-7751046f6c4b', 'cd912a90-bb84-59d6-a269-b506555d3c05', '4162d5d9-cdc5-564c-ab76-fb454e999e1c', 3, 31, 'ለአምላክህ ለእግዚአብሔር እንዲሁ አታድርግ፤ ወንዶችና ሴቶች ልጆቻቸውን ለአምላኮቻቸው በእሳት ስለሚያቃጥሉ አሕዛብ ለአምላኮቻቸው የሚያደርጉትን ርኩስ ነገር እግዚአብሔር ይጠላልና።'),
  ('ffd2dbf6-51ce-5bbc-a15d-664cd47400c7', 'cd912a90-bb84-59d6-a269-b506555d3c05', '4162d5d9-cdc5-564c-ab76-fb454e999e1c', 4, 32, '“እኔ ዛሬ የማዝዝህን ነገር ሁሉ ታደርገው ዘንድ ጠብቅ፤ ምንም በእርሱ ላይ አትጨምር፤ ከእርሱም ምንም አታጕድል።'),
  ('4c7195ba-4ba3-5456-adb6-09869ee7ead3', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 1, 1, '“ከአንተም ነቢይ ወይም ሕልም አላሚ ቢነሣ፥ ምልክትም፥ ተአምራትም ቢሰጥህ፥'),
  ('5620b33f-bed7-5a67-a4ac-6939fcf035c1', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 2, 2, 'እርሱም፦ ሄደን የማታውቃቸውን ሌሎች አማልክት እንከተል እናምልካቸውም ብሎ የተናገረህ ምልክቱ ወይም ተአምራቱ ቢፈጸም፥'),
  ('f8f0b411-1fa4-59f7-a919-806e779b82ac', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 3, 3, 'አምላካችሁን እግዚአብሔርን በፍጹም ልባችሁ፥ በፍጹምም ነፍሳችሁ ትወድዱት እንደሆን ያውቅ ዘንድ አምላካችሁ እግዚአብሔር ሊፈትናችሁ ነውና የዚያን ነቢይ ቃል ወይም ያን ሕልም አላሚ አትስሙ።'),
  ('a6f35e70-69be-57c7-a69b-ba42ddb561ee', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 4, 4, 'አምላካችሁን እግዚአብሔርን ተከተሉ፤ እርሱንም ፍሩ፤ ትእዛዙንም ጠብቁ፤ ቃሉንም ስሙ፥ እርሱንም ተማጠኑት።'),
  ('0cdea0a3-f27e-5823-a7b3-e3f411037764', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 5, 5, 'ከግብፅ ምድር ካወጣችሁ፥ ከባርነትም ቤት ካዳናችሁ ከአምላካችሁ ከእግዚአብሔር ሊያስታችሁ፥ አምላክህ እግዚአብሔርም ትሄድባት ዘንድ ካዘዘህ መንገድ ሊያወጣህ ተናግሮአልና ያ ነቢይ ወይም ሕልም አላሚ ይገደል፤ እንዲሁም ክፉውን ነገር ከአንተ አርቅ።'),
  ('f95e87de-3e64-507a-a0ff-b1914bfa96dc', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 6, 6, '“የአባትህ ወይም የእናትህ ልጅ ወንድምህ ወይም ወንድ ልጅህ ወይም ሴት ልጅህ ወይም አብራህ የምትተኛ ሚስትህ ወይም እንደ ነፍስህ ያለ ወዳጅህ በስውር፦ ና፥ ሄደን አንተም አባቶችህም የማታውቋቸውን ሌሎች አማልክት እናምልክ ብሎ ቢያስትህ፥'),
  ('80722954-bc1d-5be1-a5b3-c3f975fa268b', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 7, 7, 'ከምድር ዳር ጀምሮ እስከ ምድር ዳር ድረስ ወደ አንተ የቀረቡት ከአንተም የራቁት አንተን ከብበውህ ያሉ አሕዛብ ከሚያመልኩአቸው አማልክት፥'),
  ('111bdc1e-584f-53f9-a167-ad7397949226', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 8, 8, 'ከእርሱ ጋር አትተባበር፤ አትስማውም፤ ዐይንህም አይራራለት፤ አትማረውም፤ አትሸሽገውም፤'),
  ('f94da4ff-a4ea-536c-a5aa-c56bb89fcfdc', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 9, 9, 'ነገር ግን ፈጽመህ ተናገር፤ እርሱን ለመግደል በፊት ያንተ እጅ፥ ከዚያም በኋላ የሕዝቡ ሁሉ እጅ በላዩ ትሁን።'),
  ('17701dbd-44a4-5814-a091-1aa0cd72ed3e', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 10, 10, 'ከግብፅ ምድር ከባርነት ቤት ካወጣህ ከአምላክህ ከእግዚአብሔር ሊያርቅህ ወድዶአልና በድንጋይ ይውገሩት፤ ይግደሉትም።'),
  ('e608eef2-4c3e-5cd3-a7c7-9663a71cb034', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 11, 11, 'እስራኤል ሁሉ ሰምተው ይፍሩ፤ እንዲህ ያለ ክፉ ሥራም እንደገና በእናንተ መካከል አይደገም።'),
  ('8805f7cd-3438-5bb6-abd2-2b1d52e491f1', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 12, 12, '“አምላክህ እግዚአብሔር ልትኖርባት ከሰጠህ ከተሞች በአንዲቱ ከተማህ፦'),
  ('99c71964-5018-59d7-a430-b92e1f22496c', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 13, 13, 'ክፋተኞች ሰዎች ከእናንተ ዘንድ ወጥተው፦ ሄደን የማታውቋቸውን ሌሎች አማልክት እናምልክ ብለው የከተማቸውን ሰዎች አሳቱ ሲሉ ወሬ ብትሰማ፥'),
  ('5e4b63ba-980e-544d-ac99-fefa7e04683b', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 14, 14, 'ትፈልጋለህ ትመረምራለህም፤ ትጠይቃለህም፤ እነሆም፥ እውነት ቢሆን፥ ይህም ክፉ ነገር በመካከልህ እንደ ተደረገ ርግጥ ሆኖ ቢገኝ፥'),
  ('f8e62ff2-4320-5c98-a646-1e7534f88ccd', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 15, 15, 'የዚያችን ሀገር ሰዎች በሰይፍ ስለት ፈጽሞ ትመታቸዋለህ፤ ሀገሪቱን፥ በውስጥዋም ያለውን ሁሉ ትረግማለህ።'),
  ('427c8468-863a-5649-ad09-cc3915cc2aee', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 16, 16, 'ዕቃዋንም ሁሉ ወደ አደባባይዋ ትሰበስባለህ፤ ከተማይቱንም፥ ዕቃዋንም ሁሉ በአምላክህ በእግዚአብሔር ፊት በእሳት ፈጽመህ ታቃጥላለህ፤ ለዘለዓለምም ወና ትሆናለች፤ ደግሞም አትሠራም።'),
  ('a37d565c-26f6-51f7-a265-8aacce7ee7ee', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 17, 17, 'የእግዚአብሔር የመቅሠፍቱ ቍጣ ይመለስ ዘንድ፥ ለአባቶችህም እንደ ማለላቸው ይምርህ ዘንድ፥ ይራራልህም ዘንድ፥ ያበዛህም ዘንድ፥ ርጉም ከሆነው አንዳች ነገር በእጅህ አትንካ።'),
  ('a086bd84-d614-51e8-aba9-f39ea6a07be6', '83717ecb-c048-53c2-ab4c-eb0e47d2383d', 'b1ece943-a010-5a6e-af73-19ff87c5a769', 18, 18, 'ዛሬም እኔ የማዝዝህን ትእዛዝ ሁሉ ብትጠብቅ፥ በአምላክህ በእግዚአብሔር ፊት መልካምና ጥሩ የሆነውን ብታደርግ፥ የአምላክህን የእግዚአብሔርን ቃል ብትሰማ ለእርሱ ልጅ ትሆናለህ።'),
  ('4bc533b6-1de7-5878-af41-a279957e0729', '02311777-0c48-53d1-ae17-ee6840a33985', 'a24e0e0c-ec97-528d-a8ad-5d6de27bfdd7', 1, 1, '“ለሞተ ሰውም በዐይናችሁ መካከል ፊታችሁን አትንጩ፤ ራሳችሁንም አትላጩ፤'),
  ('a258417c-2f39-562d-abed-3c9e799fd73f', '02311777-0c48-53d1-ae17-ee6840a33985', 'a24e0e0c-ec97-528d-a8ad-5d6de27bfdd7', 2, 2, 'ለአምላክህ ለእግዚአብሔር አንተ ቅዱስ ሕዝብ ነህና፥ በምድርም ላይ ከሚኖሩ አሕዛብ ሁሉ ይልቅ ለእርሱ ለራሱ ሕዝብ ትሆንለት ዘንድ እግዚአብሔር አንተን መርጦአልና።'),
  ('6f097dc4-a982-55a5-a4b9-afed0b61bf29', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 1, 3, '“ርኩስን ነገር ሁሉ አትብሉ።'),
  ('53005ce9-96cf-5210-a3d0-f3df9bf5e7ed', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 2, 4, 'የምትበሉአቸው እንስሶች እነዚህ ናቸው፤ በሬ፥ በግ፥ ፍየል፥'),
  ('462aff25-6663-58c4-a3ea-dc35223dc85c', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 3, 5, 'ዋልያ፥ ሚዳቋ፥ የበረሃ ፍየል፥ ጎሽ፥ ብሖር፥ ሳላ፥ ድኵላ።'),
  ('2fbdfe3a-db8a-5d6a-ab61-fd5714ae966c', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 4, 6, 'ከእንስሶች ሰኰናው የተሰነጠቀውን፥ ጥፍሩም ከሁለት የተከፈለውን፥ የሚያመሰኳውንም እንስሳ ሁሉ ትበላለህ።'),
  ('d7d4b6a0-6b39-51c3-a060-914889ce72de', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 5, 7, 'ነገር ግን ከሚያመሰኩ ወይም ሰኰናቸው ከተሰነጠቀ እነዚህን አትበሉም፤ ግመልን፥ ሽኮኮን፥ ጥንቸልን አትበሉም፤ ያመሰኳሉና፥ ነገር ግን ሰኰናቸው አልተሰነጠቀምና እነዚህ ለእናንተ ርኩሳን ናቸው።'),
  ('b3e0ccf1-d491-5773-a67c-1d5a2576d824', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 6, 8, 'እርያም፥ ሰኰናው ስለተሰነጠቀ፥ ጥፍሩም ከሁለት ስለተከፈለ፥ ነገር ግን ሰለማያመሰኳ፥ እርሱ ለእናንተ ርኩስ ነው፤ ሥጋዉን አትብሉ፤ በድኑንም አትንኩ።'),
  ('0e704f6f-c436-59cc-a9d5-18924cc9e6ea', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 7, 9, '“በውኆች ውስጥ ከሚኖሩት ሁሉ የምትበሉአቸው እነዚህ ናቸው፤ ክንፍና ቅርፊትም ያላቸውን ትበላላችሁ፤'),
  ('93161285-f078-5ce3-a19f-c95fe239ca1e', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 8, 10, 'ክንፍና ቅርፊትም የሌላቸውን አትበሉም፤ ለእናንተ ርኩሳን ናቸው።'),
  ('3b1e9fdc-f445-5b21-ada7-05f06c2dc24e', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 9, 11, '“ንጹሓን የሆኑትን ወፎች ሁሉ ብሉ።'),
  ('bd285f18-b955-51f2-a68e-23b0cb89ec11', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 10, 12, 'ሊበሉ የማይገባቸው ግን እነዚህ ናቸው፤ ንስር፥ ገዴ፥ ዓሣ አውጭ።'),
  ('326ba070-9791-5f59-acaa-217ad36f6437', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 11, 13, 'ጭልፊት፥ ጭላትና መሰሎቻቸው፥'),
  ('6e9159da-9c53-5c7b-a830-b84568041081', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 12, 14, 'ቍራና መሰሎቹ፤'),
  ('104facfa-9033-567d-a65e-2276acf2218a', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 13, 15, 'ሰጎን፥ አራት ራስ አሞራ፥ ዝዪ፥ በቋል በየወገኑ።'),
  ('6a137527-024d-5335-a167-e222082157c3', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 14, 16, 'ጉጉት፥ ጋጋኖ፥ የውኃ ዶሮ።'),
  ('b61210f9-65f7-590f-a351-413e5e30b615', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 15, 17, 'ይብራ፥ ጥምብ አንሣ አሞራና መሰሎቻቸው፥'),
  ('a7759d94-3c7e-5b71-a4b7-07d23ce04e6d', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 16, 18, 'ዕርኩም፥ ሽመላ፥ ሳቢሳና መሰሎቹ፥ ጅንጅላቴ ወፍ፥ የሌሊት ወፍ።'),
  ('417c7c62-c403-5b5f-a403-41d3cc3621dd', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 17, 19, 'የሚበርሩም አዕዋፍ ሁሉ ለእናንተ ንጹሓን አይደሉምና ከእነርሱ አትብሉ፤'),
  ('54b073d1-b7fc-5e62-acef-927fc3317c22', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 18, 20, 'ነገር ግን ንጹሓን የሆኑትን ወፎች ሁሉ ብሉ።'),
  ('eccdba5d-7bb3-5b17-a6b3-b5c4f7e9669b', '02311777-0c48-53d1-ae17-ee6840a33985', '5ab50922-6fd3-5c44-a805-088b78195003', 19, 21, 'የበከተዉን ሁሉ አትብሉ፤ ይበላው ዘንድ በሀገርህ ደጅ ለተቀመጠ መጻተኛ ወይም ለባዕድ ስጠው፤ አንተ ለአምላካህ ለእግዚአብሔር የተቀደሰ ሕዝብ ነህና፥ የፍየሉን ጠቦት በእናቱ ወተት አትቀቅል።'),
  ('95bec878-08e7-5894-a267-20ee73a02237', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 1, 22, '“ከእርሻህ ዘርተህ በየዓመቱ ከምታገኘው እህልህ ሁሉ ዐሥራት ታወጣለህ።'),
  ('1d3d7ed0-8757-5acc-ae0b-cef5625a1cce', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 2, 23, 'በዘመንህም ሁሉ አምላክህን እግዚአብሔርን መፍራትን ትማር ዘንድ፥ ስሙ እንዲጠራበት በመረጠው ስፍራ በአምላክህ በእግዚአብሔር ፊት የእህልህን፥ የወይንህን፥ የዘይትህንም ዐሥራት፥ የላምህንና የበግህንም በኵራት ብላ።'),
  ('784e5b3f-e6b3-5965-a833-292a6caa65aa', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 3, 24, 'አምላክህ እግዚአብሔር ባርኮሃልና፥ መንገዱ ሩቅ ቢሆን፥ አምላክህም እግዚአብሔር ስሙን ያኖርበት ዘንድ የመረጠው ስፍራ ቢርቅብህ፥ ይህን ወደዚያ ለመሸከም ባትችል፥'),
  ('4268c3eb-2e74-5554-a5ca-0652abd566a4', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 4, 25, 'በብር ትሸጠዋለህ፤ ብሩንም በእጅህ ይዘህ አምላክህ እግዚአብሔር ወደ መረጠው ስፍራ ትሄዳለህ።'),
  ('6e4f6c38-add3-5aca-adfa-da22d8735444', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 5, 26, 'በዚያም በብሩ ሰውነትህ የፈለገውን፥ በሬ ወይም በግ፥ ወይም የወይን ጠጅ፥ ወይም ብርቱ መጠጥ፥ ሰውነትህ የሚሻውን ሁሉ ትገዛለህ፤ በዚያም በአምላክህ በእግዚአብሔር ፊት ትበላዋለህ፤ አንተና ቤተ ሰብህም ደስ ይላችኋል።'),
  ('3ee81e91-5dad-575f-a4bf-3f7539e0f429', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 6, 27, 'ድርሻና ርስት ከአንተ ጋር ስለሌለው በከተማህ ውስጥ ያለውን ሌዋዊ ቸል አትበል።'),
  ('b7ddd0fb-4a2b-55e9-a6ea-b610ff6cb66b', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 7, 28, '“በየሦስተኛው ዓመት መጨረሻ በዚያ ዓመት የፍሬህን ዐሥራት ሁሉ አምጥተህ በከተማዎችህ ውስጥ ታኖረዋለህ።'),
  ('afb94530-c4fc-57f3-a818-62041d6b1b05', '02311777-0c48-53d1-ae17-ee6840a33985', 'f53db6ed-c15b-5b60-a2b0-8241db4a40f2', 8, 29, 'ሌዋዊዉም፥ ከአንተ ጋር ክፍልና ርስት የለውምና፥ በከተማህ ውስጥ ያለ መጻተኛ፥ ድሃ-አደግም፥ መበለትም መጥተው ይበላሉ፤ ይጠግባሉም፤ ይኸውም አምላክህ እግዚአብሔር በምታደርገው በእጅህ ሥራ ሁሉ ይባርክህ ዘንድ ነው።'),
  ('9c327496-75a2-528b-a2d9-3e333b2a415e', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 1, 1, '“በየሰባቱ ዓመት የዕዳ ምሕረትን ታደርጋለህ።'),
  ('f6b1c126-64b6-592b-a9fe-7837711fd5ce', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 2, 2, 'ለምሕረቱም የሚገባ ትእዛዝ ይህ ነው፤ ባልንጀራህ ወይም ወንድምህ የሚከፍልህን ገንዘብ ሁሉ አትከፈል፤ የአምላክህ የእግዚአብሔር ምሕረት ተብላለችና።'),
  ('9b112142-3725-5f24-aa71-c99323550255', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 3, 3, 'ከባዕድ ግን በእርሱ ዘንድ ያለህን ሁሉ መቀበል ትችላለህ፤ በወንድምህ ላይ ያለውን ሁሉ ግን ተውለት።'),
  ('da0ffc84-5af8-5027-ac02-2a016399dd6e', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 4, 4, 'አምላክህ እግዚአብሔር ትወርሳት ዘንድ ርስት አድርጎ በሚሰጥህ ምድር ላይ አምላክህ እግዚአብሔር ፈጽሞ ይባርክሃልና በመካከልህ ድሃ አይኖርም፤'),
  ('120111d1-e27d-59ab-aed9-2063dc705df9', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 5, 5, 'አንተ የአምላክህን የእግዚአብሔርን ቃል ፈጽመህ ብትሰማ፥ ታደርጋትም ዘንድ ዛሬ የማዝዝህን ይህችን ትእዛዝ ሁሉ ብትጠብቅ፥'),
  ('07eebca6-53f3-5bcc-a63d-6bf614e744e5', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 6, 6, 'አምላክህ እግዚአብሔር እንደ ነገረህ ይባርክሃል፤ ለብዙ አሕዛብም ብዙ ታበድራለህ፤ አንተ ግን አትበደርም፤ ብዙ አሕዛብንም ትገዛለህ፤ አንተን ግን አይገዙህም።'),
  ('8703ee33-7563-5136-a3f1-d6c717cc5399', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 7, 7, '“አምላክህ እግዚአብሔር በሰጠህ ምድር ካሉ ከተሞች በአንዲትዋ ውስጥ ከሚኖሩ ከወንድሞችህ አንዱ ቢቸገር ልብህን አታጽና፤ ለወንድምህ ከመስጠት እጅህን አትመልስ።'),
  ('6ef7d076-660f-53db-acf8-877b36641b68', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 8, 8, 'ነገር ግን እጅህን ለእርሱ ዘርጋ፤ የለመነህንም ሁሉ ስጠው።'),
  ('d65a94c4-8605-5b2c-a8a3-53b43d514b45', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 9, 9, 'ሰባተኛው ዓመት የምሕረት ዓመት ቅርብ ነው፤ አልሰጠውምም ብለህ ክፉ ዐሳብ በልብህ እንዳታስብ ለራስህ ዕወቅ። ወንድምህም ዐይኑን በአንተ ላይ ያከፋል፤ እርሱም ወደ እግዚአብሔር በአንተ ላይ ይጮሃል፤ ኀጢአትም ይሆንብሃል።'),
  ('98e8f61f-b444-5f05-ab73-67cf94aea35a', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 10, 10, 'እጅህን በምትጥልበት ሁሉ አምላክህ እግዚአብሔር ስለዚህ በሥራህ ሁሉ ይባርክሃልና ፈጽመህ ስጠው፤ የለመነህንም ያህል አበድረው፤ በሰጠኸውም ጊዜ በልብህ አትጸጸት።'),
  ('18b5dd44-bbe3-57af-aa6b-a473a92f1b20', '48c2799e-5dbd-5da8-aa96-098f75494b34', '2ca76c42-1c3d-5c9d-a4c1-ec7e65a20c27', 11, 11, 'ድሃ ከምድርህ ላይ አይታጣምና ስለዚህ እኔ፦ በሀገርህ ውስጥ ላለው ድሃ፥ ለሚለምንህም ወንድምህ እጅህን ዘርጋ ብዬ አዝዝሃለሁ።'),
  ('c7227228-a90c-5e84-ac57-4b112ff9ca8b', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 1, 12, '“አንተም ወንድምህን ዕብራዊዉን ወይም ዕብራዊቱን ብትገዛ ስድስት ዓመት ያገልግሉህ፤ በሰባተኛውም ዓመት ከአንተ ዘንድ አርነት አውጥተህ ልቀቀው።'),
  ('df49f954-3914-5f7a-a42e-35f08470c14d', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 2, 13, 'ከአንተም ዘንድ አርነት አውጥተህ በለቀቅኸው ጊዜ ባዶውን አትልቀቀው።'),
  ('6903e8c8-1470-50b5-a314-4a8a6ae3e981', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 3, 14, 'ነገር ግን ከበጎችህ፥ ከእህልህም፥ ከወይንህም መጭመቂያ ስንቅ ትሰንቅለታለህ፤ አምላክህ እግዚአብሔር እንደ ባረከህ መጠን ትሰጠዋለህ።'),
  ('b99d0b11-53dc-54ad-a803-e2c73072ba6f', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 4, 15, 'አንተም በግብፅ ምድር ባሪያ እንደ ነበርህ፥ አምላክህም እግዚአብሔር ከዚያ እንዳዳነህ ዐስብ፤ ስለዚህ እኔ ዛሬ ይህን ነገር አዝዝሃለሁ።'),
  ('3aa427d5-d716-5708-a99d-967066029061', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 5, 16, 'እርሱ ግን አንተንና ቤትህን ስለ ወደደ፥ በአንተም ዘንድ መኖር መልካም ስለሆነለት፦ ‘አልወጣም’ ቢል፥'),
  ('419ffbbc-ce3c-5e7f-ac79-6a8a9b44461d', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 6, 17, 'አንተ ወስፌ ወስደህ በቤትህ በር ላይ ጆሮውን ትበሳዋለህ፤ ለዘለዓለምም ባሪያ ይሆንልሃል። በሴት ባሪያህም ደግሞ እንዲሁ ታደርጋለህ።'),
  ('fabd90fc-2b3e-586f-ae0a-0b79c66a7b24', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'bf21eee0-719a-5060-aca4-4f6241813abf', 7, 18, 'እርሱንም አርነት ባወጣኸው ጊዜ የምንደኝነቱን ሥራ ሁለት ዕጥፍ አድርጎ ስድስት ዓመት አገልግሎሃልና አያስጨንቅህ፤ አምላክህም እግዚአብሔር በምትሠራው ሁሉ ይባርክሃል።'),
  ('71ab3c05-3482-5468-acff-85ff220a263e', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'd82eb643-e7d4-5303-a06d-8f192bb7db19', 1, 19, '“ላምህና በግህ የወለዱትን ተባት የሆነውን በኵራት ለአምላክህ ለእግዚአብሔር ትቀድሳለህ፤ በበሬህ በኵራት አትሥራበት፤ የበግህንም በኵራት አትሸልት።'),
  ('653ae3db-7419-50f6-a002-50a3d215162e', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'd82eb643-e7d4-5303-a06d-8f192bb7db19', 2, 20, 'አምላክህ እግዚአብሔር በመረጠው ስፍራ አንተና ቤተ ሰብህ በየዓመቱ በአምላክህ በእግዚአብሔር ፊት ብላው።'),
  ('9aa258a4-3ad4-52d1-ab5e-6285e049ab15', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'd82eb643-e7d4-5303-a06d-8f192bb7db19', 3, 21, 'ነውረኛ ወይም አንካሳ ወይም ዕውር ቢሆን፥ ወይም አንዳች ክፉ ነውር ቢኖረው፥ ለአምላክህ ለእግዚአብሔር አትሠዋው።'),
  ('05ae816c-d37b-5561-aa8d-8d219604ed2c', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'd82eb643-e7d4-5303-a06d-8f192bb7db19', 4, 22, 'በሀገርህ ውስጥ ትበላዋለህ፤ ንጹሕ ሰው፥ ንጹሕም ያልሆነ፥ ሚዳቋንና ዋሊያን እንደሚበሉ ይበሉታል።'),
  ('e53a1beb-2f1c-5b8c-ad44-4f57e2c337b1', '48c2799e-5dbd-5da8-aa96-098f75494b34', 'd82eb643-e7d4-5303-a06d-8f192bb7db19', 5, 23, 'ነገር ግን ደሙን በምድር ላይ እንደ ውኃ አፍስሰው እንጂ አትብላው።'),
  ('95f17614-7c47-5eca-a38c-b557dcbb367b', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 1, 1, '“በሚያዝያ ወር ከግብፅ ሀገር በሌሊት ወጥተሃልና የሚያዝያን ወር ጠብቀህ፥ የአምላክህ የእግዚአብሔርን ፋሲካ አድርግ።'),
  ('3003ae34-e5f1-5328-a06d-d99881d956de', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 2, 2, 'አምላክህ እግዚአብሔር በዚያ ስሙ ይጠራበት ዘንድ በመረጠው ስፍራ ለአምላክህ ለእግዚአብሔር ፋሲካ ከበግና ከላም መንጋ ሠዋ።'),
  ('eabe38e0-5bb2-5fe2-a39b-bc5edb9abb9d', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 3, 3, 'የቦካውን እንጀራ ከእርሱ ጋር አትብላ፤ ከግብፅ ሀገር በችኮላ ስለ ወጣህ ከግብፅ ሀገር የወጣህበትን ቀን በዕድሜህ ሁሉ ታስብ ዘንድ የመከራን እንጀራ፥ ቂጣ እንጀራ ሰባት ቀን ከእርሱ ጋር ብላ።'),
  ('5769e268-a8a1-5a6a-a6f4-53d27d2fdd4d', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 4, 4, 'ሰባት ቀንም በሀገርህ ሁሉ የቦካ አይታይም፤ በመጀመሪያው ቀን ማታ ከሠዋኸው ሥጋ እስከ ነገ ድረስ ምንም አይደር።'),
  ('f02379ea-b573-5b45-a0af-b0675d0d790a', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 5, 5, 'አምላክህ እግዚአብሔር ከሰጠህ ከተሞች በማንኛዪቱም ፋሲካን ትሠዋ ዘንድ አይገባህም።'),
  ('4d5d4cad-5c29-532c-a1d7-f4e07d4515a6', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 6, 6, 'ነገር ግን አምላክህ እግዚአብሔር ስሙ ይጠራበት ዘንድ በመረጠው በዚያ ስፍራ ከግብፅ በወጣህበት ወራት፥ ፀሐይ ሲገባ፥ ማታ ፋሲካን ትሠዋለህ።'),
  ('95838c83-f930-5333-a207-9087294f9aa3', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 7, 7, 'አምላክህ እግዚአብሔር በመረጠው ስፍራ ትጠብሰዋለህ፤ ታበስለዋለህም፤ ትበላውማለህ፤ በነጋውም ተመልሰህ ወደ ቤትህ ትሄዳለህ።'),
  ('17aafd10-fc0b-5fc3-acde-a5d9aeaa68f9', '04a567f9-09ad-5cd0-a458-e270b36386a5', '709df8c5-5d18-50a8-a91e-ffe0ebbcee04', 8, 8, 'ስድስት ቀን ቂጣ እንጀራ ብላ፤ ሰባተኛው ቀን ግን መውጫው ስለሆነ ለአምላክህ ለእግዚአብሔር በዓል ይሁን፤ ለነፍስም ከሚሠራው በቀር ሥራን ሁሉ አታድርግበት።'),
  ('304faadc-68b5-5a91-a66a-15cdda328d30', '04a567f9-09ad-5cd0-a458-e270b36386a5', '14dd7417-46ca-52b2-ab48-b56b4d480bac', 1, 9, '“ሰባት ሳምንትም ትቈጥራለህ፤ መከሩን ማጨድ ከምትጀምርበት ቀን ጀምሮ ሰባት ሳምንት መቍጠር ትጀምራለህ።'),
  ('83056d64-134f-5368-acd4-1094c98dcaa9', '04a567f9-09ad-5cd0-a458-e270b36386a5', '14dd7417-46ca-52b2-ab48-b56b4d480bac', 2, 10, 'አምላክህ እግዚአብሔር የባረከህን ያህል እጅህ መስጠት በምትችለው መጠን ለአምላክህ ለእግዚአብሔር የሰባቱን ሱባዔ በዓል ታደርጋለህ።'),
  ('9f9feddf-6ddd-5394-a336-48a32febaa46', '04a567f9-09ad-5cd0-a458-e270b36386a5', '14dd7417-46ca-52b2-ab48-b56b4d480bac', 3, 11, 'አንተ፥ ወንድ ልጅህና ሴት ልጅህ፥ ወንድ ባሪያህና ሴት ባሪያህ፥ በሀገርህም ውስጥ ያለው ሌዋዊ፥ በመካከልህም ያሉ መጻተኛና ድሃ-አደግ፥ መበለትም አምላክህ እግዚአብሔር በዚያ ስሙ ይጠራበት ዘንድ በሚመርጠው ስፍራ በአምላክህ በእግዚአብሔር ፊት ደስ ይበላችሁ።'),
  ('f5a339f2-c332-5e5e-a709-53702b710aa1', '04a567f9-09ad-5cd0-a458-e270b36386a5', '14dd7417-46ca-52b2-ab48-b56b4d480bac', 4, 12, 'አንተም በግብፅ ባሪያ እንደ ነበርህ ዐስብ፤ ይህንም ሥርዐት ጠብቅ፤ አድርገውም።'),
  ('99934395-11d7-59be-a819-e23991bb429a', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'a38d2186-34f8-5705-a59b-60ae66382129', 1, 13, '“ከአውድማህና ከወይን መጭመቂያህ ፍሬህን በሰበሰብህ ጊዜ ሰባት ቀን የዳስ በዓል አድርግ።'),
  ('b1136cd9-f349-5eac-aa43-98c39fc7d166', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'a38d2186-34f8-5705-a59b-60ae66382129', 2, 14, 'አንተም፥ ወንድ ልጅህና ሴት ልጅህ፥ ወንድ ባሪያህና ሴት ባሪያህ፥ በሀገርህም ውስጥ ያለ ሌዋዊና መጻተኛ፥ ድሃ-አደግና መበለትም በበዓልህ ደስ ይበላችሁ።'),
  ('3021b64e-29e8-57fd-a718-c4337e6c0949', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'a38d2186-34f8-5705-a59b-60ae66382129', 3, 15, 'አምላክህ እግዚአብሔር ለራሱ በመረጠው ስፍራ ለአምላክህ ለእግዚአብሔር ሰባት ቀን በዓል ታደርጋለህ፤ አምላክህ እግዚአብሔር በፍሬህ ሁሉ፥ በእጅህም ሥራ ሁሉ ይባርክሃልና። አንተም ፈጽሞ ደስ ይልሃልና።'),
  ('6872fa80-b724-5d98-a7c4-71c74a916b72', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'a38d2186-34f8-5705-a59b-60ae66382129', 4, 16, 'በዓመት ሦስት ጊዜ በቂጣ በዓል፥ በሰባቱ ሱባዔም በዓል፥ በዳስም በዓል ወንድ ልጅህ ሁሉ በአምላክህ በእግዚአብሔር ፊት እግዚአብሔር በመረጠው ስፍራ ይታይ፤'),
  ('82ad0470-85b5-58c5-a1b5-6de16db3f185', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'a38d2186-34f8-5705-a59b-60ae66382129', 5, 17, 'በአምላክህ በእግዚአብሔር ፊት ባዶ እጅህን አትታይ። አምላካችሁ እግዚአብሔር በሰጣችሁ በረከት መጠን እያንዳንዳችሁ እንደ ችሎታችሁ ታመጣላችሁ።'),
  ('4341969f-1bc1-5d55-a047-1dafa4382d6f', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'db38c9d9-4617-539e-adef-2b863d161e67', 1, 18, '“አምላክህ እግዚአብሔር በሚሰጥህ በሀገርህ ደጅ ሁሉ በየነገዶችህ ፈራጆችንና መባውን የሚጽፉትን ሹሙ፤ ለሕዝቡም ቅን ፍርድን ይፍረዱ።'),
  ('fae67dc5-8464-5684-a6ad-39c09b730052', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'db38c9d9-4617-539e-adef-2b863d161e67', 2, 19, 'ፍርድን አታጣምም፤ ፊት አይተህም አታድላ፤ ጉቦን አትቀበል፥ ጉቦ የጥበበኞችን ዐይን ያሳውራልና፥ የእውነትንም ቃል ያጣምማልና ጉቦ አትቀበል።'),
  ('e16f2267-b5ae-58f8-afcf-e944ee15e55d', '04a567f9-09ad-5cd0-a458-e270b36386a5', 'db38c9d9-4617-539e-adef-2b863d161e67', 3, 20, 'በሕይወት ትኖር ዘንድ፥ አምላክህ እግዚአብሔርም የሚሰጥህን ምድር ትወርስ ዘንድ እውነተኛውን ፍርድ ተከተል።'),
  ('35ab52b4-cbf4-538a-abfc-b8d854a35f5d', '04a567f9-09ad-5cd0-a458-e270b36386a5', '8f565091-04c7-52f3-a132-4dc646a66f70', 1, 21, '“ለአንተ በምትሠራው በአምላክህ በእግዚአብሔር መሠዊያ አጠገብ ከማናቸውም ዛፍ የማምለኪያ ዐጸድ አድርገህ አትትከል።'),
  ('6223e1b9-9a5d-5ecc-a4a2-79fa870eaedd', '04a567f9-09ad-5cd0-a458-e270b36386a5', '8f565091-04c7-52f3-a132-4dc646a66f70', 2, 22, 'አምላክህ እግዚአብሔርም የሚጠላውን ሐውልት ለአንተ አታቁም።'),
  ('f8c443ff-3b2b-59db-aea7-11732dc2367f', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 1, 1, '“በአምላክህ በእግዚአብሔር ዘንድ የተጠላ ነውና ነውር ወይም ክፉ ነገር ያለበትን በሬ ወይም በግ ለአምላክህ ለእግዚአብሔር አትሠዋ።'),
  ('337865a3-f0f6-5ab1-ab75-e4141c168e4b', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 2, 2, '“አምላክህ እግዚአብሔር ከሰጠህ ሀገሮች በአንዲትዋ ውስጥ ወንድ ወይም ሴት ቢሆን ቃል ኪዳኑን በማፍረስ በአምላክህ በእግዚአብሔር ፊት ክፋት የሠራ ቢገኝ፥'),
  ('562b2615-f7e3-55da-af3e-90a7ced7e285', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 3, 3, 'ሄዶም ሌሎች አማልክትን ያመለከ፥ አምላክህ እግዚአብሔር ላላዘዘህ ለፀሐይና ለጨረቃ ወይም ለሰማይ ከዋክብት የሰገደ ቢገኝ፥'),
  ('8358fe1b-fd8a-5674-aeca-c62361248cce', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 4, 4, 'ቢያወሩልህም ብትሰማም፥ ያን ፈጽመህ መርምር፤ እነሆም፥ እውነት ቢሆን፥ በእስራኤልም መካከል እንዲህ ያለ ርኵሰት እንደ ተሠራ ርግጥ ሆኖ ቢገኝ፥'),
  ('c532f1e0-f0ec-5484-af0d-cc02f750fb7c', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 5, 5, 'ይህን ክፉ ነገር የሠሩትን ያን ወንድ ወይም ያችን ሴት ታወጣቸዋለህ፥ እስኪሞቱም ድረስ በድንጋይ ትመትዋቸዋላችሁ።'),
  ('4a8b2dca-0574-56c2-afce-7df2d6e64169', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 6, 6, 'በሁለት ወይም በሦስት ምስክሮች ሞት የሚገባቸው ይገደሉ፤ በአንድ ምስክር ግን አይገደሉ።'),
  ('e875e143-b1a6-5511-af95-f5d312eb9bfd', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '1d6d2060-9b6d-5c24-aaf6-d6728e21a813', 7, 7, 'እርሱን ለመግደል በመጀመሪያ የምስክሮች እጅ በኋላም የሕዝቡ ሁሉ እጅ ትሁንበት፤ እንዲሁ ክፉውን ከመካከላችሁ አስወግዱ።'),
  ('d76c1003-b035-5d3b-a8aa-7eb49e6c9d28', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '9a05d585-19ca-59bf-a592-7d2b12837a12', 1, 8, '“በደምና በደም መካከል፥ በፍርድና በፍርድ መካከል፥ በመቍሰልና በመቍሰል መካከል፥ በክርክርና በክርክር መካከል በሀገርህ ውስጥ ሰዎች ስለሚከራከሩበት ክርክር የሚሳንህ የፍርድ ነገር ቢኖር፥ አንተ ተነሥተህ ስሙ በዚያ ይጠራ ዘንድ አምላክህ እግዚአብሔር ወደ መረጠው ስፍራ ትወጣለህ፤'),
  ('e46fc35a-fbfc-5025-acfd-9c45991a29f7', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '9a05d585-19ca-59bf-a592-7d2b12837a12', 2, 9, 'ወደ ሌዋውያን ካህናት በዚያም ዘመን ወደ አሉ ፈራጆች መጥተህ ትጠይቃለህ፤ እነርሱም የፍርዱን ነገር ይነግሩሃል።'),
  ('a2e7b788-3f87-504d-af7c-5761026dc69e', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '9a05d585-19ca-59bf-a592-7d2b12837a12', 3, 10, 'ስሙ በዚያ ይጠራ ዘንድ አምላክህ እግዚአብሔር በመረጠው ስፍራ እንደ ነገሩህ ቃል ታደርጋለህ፤ ያስተማሩህንም ሕጉን ታደርግ ዘንድ ጠብቅ።'),
  ('4bc0b511-6f82-5bd6-ae8a-618beeab72b0', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '9a05d585-19ca-59bf-a592-7d2b12837a12', 4, 11, 'እንዳስተማሩህም ሕግ፥ እንደ ነገሩህም ፍርድ አድርግ፤ ከነገሩህ ፍርድ ወደ ቀኝም ወደ ግራም አትበል።'),
  ('3b2435d5-9e4c-5d6e-a259-5fb40e096090', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '9a05d585-19ca-59bf-a592-7d2b12837a12', 5, 12, 'ማናቸውም ሰው ቢኰራ፥ በአምላክህ እግዚአብሔር ስም ለማገልገል የሚቆመውን ካህኑን ወይም በዚያ ወራት ያለውን ፈራጁን ባይሰማ ያ ሰው ይሙት፤ ከእስራኤልም ዘንድ ክፉውን አስወግዱ፤'),
  ('e8ed5708-b07b-5734-afc0-0363bf0c152b', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', '9a05d585-19ca-59bf-a592-7d2b12837a12', 6, 13, 'ሕዝቡም ሁሉ ሰምቶ ይፈራል፤ ከዚያም ወዲያ ደግሞ አይበድልም።'),
  ('334d522a-3ca4-52fc-aa52-d7f75d961b50', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 1, 14, '“አምላክህ እግዚአብሔር ርስት አድርጎ ወደሚሰጥህ ምድር በገባህ፥ በወረስሃትም ጊዜ፥ በተቀመጥህባትም ጊዜ፦ በዙሪያዬ እንዳሉት አሕዛብ ሁሉ በላዬ አለቃ እሾማለሁ ብትል፥'),
  ('b2e5dacc-df0f-575b-aedc-56c9c33c266b', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 2, 15, 'ከወንድሞችህ መካከል አምላክህ እግዚአብሔር የመረጠውን ለአንተ አለቃ ትሾማለህ፤ ወንድምህ ያልሆነውን ሌላ ሰው በአንተ ላይ መሾም አትችልም።'),
  ('10d9b07b-fda7-5283-a176-ff232ba55f7e', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 3, 16, 'ለእርሱ ፈረሶችን እንዳያበዛ፥ ሕዝቡንም ወደ ግብፅ እንዳይመልስ፤ እግዚአብሔር፦ በዚያች መንገድ መመለስን አትድገም ብሎአልና።'),
  ('c4bdb804-c238-5c2c-aa6a-1fc84b9ba6b9', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 4, 17, 'ልቡም እንዳይስት ሚስቶችን ለእርሱ አያብዛ፤ ወርቅና ብርም ለእርሱ እጅግ አያብዛ።'),
  ('f56e26fd-ec12-50a1-acbb-dbf38e8986c7', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 5, 18, '“በግዛቱም በተቀመጠ ጊዜ ከሌዋውያን ካህናት ወስዶ ይህን ሁለተኛ ሕግ ለራሱ በመጽሐፍ ይጻፍ።'),
  ('988272e7-92f7-5b57-ad6d-5945f43da4ff', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 6, 19, 'መጽሐፉ ከእርሱ ጋር ይኑር፤ ዕድሜውንም ሁሉ ያንብበው። አምላኩን እግዚአብሔርን መፍራት ይማር ዘንድ፥ የዚህን ሕግ ቃል ሁሉ፥ ይህችንም ሥርዐት ጠብቆ ያደርግ ዘንድ፥'),
  ('58c967bf-539f-5c0b-a24f-b1648e880cc7', 'ce7e2c99-a65c-54c4-a775-4f40b3e1771d', 'e862c676-c64a-59d7-a000-88e78652102a', 7, 20, 'ልቡ በወንድሞቹ ላይ እንዳይኰራ፥ የአምላኩ የእግዚአብሔርን ትእዛዝ እንዳይተው፥ ቀኝና ግራም እንዳይል፥ እርሱም ልጆቹም በእስራኤል ልጆች መካከል ረዥም ዘመን ይገዙ ዘንድ።'),
  ('c2cb631a-e4d3-5288-ae91-88322890545d', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 1, 1, '“ለሌዋውያን ካህናት፥ ለሌዊም ነገድ ሁሉ ከእስራኤል ጋር ድርሻና ርስት አይኑራቸው፤ ለእግዚአብሔር የሚቀርበው መሥዋዕት ድርሻቸው ነው፤ እርሱን ይመገባሉ።'),
  ('b1efcc8e-8f33-5523-a992-753d1b877090', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 2, 2, 'በወንድሞቻቸውም መካከል ርስት አይኖራቸውም፤ እርሱ እንደ ተናገራቸው ርስታቸው እግዚአብሔር ነውና።'),
  ('3f39b635-8be1-550b-af38-0f5ed7e48eca', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 3, 3, 'በሬ ወይም በግ ለመሥዋዕት ከሚያቀርቡት ሕዝብ የካህናቱ ወግ ይህ ይሆናል፤ ወርቹንና ሁለቱን ጕንጮቹን፥ ጨጓራውንም ለካህኑ ይሰጣሉ።'),
  ('bbfb97b0-e07f-5e91-ab33-60140afc1252', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 4, 4, 'የእህልህን፥ የወይንህን፥ የዘይትህንም ቀዳምያት፥ አስቀድሞም የተሸለተውን የበግህን ጠጕር ለእርሱ ትሰጣለህ።'),
  ('51f381ba-8205-5b56-afac-774f6529a862', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 5, 5, 'እርሱ ከልጆቹ ጋር በአምላክህ በእግዚአብሔር ፊት ቁሞ ለዘለዓለም ያገለግል ዘንድ፥ በስሙም ይባርክ ዘንድ አምላክህ እግዚአብሔር ከነገዶችህ ሁሉ መርጦታልና።'),
  ('8eddbddd-3201-5b1d-a667-2308305515b9', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 6, 6, '“አንድ ሌዋዊ ሰው ከሚቀመጥባቸው በእስራኤል ሁሉ ዘንድ ካሉት ከተሞች ከአንዲቱ፥ በፍጹም ልብም ሊያገለግል እግዚአብሔር ወደ መረጠው ስፍራ ቢመጣ፥'),
  ('1073c269-b77a-5c07-a834-8e5e4114227e', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 7, 7, 'በእግዚአብሔር ፊት እንደሚቆሙት እንደ ወንድሞቹ እንደ ሌዋውያን ሁሉ በአምላኩ በእግዚአብሔር ስም ያገለግላል።'),
  ('30a2d719-6380-5193-a513-c5c2b20aa28b', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '503436fa-ae9e-5b41-aa0e-e673c5c01d8f', 8, 8, 'ከአባቶቹ ከብት ዋጋ ሌላ እንደ ባልንጀሮቹ ከመብል ድርሻውን ይወስዳል።'),
  ('24a682ff-ca1d-5915-a94b-298aa7bd8a22', '876116e4-e94b-53cf-ae56-5efeb722c1c2', 'e20c8195-c975-5b3e-a1e5-ce517cc5c98c', 1, 9, '“አምላክህ እግዚአብሔር ወደሚሰጥህ ምድር በገባህ ጊዜ እነዚያ አሕዛብ የሚያደርጉትን ርኵሰት ታደርግ ዘንድ አትማር።'),
  ('b405b45f-8d0d-5a1f-abe0-3948ff597f90', '876116e4-e94b-53cf-ae56-5efeb722c1c2', 'e20c8195-c975-5b3e-a1e5-ce517cc5c98c', 2, 10, 'ወንድ ልጁን ወይም ሴት ልጁን በእሳት የሚሠዋ፥ ምዋርተኛም፥ ሞራ ገላጭም፥ አስማተኛም፥ መተተኛም፥'),
  ('83f00503-cf6f-5359-a88c-3518389ab0c9', '876116e4-e94b-53cf-ae56-5efeb722c1c2', 'e20c8195-c975-5b3e-a1e5-ce517cc5c98c', 3, 11, 'በድግምት የሚጠነቍልም፥ መናፍስትንም የሚጠራ፥ ጠንቋይም፥ ሙታን ሳቢም፥ በወፍም የሚያሟርት በአንተ ዘንድ አይገኝ።'),
  ('ebad771c-d98b-5263-af3d-834fba39099d', '876116e4-e94b-53cf-ae56-5efeb722c1c2', 'e20c8195-c975-5b3e-a1e5-ce517cc5c98c', 4, 12, 'ይህንም የሚያደርግ ሁሉ በእግዚአብሔር ፊት የተጠላ ነው፤ ስለዚህም ርኵሰት አምላክህ እግዚአብሔር ከፊትህ ያጠፋቸዋል።'),
  ('66719e81-d792-5dfe-a5b0-374489b8b040', '876116e4-e94b-53cf-ae56-5efeb722c1c2', 'e20c8195-c975-5b3e-a1e5-ce517cc5c98c', 5, 13, 'አንተ ግን በአምላክህ በእግዚአብሔር ዘንድ ፍጹም ሁን።'),
  ('5f771e37-5a27-5dbf-a6e6-075ada880193', '876116e4-e94b-53cf-ae56-5efeb722c1c2', 'e20c8195-c975-5b3e-a1e5-ce517cc5c98c', 6, 14, 'አንተ የምትወርሳቸው እነዚህ አሕዛብ ሞራ ገላጮችንና ምዋርተኞችን ያዳምጣሉ፤ ለአንተ ግን እንዲህ አይደለም፤ አምላክህ እግዚአብሔር አልፈቀደምና።'),
  ('a2106095-e42d-59a9-a4c4-4c913d3d8e82', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 1, 15, '“አምላክህ እግዚአብሔር ከወንድሞችህ እንደ እኔ ያለ ነቢይ ያስነሣልሃል፤ እርሱንም ስሙት።'),
  ('c0db0999-835b-5448-a721-b0d3aa9a9e98', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 2, 16, 'አምላካችሁን እግዚአብሔርን በኮሬብ በተሰበሰባችሁበት ቀን፦ ‘እንዳንሞት የአምላካችን የእግዚአብሔርን ድምፅ ደግሞ አንስማ፤ ይህችን ታላቅ እሳት ደግሞ አንይ’ ብላችሁ እንደ ለመናችሁት ሁሉ።'),
  ('4dcf9007-2057-5ec4-ad9b-99cc46f6b6ad', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 3, 17, 'እግዚአብሔርም አለኝ፦ ለአንተ የተናገሩት ሁሉ ልክ ነው።'),
  ('31129576-d59f-5990-a704-b316fc280699', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 4, 18, 'ከወንድሞቻቸው እንደ አንተ ያለ ነቢይ አስነሣላቸዋለሁ፤ ቃሌንም በአፉ አኖራለሁ፤ እንደ አዘዝሁትም ይነግራቸዋል፤'),
  ('8be05d53-8225-5233-a883-c6e3141dadb1', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 5, 19, 'በስሜም በሚናገረው ሁሉ ያን ነቢይ የማይሰማውን ሰው እኔ እበቀለዋለሁ።'),
  ('282f7dae-b186-5399-ad20-8d852f05a485', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 6, 20, 'ነገር ግን ይናገር ዘንድ ያላዘዝሁትን ቃል በስሜ የሚናገር ነቢይ፥ በሌላ አማልክት ስም የሚናገር ነቢይም፥ እርሱ ይገደል።'),
  ('953443f8-f244-5692-a0cd-c5964b70edd2', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 7, 21, 'በልብህም፦ እግዚአብሔር ያልተናገረውን ቃል እንዴት አውቃለሁ ብትል፥'),
  ('a39a996d-8e92-5f16-a1e4-1c53c5d7742f', '876116e4-e94b-53cf-ae56-5efeb722c1c2', '9fe9d656-edcc-5d2e-a9d9-fae6ac8125ee', 8, 22, 'ያ ነቢይ በእግዚአብሔር ስም ከተናገረው ሁሉ ቃሉ ባይደርስ፤ እንደ ተናገረውም ባይሆን እግዚአብሔር ያን ቃል አልተናገረውም፤ ነቢዩ በሐሰት ተናግሮታልና አትስማው።'),
  ('3ab9e955-ee43-5f11-abe4-268b235c5d39', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 1, 1, '“አምላክህ እግዚአብሔር ምድራቸውን የሚሰጥህን አሕዛብ ባጠፋቸው ጊዜ፥ በወረስሃቸውም ጊዜ፥ በከተሞቻቸውና በቤቶቻቸውም በተቀመጥህ ጊዜ፥'),
  ('3d60ed4f-78b9-5849-abb2-afae835fe4b1', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 2, 2, 'አምላክህ እግዚአብሔር በሚሰጥህ በምድርህ መካከል ሦስት ከተሞችን ለራስህ ትለያለህ።'),
  ('9e6015f2-ad62-5eba-a122-94e2d951b23a', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 3, 3, 'ለአንተም መንገድህን ታዘጋጃለህ፤ አምላክህም እግዚአብሔር የሚያወርስህን ምድር ከሦስት አድርገህ ትከፍላለህ፤ ለነፍሰ ገዳይም ሁሉ መማጸኛ ይሁን።'),
  ('0a36cbb5-0aeb-5647-afe8-0828b6b4f897', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 4, 4, '“የነፍሰ ገዳይ ሕግ ይህ ነው፤ ቀድሞ ጠላቱ ሳይሆን ባልንጀራውን ሳያውቅ የገደለ ወደዚያ ሸሽቶ በሕይወት ይኑር።'),
  ('d23be4d1-e7c4-5cf8-aeae-473346ec70e6', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 5, 5, 'ሰው ከባልንጀራው ጋር እንጨት ሊለቅም ወደ ዱር ቢሄድ፥ ዛፉንም ሲቈርጥ ምሳሩ ከእጁ ቢወድቅ፥ ብረቱም ከእጄታው ቢወልቅ፥ በባልንጀራውም ላይ ቢወድቅና ቢገድለው፥ ከእነዚህ ከተሞች በአንዲቱ ተማጥኖ በሕይወት ይኖራል፤'),
  ('ef9e7e4b-1a75-5b56-a3e7-e4ae6affa8b3', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 6, 6, 'ባለ ደሙ ነፍሰ ገዳዩን በልቡ ተናድዶ እንዳያሳድደው መንገዱም ሩቅ ስለሆነ አግኝቶ እንዳይገድለው፥ አስቀድሞ ጠላቱ አልነበረምና ሞት አይገባውም።'),
  ('b148c80d-8ad8-59ea-a7df-1c2d87d6be14', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 7, 7, 'ስለዚህ እኔ፦ ለአንተ ሦስት ከተሞችን ለይ ብዬ አዝዤሃለሁ።'),
  ('09b3c738-b3bb-51ec-a1c3-07a41a94901c', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 8, 8, 'አምላክህም እግዚአብሔር ለአባቶችህ እንደ ማለላቸው ዳርቻህን ቢያሰፋ፥ ለአባቶችህ እሰጣቸዋለሁ ብሎ የተናገረውን ምድር ሁሉ ቢሰጥህ፥'),
  ('e3108d51-2b43-5909-a347-1b721d5bd051', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 9, 9, 'አምላክህን እግዚአብሔርን ትወድድ ዘንድ፥ ሁልጊዜም በመንገዱ ሁሉ ትሄድ ዘንድ፥ ዛሬ የማዝዝህን ይህችን ትእዛዝ ሁሉ ታደርጋት ዘንድ ብትሰማ፥ በእነዚህ በሦስት ከተሞች ላይ ሌሎች ሦስት ከተሞችን ትጨምራለህ።'),
  ('d5173dc2-f338-56f8-ae0a-8f7a5d610753', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 10, 10, 'አምላክህ እግዚአብሔር ትወርሳት ዘንድ በሚሰጥህ ምድር ውስጥ ንጹሕ ደም እንዳይፈስስ፥ በውስጥህም የደም ወንጀለኛ እንዳይኖር።'),
  ('e3cae3fc-e199-560a-ad9c-fe226acaa356', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 11, 11, '“ሰው ግን ባልንጀራውን ቢጠላ፥ ቢሸምቅበትም፥ በእርሱም ላይ ቢነሣ፥ ቢገድለውም፥ ከእነዚህ ከተሞች በአንዲቱ ቢማጠን፥'),
  ('392e4fd1-b639-5d79-a2c4-d25174c395aa', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 12, 12, 'የከተማው ሽማግሌዎች ይልካሉ፤ ከዚያም ይይዙታል። በባለደሙም እጅ አሳልፈው ይሰጡታል፤ ይሞታልም።'),
  ('bfa97cfe-c7f9-5047-a497-9a2f3c4a125f', 'e2372401-ea7f-587c-af85-8a0a42337326', 'eef3064d-ac7c-5998-a774-ab6741882bac', 13, 13, 'ዐይንህም አትራራለት፤ ነገር ግን ንጹሑን ደም ከእስራኤል ታስወግዳለህ፤ መልካምም ይሆንልሃል።'),
  ('2b66bb48-8f92-5739-a62c-ec29595c5265', 'e2372401-ea7f-587c-af85-8a0a42337326', '37eb31ed-a42f-5840-a0c2-3fec0061e073', 1, 14, '“አምላክህ እግዚአብሔር ትወርሳት ዘንድ በሚሰጥህ ምድር፤ በምትካፈላት ርስትህ አባቶችህ የተከሉትን የባልንጀራህን የድንበር ምልክት አትንቀል።'),
  ('72da0dee-9425-53d2-ade9-3623a0891bf9', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 1, 15, '“ስለ በደል ሁሉ፥ ክፉ በማድረግም ስለሚሠራት ኀጢአት ሁሉ በማንም ላይ አንድ ምስክር አይሁን፤ በሁለት ምስክሮች ወይም በሦስት ምስክሮች ቃል ነገር ሁሉ ይጸናል።'),
  ('e6ebde37-7195-57a5-af33-b04b082bbd57', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 2, 16, 'በዐመፃ ይከስሰው ዘንድ በሰው ላይ ሐሰተኛ ምስክር ቢቆም፥'),
  ('c7aac591-7b67-51f3-ac7a-40007e32532c', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 3, 17, 'ሁለቱ ጠበኞች በእግዚአብሔር ፊት በካህናቱና በዚያ ዘመን በሚፈርዱ ፈራጆች ፊት ይቆማሉ፤'),
  ('0fb29058-3eeb-5284-ab5c-4af929629c83', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 4, 18, 'ፈራጆቹም አጥብቀው ይመረምራሉ፤ ያም ምስክር ሐሰተኛ ምስክር ሆኖ በወንድሙ ላይ በሐሰት ተናግሮ ቢገኝ፥'),
  ('63bff216-4f30-5594-a83d-c84adf3b9f33', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 5, 19, 'በወንድሙ ላይ ክፋትን ያደርግ ዘንድ እንደ ወደደ በእርሱ ላይ ታደርጉበታላችሁ፤ እንዲሁም ከእናንተ መካከል ክፉውን ታስወግዳላችሁ።'),
  ('5d4e3dd9-af1c-54c6-ab9e-38369d32d003', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 6, 20, 'ሌላውም ሰምቶ ይፈራል፤ እንደዚህ ያለውንም ክፋት በመካከልህ ከእንግዲህ ወዲህ ደግሞ አያደርግም።'),
  ('15f16380-9bf3-5f65-a258-806d0fbc78fd', 'e2372401-ea7f-587c-af85-8a0a42337326', '168cb646-bb0e-56a9-a495-eb1a54112033', 7, 21, 'ዐይንህም አትራራለት፤ ነፍስ በነፍስ፥ ዐይን በዐይን፥ ጥርስ በጥርስ፥ እጅ በእጅ፥ እግር በእግር ይመለሳል።'),
  ('e98bedfe-0ffa-5ebe-a988-523af8de5d60', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 1, 1, '“ጠላቶችህን ለመውጋት በወጣህ ጊዜ፥ ፈረሶችንና ፈረሰኞችን ሕዝቡንም ከአንተ ይልቅ በዝተው ባየህ ጊዜ፥ ከግብፅ ሀገር ያወጣህ አምላክህ እግዚአብሔር ከአንተ ጋር ነውና አትፍራቸው።'),
  ('dd352477-e412-587a-aff8-a75ee3049ac9', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 2, 2, 'ወደ ጦርነትም በቀረባችሁ ጊዜ ካህኑ ይቅረብ፤ ለሕዝቡም እንዲህ ብሎ ይንገራቸው፦'),
  ('94ed5904-07aa-5527-aea5-c73f58e42ae5', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 3, 3, 'እስራኤል ሆይ፥ ስማ፤ ዛሬ ጠላቶቻችሁን ለመውጋት ትሄዳላችሁ፤ ልባችሁ አይታወክ፤ አትፍሩ፤ አትሸበሩ፤ ከፊታቸውም ፈቀቅ አትበሉ፤'),
  ('18fbc260-7639-5504-a25c-d1c276b4d773', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 4, 4, 'ከእናንተ ጋር የሚሄድ፥ ያድናችሁም ዘንድ ጠላቶቻችሁን ስለ እናንተ የሚወጋ አምላካችሁ እግዚአብሔር ነውና።'),
  ('f211ec29-281e-55cc-a4ee-231df197f670', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 5, 5, 'ጸሐፍትም ለሕዝቡ እንዲህ ብለው ይናገሩ፦ አዲስ ቤት ሠርቶ ያላስመረቀ ሰው ቢኖር በጦርነት እንዳይሞት ሌላም ሰው እንዳያስመርቀው ወደ ቤቱ ተመልሶ ይሂድ።'),
  ('41881cf6-b0d5-53f6-a152-ec248e8c601b', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 6, 6, 'ወይንም ተክሎ ደስ ያልተሰኘበት ሰው ቢኖር በጦርነት እንዳይሞት ሌላም ሰው ደስ እንዳይሰኝበት ወደ ቤቱ ተመልሶ ይሂድ።'),
  ('7189b939-e06f-599c-ae5e-aa9fa3444c46', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 7, 7, 'ሚስትም አጭቶ ያላገባት ሰው ቢኖር በጦርነት እንዳይሞት ሌላም ሰው እንዳያገባት ወደ ቤቱ ተመልሶ ይሂድ።'),
  ('f30b9fb6-cac8-5407-ac55-f9d9c3d90edc', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 8, 8, 'ጸሐፍቱም ደግሞ ጨምረው፦ ማንም ፈሪና ልበ ድንጉጥ ሰው ቢሆን የወንድሞቹን ልብ እንደ እርሱ እንዳያስፈራ ወደ ቤቱ ተመልሶ ይሂድ ብለው ለሕዝቡ ይናገሩ።'),
  ('b5a6229b-fce1-5339-a575-27ed4f3003f7', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 9, 9, 'ጸሐፍቱም ለሕዝቡ ነግረው በጨረሱ ጊዜ ከታላላቁ ሕዝብ መካከል የሠራዊት አለቆችን ይሹሙ።'),
  ('b73b7708-6fb0-5e9e-a1db-971011e6f906', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 10, 10, '“ለመዋጋት ወደ አንዲት ከተማ በደረስህ ጊዜ አስቀድመህ በሰላም ቃል ጥራቸው።'),
  ('05224083-b7c7-5b85-a794-4370e32571c0', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 11, 11, 'የሰላም ቃልም ቢመልሱልህ ደጅም ቢከፍቱልህ፥ በከተማው ያለው ሕዝብ ሁሉ ይገብሩልህ፤ አገልጋዮችም ይሁኑህ።'),
  ('d038f30e-66c2-55c2-a44d-ca08f2c3eebf', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 12, 12, 'የሰላም ቃልም ባይመልሱልህ ከአንተም ጋር መዋጋት ቢወድዱ፥ አንተ ከተማዪቱን ትከብባለህ፤'),
  ('46316b81-5d0b-5dad-a7fd-ba3f9190f2f9', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 13, 13, 'አምላክህ እግዚአብሔር በእጅህ አሳልፎ በሰጣት ጊዜ፥ በእርስዋ ያሉትን ወንዶች ሁሉ በሰይፍ ስለት ትገድላቸዋለህ፤'),
  ('fae59df9-f5e9-5946-a097-edb78f17bc9d', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 14, 14, 'ከሴቶቹና ከጓዙ በቀር እንስሶቹን፥ በከተማዪቱም ያለውን ምርኮ ሁሉ ዘርፈህ ለአንተ ትወስዳለህ፤ አምላክህም እግዚአብሔር የሚሰጥህን የጠላቶችህን ምርኮ ትበላለህ።'),
  ('722c8d6e-2801-5c14-aeb2-abc2a844470c', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 15, 15, 'አምላክህ እግዚአብሔር ትወርስ ዘንድ ምድራቸውን ከሚሰጥህ ከእነዚህ አሕዛብ ከተሞች ባይደሉት ከአንተ እጅግ በራቁት ከተሞች ሁሉ እንዲሁ ታደርጋለህ።'),
  ('68e5b569-2644-5cd2-ad7e-cc0b57f67ed5', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 16, 16, 'ከእነርሱም ምንም ነፍስ አታድንም።'),
  ('5019c4a2-cb61-5e74-a0b0-225c7f4682f8', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 17, 17, 'ነገር ግን አምላክህ እግዚአብሔር እንዳዘዘህ ኬጤዎናዊዉን፥ አሞሬዎናዊዉን፥ ከነዓናዊዉንም፥ ፌርዜዎናዊዉንም፥ ኤዌዎናዊዉንም፥ ኢያቡሴዎናዊዉንም፥ ጌርጌሴዎናዊዉንም ፈጽመህ ትረግማቸዋለህ።'),
  ('71cdf475-d1c1-5610-a18c-a2a70fe09e6a', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 18, 18, 'ለአማልክቶቻቸው ያደረጉትን ርኵሰት ሁሉ ታደርጉ ዘንድ እንዳያስተምሩአችሁ፥ በአምላካችሁ በእግዚአብሔር ላይ ኀጢአት እንዳትሠሩ ትረግማቸዋለህ።'),
  ('9fd55765-1aa1-5616-a14d-cf7cfc19a52c', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 19, 19, '“ከተማዪቱን ለመውጋትና ለመውሰድ ብዙ ቀን ብትከብባት፥ ምሳርህን አንሥተህ ዛፎችዋን አትቍረጥ፤ ከእነርሱ ትበላለህና አትቍረጣቸው፤ ወደ አንተ ይመጣና ወደ ቅጥርህም ይገባ ዘንድ የምድር ዛፍ ሰው መሆኑ ነውን?'),
  ('9ec98af5-770b-50d1-ae9e-fb7f2920f1eb', 'd9fbaa59-b27a-5e5f-a034-4f4dfd6a9c14', 'a9b6178f-07d0-552c-a62b-f5044467b42d', 20, 20, 'ለመብል የማይሆኑትን የምታውቃቸውን ዛፎች ታጠፋቸዋለህ፤ ትቈርጣቸውማለህ፤ እስክታሸንፋትም ድረስ በምትዋጋህ ከተማ ላይ ምሽግ ትመሽጋለህ።'),
  ('22debba7-e211-542f-a95f-e91b36f1650e', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 1, 1, '“አምላክህ እግዚአብሔር ትወርሳት ዘንድ በሚሰጥህ ምድር የተገደለ ሰው በሜዳ ወድቆ ቢገኝ፥ ገዳዩም ባይታወቅ፥'),
  ('558cc30c-5f99-5e9f-af08-e737876f8a81', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 2, 2, 'ሽማግሌዎችህና ፈራጆችህ ወጥተው በተገደለው ሰው ዙሪያ እስካሉት ከተሞች ድረስ በስፍር ይለኩ፤'),
  ('e9965ebd-6865-5261-a163-6f91ffbdfd10', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 3, 3, 'ለተገደለውም ሰው አቅራቢያ የሆነች የከተማዪቱ ሽማግሌዎች ከላሞች ለሥራ ያልደረሰችውን፥ ቀንበርም ያልተጫነባትን ጊደር ይውሰዱ፤'),
  ('053d04de-7e1a-5652-a041-71c7743c2e8f', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 4, 4, 'የዚያችም ከተማ ሽማግሌዎች ጊደሪቱን ይዘው ፈሳሽ ውኃ ወዳለበት ወዳልታረሰና ዘርም ወዳልተዘራበት ሽለቆ ይሄዳሉ፤ በዚያም በሸለቆው ውስጥ የጊደሪቱን ቋንጃዋን ይቈርጣሉ።'),
  ('25249bea-9ee5-5de6-abad-894672b845af', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 5, 5, 'የሌዊ ልጆች ካህናትም ይቀርባሉ፤ በፊቱ እንዲያገለግሉ፥ በስሙም እንዲባርኩ አምላክህ እግዚአብሔር መርጦአቸዋልና፤ በእነርሱም ቃል ክርክር ሁሉ ጕዳትም ሁሉ ይቆማልና፤'),
  ('70f01fae-cc09-5cd5-ac5c-c61bbfb79520', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 6, 6, 'ወደ ተገደለው ሰው አቅራቢያ የሆነችው የከተማዪቱ ሽማግሌዎች በሸለቆው ውስጥ ቋንጃዋ በተቈረጠው ጊደር ራስ ላይ እጃቸውን ይታጠቡ፦'),
  ('8937b908-9d06-5d1b-a5fe-477ba32dfb15', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 7, 7, '‘እጆቻችን ይህን ደም አላፈሰሱም፤ ዐይኖቻችንም አላዩም፤'),
  ('d2dde0d7-348a-5961-a507-edbfff0f12fd', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 8, 8, 'አቤቱ፥ ከግብፅ ምድር የተቤዠኸውን ሕዝብህን እስራኤልን ይቅር በል፤ በሕዝብህም በእስራኤል ላይ የንጹሑን ደም በደል አትቍጠር’ ብለው ይናገሩ፤ ስለ ደሙም ይሰረይላቸዋል።'),
  ('e66514f6-d7b3-5616-a2b0-810d7024017d', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '4b331bd3-866c-5d3b-a4bd-ea6a44d58493', 9, 9, 'አንተም በእግዚአብሔር ፊት መልካምና ጥሩ የሆነውን ባደረግህ ጊዜ የንጹሑን ደም በደል ከመካከላቸው ታርቃለህ።'),
  ('00397bb6-8b52-506e-a2e4-b81e348735ef', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'afb9aa43-28e4-5a00-a77b-64aac82ec4c1', 1, 10, '“ጠላቶችህን ልትወጋ በወጣህ ጊዜ አምላክህም እግዚአብሔር በእጅህ አሳልፎ በሰጣቸውና በማረክሃቸው ጊዜ፥'),
  ('ba02552e-3c84-52d5-a57b-a337ecb5fb53', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'afb9aa43-28e4-5a00-a77b-64aac82ec4c1', 2, 11, 'በምርኮው ውስጥ የተዋበች ሴት ብታይ፥ ብትመኛትም፥ ሚስትም ልታደርጋት ብትወድድ፥'),
  ('bee8adf3-bfa9-561f-a402-f95ec95695e4', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'afb9aa43-28e4-5a00-a77b-64aac82ec4c1', 3, 12, 'ወደ ቤትህ ታመጣታለህ፤ ራስዋንም ትላጫታለህ፤ ጥፍርዋንም ትቈርጥላታለህ፤'),
  ('6df690c8-f1ab-5ba5-a97f-f3c7b9f6e509', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'afb9aa43-28e4-5a00-a77b-64aac82ec4c1', 4, 13, 'የተማረከችበትንም ልብስ ታወልቅላታለህ፤ በቤትህም ታስቀምጣታለህ፤ ስለ አባቷና ስለ እናቷ አንድ ወር ሙሉ ታለቅሳለች፤ ከዚያም በኋላ ትደርስባታለህ፤ ባልም ትሆናታለህ፤ እርስዋም ሚስት ትሆንልሃለች።'),
  ('5c5ead52-4c8f-53ef-a84b-b07874ceef70', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'afb9aa43-28e4-5a00-a77b-64aac82ec4c1', 5, 14, 'ከዚያም በኋላ በእርስዋ ደስ ባይልህ አርነት አውጥተህ ትለቅቃታለህ፤ በዋጋ ግን አትሸጣትም፤ አግብተሃታልና እንደባሪያ አትቍጠራት።'),
  ('a4e729bf-bcd5-54f8-a4ec-718a9842a4a2', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'fe7953c0-6ab6-53fa-a218-f2e92df1ea42', 1, 15, '“ለአንድ ሰው አንዲቱ የተወደደች፥ አንዲቱም የተጠላች ሁለት ሚስቶች ቢኖሩት፥ ለእርሱም የተወደደችው፥ ደግሞም የተጠላችው ልጆችን ቢወልዱ፥ በኵሩም ከተጠላችው ሚስት የተወለደው ልጅ ቢሆን፥'),
  ('a6517e03-f010-55e4-a110-c8756aa23f7c', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'fe7953c0-6ab6-53fa-a218-f2e92df1ea42', 2, 16, 'ለልጆቹ ከብቱን በሚያወርስበት ቀን ከተጠላችው ሚስት በተወለደው በበኵሩ ፊት ከተወደደችው ሚስት የተወለደውን ልጅ በኵር ያደርገው ዘንድ አይገባውም፤'),
  ('02e1f482-fd9a-54a3-a5b7-f89dd4151bcb', '3ff77e57-62ad-5a0c-a1dc-45e838535208', 'fe7953c0-6ab6-53fa-a218-f2e92df1ea42', 3, 17, 'ነገር ግን ከከብቱ ሁለት እጥፍ ለእርሱ በመስጠት ከተጠላችው ሚስት የተወለደው ልጅ በኵር እንደ ሆነ ያስታውቅ። የኀይሉ መጀመሪያ ነውና በኵርነቱ የእርሱ ነው።'),
  ('245587f0-03ee-5e40-a968-6371068946a3', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '8d165727-9fd7-54ce-a630-949ae58fcd7e', 1, 18, '“ማንም ሰው ለአባቱ ቃልና ለእናቱ ቃል የማይታዘዝ፥ ቢገሥጹትም የማይሰማቸው ትዕቢተኛና ዐመፀኛ ልጅ ቢኖረው፥'),
  ('58eb9dc7-9377-5e10-ab56-c06882fa7fe2', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '8d165727-9fd7-54ce-a630-949ae58fcd7e', 2, 19, 'አባቱና እናቱ ይዘው ወደ ከተማዉ ሽማግሌዎች፥ ወደሚኖርበትም ስፍራ በር ይውሰዱት፤'),
  ('db3860fe-c906-50d6-ad49-2a517feb5bdb', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '8d165727-9fd7-54ce-a630-949ae58fcd7e', 3, 20, 'የከተማዉንም ሰዎች፦ ‘ይህ ልጃችን ትዕቢተኛና ዐመፀኛ ነው፥ ቃላችንንም አይሰማም፤ ስስታምና ሰካራም ነው’ ይበሉአቸው።'),
  ('d25adb8c-9db3-5cbd-a2b0-474e3aee12d3', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '8d165727-9fd7-54ce-a630-949ae58fcd7e', 4, 21, 'የከተማዉም ሰዎች ሁሉ በድንጋይ ደብድበው ይግደሉት፤ እንዲህም ክፉውን ነገር ከመካከልህ ታርቃለህ፤ እስራኤልም ሁሉ ሰምተው ይፈራሉ።'),
  ('136b776e-3f3c-5309-a62d-0953b2d39959', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '1f261a94-abd4-5739-a7b8-9341c112902d', 1, 22, '“ማንም ሰው ለሞት የሚያበቃውን ኀጢአት ቢሠራ፥ እንዲሞትም ቢፈረድበት፥ በእንጨትም ላይ ብትሰቅለው፥'),
  ('26600e2c-579e-5bd0-a7a6-b9d7e17eb0fe', '3ff77e57-62ad-5a0c-a1dc-45e838535208', '1f261a94-abd4-5739-a7b8-9341c112902d', 2, 23, 'በእንጨት ላይ የተሰቀለ በእግዚአብሔር ዘንድ የተረገመ ነውና ሥጋው በእንጨት ላይ አይደር፤ ነገር ግን አምላክህ እግዚአብሔር ርስት አድርጎ የሰጠህን ምድር እንዳታረክስ በእርግጥ በዚያው ቀን ቅበረው።'),
  ('f3afe571-17bf-5f71-a85e-ad18f0330a7b', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 1, 1, '“የወንድምህ በሬ ወይም በግ በመንገድ ጠፍቶ ብታይ ቸል አትበል፤ እነርሱን መልሰህ ለወንድምህ ስጥ።'),
  ('06c05108-e0a1-59db-abe2-81a502deeec7', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 2, 2, 'ወንድምህም በአቅራቢያህ ባይሆን ወይም ባታውቀው ይዘሃቸው ወደ ቤትህ ትገባለህ፤ ወንድምህ እስኪሻቸው ድረስ በአንተ ዘንድ ይቀመጣሉ፤ ለእርሱም ትመልስለታለህ።'),
  ('a89a92bf-4fb4-528a-a588-6b0f5b0aa427', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 3, 3, 'አህያውም ቢሆን፥ በሬውም ቢሆን፥ ወይም ልብሱ ቢሆን እንዲሁ ታደርጋለህ፤ እንዲሁም በወንድምህ በጠፋበት ነገር ሁሉ ባገኘኸው ጊዜ ታደርጋለህ፤ ቸል ልትለው አይገባህም።'),
  ('48c89cba-e995-5695-a7dc-3869de32c0bf', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 4, 4, 'የወንድምህ አህያው ወይም በሬው በመንገድ ወድቆ ብታይ ቸል አትበላቸው፤ ነገር ግን ከእርሱ ጋር ሆነህ አነሣሣው።'),
  ('a1e67713-b1e8-5521-a001-f89107b20109', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 5, 5, '“ሴት የወንድ ልብስ አትልበስ፤ ወንድም የሴት ልብስ አይልበስ፤ ይህን የሚያደርግ በአምላክህ በእግዚአብሔር ዘንድ የተጠላ ነውና።'),
  ('89754c8d-ca11-5572-a058-3e307fb1a4cf', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 6, 6, '“በመንገድ በማናቸውም ዛፍ ላይ ወይም በመሬት ላይ ከጫጭቶችና ከእንቍላል ጋር እናቲቱ በእነዚህ ላይ ተቀምጣ የወፍ ጎጆ ብታገኝ እናቲቱን ከጫጭቶችዋ ጋር አትውሰድ።'),
  ('a4606de7-b70f-575b-a327-336758751855', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 7, 7, 'ነገር ግን መልካም ይሆንልህ ዘንድ፥ ዕድሜህም ይረዝም ዘንድ እናቲቱን ልቀቅ፤ ጫጭቶችንም ለአንተ ውሰድ።'),
  ('b7fc0159-9f57-5c18-a8d8-1a08438369fe', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 8, 8, '“አዲስ ቤት በሠራህ ጊዜ ማንም ከእርሱ ወድቆ በቤትህ ግድያ እንዳታደርግ ለሰገነትህ መከታ አድርግለት።'),
  ('c457b22f-3481-5b5e-ad72-c9d1aa9f5987', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 9, 9, '“ፍሬውንና የዘራኸውን ዘር ከወይንህ ፍሬ ጋር እንዳትለቅም በወይንህ ቦታ ላይ የተለያየ ዓይነት ተክል አትትከል።'),
  ('6dfb8b19-6182-5e48-a703-a55f2a9075b8', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 10, 10, 'በአህያህና በበሬህ በአንድነት አትረስ።'),
  ('e9b8f31d-164b-57e0-a033-3a5b38d0bc8d', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 11, 11, 'ከተልባ እግርና ከበግ ጠጕር በአንድነት የተሠራ ልብስ አትልበስ።'),
  ('af9791d3-ce4b-5217-ad05-ecb32ff4de0a', '9872d638-433f-592c-aa2e-b4790036b286', '7fa8f63d-7680-5d2a-a1a3-92edb66788fe', 12, 12, '“በምትለብሰው በልብስህ በአራቱ ማዕዘን ዘርፍ አድርግ።'),
  ('8df899ca-ce66-57e3-ab74-f29a8ed0e9a9', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 1, 13, '“ማናቸውም ሰው ሚስት ቢያገባ፥ አብሮአትም ከኖረ በኋላ ቢጠላት፥'),
  ('f3d33b4b-fe53-55c4-addd-c38d1076896e', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 2, 14, 'የነውር ነገርም ቢያመጣባት፥ እኔ ይህችን ሴት ሚስቴ አድርጌ አገባኋት፤ በደረስሁባትም ጊዜ ድንግልናዋን አላገኘሁባትም ብሎ ክፉ ስም ቢያወጣባት፥'),
  ('6ac6b13a-0712-5e75-a625-2e403cf6a218', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 3, 15, 'የብላቴናዪቱ አባትና እናት የልጃቸውን የድንግልናዋን ልብስ ወስደው በበሩ አደባባይ ወደ ተቀመጡ ወደ ከተማ ሽማግሌዎች ያምጡት፤'),
  ('551999be-ad3e-5148-aec4-d899d6d9de95', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 4, 16, 'የብላቴናዪቱም አባት ሽማግሌዎቹን፦ እኔ ለዚህ ሰው ልጄን ዳርሁለት፤ እርሱም ጠላት፤'),
  ('9fdee0c8-d099-5253-a948-d1842fd2d2ed', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 5, 17, 'እነሆም፦ በልጅህ ድንግልና አላገኘሁባትም ብሎ የነውር ነገር አወራባት፤ የልጄም የድንግልናዋ ልብስ ይኸው ይላቸዋል። በከተማም ሽማግሌዎች ፊት ልብሱን ይዘረጋሉ።'),
  ('69eed830-e006-53e7-afea-7d1af6da82b3', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 6, 18, 'የዚያች ከተማ ሽማግሌዎችም ያን ሰው ወስደው ይገሥጹት፤'),
  ('0d0f66b8-fb89-52c7-a86e-3dd16b4fb38c', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 7, 19, 'በእስራኤል ድንግል ላይ ክፉ ስም አምጥቶአልና መቶ የብር ሰቅል ያስከፍሉት፤ ለብላቴናዪቱም አባት ይስጡት፤ እርስዋም ሚስት ትሁነው፤ በዕድሜውም ዘመን ሁሉ ሊፈታት አይገባውም።'),
  ('d47039dc-073b-5c63-ac8b-f21e25e4d99e', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 8, 20, '“ነገሩ ግን እውነት ቢሆን፥ የብላቴናዪቱም ድንግልናዋ ባይገኝ፥'),
  ('a6b0c492-52f3-50c9-a75c-dec467db24f3', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 9, 21, 'ብላቴናዪቱን ወደ አባቷ ቤት ደጅ ያውጡአት፤ በእስራኤልም ዘንድ ስንፍናን አድርጋለችና፥ የአባቷንም ቤት አስነውራለችና የከተማው ሰዎች በድንጋይ ወግረው ይግደሉአት፤ እንዲሁም ክፉውን ነገር ከመካከልህ ታስወግዳለህ።'),
  ('19557923-6414-5450-a1b6-f46efbbb4f6e', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 10, 22, '“ማናቸውም ሰው ከሌላ ሰው ሚስት ጋር ተኝቶ ቢገኝ፥ አመንዝራውና አመንዝራዪቱ ሁለታቸው ይገደሉ፤ እንዲሁም ክፉውን ነገር ከእስራኤል ታስወግዳለህ።'),
  ('ffe0d6d2-d27b-5678-a234-f5ae9bf16419', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 11, 23, '“ለወንድ የታጨች ድንግል ልጅ ብትኖር፥ ሌላ ሰውም በከተማ ውስጥ አግኝቶ ከእርስዋ ጋር ቢተኛ፥ ሁለቱን ወደዚያች ከተማ በር አውጡአቸው፤'),
  ('069e6d64-20ad-5e9a-a3f9-4f3d1bfa4c28', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 12, 24, 'ብላቴናዪቱ በከተማ ውስጥ ሳለች አልጮኸችምና፥ ሰውየውም የባልጀራውን ሚስት አስነውሮአልና በድንጋይ ወግረው ይግደሉአቸው፤ እንዲሁ ክፉውን ነገር ከውስጥህ ታስወግዳለህ።'),
  ('081faed8-97c9-548c-a182-9424cce4cf55', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 13, 25, '“ነገር ግን ሰው የታጨችውን ልጃገረድ በሜዳ ቢያገኛት፥ በግድ አሸንፎም ቢደርስባት፥ ያ የደረሰባት ሰው ብቻውን ይገደል።'),
  ('a147be25-0061-5e2c-a067-37987633db51', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 14, 26, 'በብላቴናዪቱ ላይ ግን ምንም አታድርጉ፤ በብላቴናዪቱ ላይ ለሞት የሚያበቃ ኀጢአት የለባትም፤ ሰው በባልንጀራው ላይ ተነሥቶ እንደሚገድለው ይህ ነገር ደግሞ እንደዚሁ ነውና፤'),
  ('07f023be-67e6-5323-aca5-5ee1486243b2', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 15, 27, 'በሜዳ ባገኛት ጊዜ የታጨችው ልጃገረድ ጮኻለችና፥ የሚታደጋትም አልነበረምና።'),
  ('81d20719-7d4b-5e51-ac51-8e0e87d36dc4', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 16, 28, 'ማናቸውም ሰው ድንግልና ያላትን ያልታጨች ልጃገረድ ቢያገኝ፥ በግድ አሸንፎ ቢደፍራት፥ ቢያገኙትም፥'),
  ('0eba676e-4581-5860-af4f-d2df7e975fc6', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 17, 29, 'ያ የደፈራት ሰው አምሳ የብር ሰቅል ለብላቴናዪቱ አባት ይስጥ፤ አስነውሮአታልና ሚስት ትሁነው፤ በዕድሜውም ዘመን ሁሉ ሊፈታት አይገባውም።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4e600abf-deff-5d91-a889-9928b5254632', '9872d638-433f-592c-aa2e-b4790036b286', '51060bb5-4fb7-5ae6-ab93-acfbc41d7648', 18, 30, '“ማናቸውም ሰው የእንጀራ እናቱን አይውሰድ፤ የአባቱንም ኀፍረት አይግለጥ።'),
  ('99687fdf-f818-51f6-a4a7-e4780715dbfc', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 1, 1, '“ፍሬ ዘሩ የተቀጠቀጠ፥ አባለ ዘሩም የተቈረጠ ወደ እግዚአብሔር ቤት አይግባ።'),
  ('8d97b004-eb0e-5d39-aa6d-cff3258b4218', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 2, 2, 'ዲቃላ ወደ እግዚአብሔር ቤት አይግባ፤'),
  ('5b7fb31d-f3e0-5042-a984-d42fb13d7e7b', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 3, 3, '“አሞናዊ ወይም ሞዓባዊ ወደ እግዚአብሔር ቤት አይግባ፤ እስከ ዐሥር ትውልድ ድረስ ለዘለዓለም ወደ እግዚአብሔር ቤት አይግባ።'),
  ('ed29aeb4-3519-51b7-af86-5abad726c621', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 4, 4, 'ከግብፅ በወጣችሁ ጊዜ እንጀራና ውኃ ይዘው በመንገድ ላይ አልተቀበሉአችሁምና፥ ከመስጴጦምያ የቢዖርን ልጅ በለዓምን ዋጋ ሰጥተው ይረግማችሁ ዘንድ ተዋውለውባችኋልና።'),
  ('94b11d15-67dc-5a9a-a909-670667d63bcf', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 5, 5, 'ነገር ግን አምላክህ እግዚአብሔር በለዓምን ይሰማ ዘንድ አልወደደም፤ አምላክህ እግዚአብሔርም ወድዶሃልና ርግማኑን ወደ በረከት ለወጠልህ።'),
  ('df744399-57f9-591f-a879-79b05066d835', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 6, 6, 'በዘመንህ ሁሉ ለዘለዓለም ሰላም እንደሚገባቸው አታናግራቸው።'),
  ('d44c03c7-fcf8-5cf7-a90f-28721d4c3b09', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 7, 7, '“ኤዶማዊዉ ወንድምህ ነውና አትጸየፈው፤ ግብፃዊዉንም በሀገሩ ስደተኛ ነበርህና አትጸየፈው።'),
  ('75490379-a082-59a8-aa5e-48f046e551f7', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'eb2d7ea6-c858-556c-afcf-4cb04e45ce7d', 8, 8, 'ከእነርሱም በሦስተኛው ትውልድ የሚወለዱ ልጆች ወደ እግዚአብሔር ቤት ይግቡ።'),
  ('d141272d-973d-59ce-a30e-085c2f3513d8', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', '2036f4d2-9918-57d3-a9f6-1df6c17ecd23', 1, 9, '“ጠላቶችህን ልትወጋ በወጣህ ጊዜ ከክፉ ነገር ሁሉ ሰውነትህን ጠብቅ።'),
  ('fe567400-849f-594d-ae06-ec5bfb50e841', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', '2036f4d2-9918-57d3-a9f6-1df6c17ecd23', 2, 10, 'በእናንተ ውስጥ ሌሊት በሚሆነው ርኵሰት የረከሰ ሰው ቢኖር፥ ከሰፈር ወደ ውጭ ይውጣ፤ ወደ ሰፈርም አይግባ።'),
  ('30096ff8-7717-549d-a727-b92acb1e2daa', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', '2036f4d2-9918-57d3-a9f6-1df6c17ecd23', 3, 11, 'በመሸም ጊዜ ሰውነቱን በውኃ ይታጠብ፤ ፀሐይም በገባ ጊዜ ወደ ሰፈር ይመለስ።'),
  ('d231fe0c-4886-5b77-af6e-07c766a6e921', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', '2036f4d2-9918-57d3-a9f6-1df6c17ecd23', 4, 12, 'ወደ ሜዳም ትወጣባት ዘንድ ከሰፈር ውጭ ቦታ ይኑርህ።'),
  ('de3c7597-2212-5a32-ac25-e6ffc029319a', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', '2036f4d2-9918-57d3-a9f6-1df6c17ecd23', 5, 13, 'ከመሣርያህም ጋር መቈፈሪያ ያዝ፤ ሜዳም በተቀመጥህ ጊዜ ትምስበታለህ፤ ዞረህም ከአንተ የወጣውን በአፈር ትከድነዋለህ።'),
  ('89d88193-a5d2-5939-aafb-08b7ce93dac9', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', '2036f4d2-9918-57d3-a9f6-1df6c17ecd23', 6, 14, 'አምላክህ እግዚአብሔር ሊያድንህ፥ ጠላቶችህንም በእጅህ አሳልፎ ሊሰጥህ በሰፈርህ ውስጥ ይሄዳልና ስለዚህ ነውረኛ ነገር እንዳያይብህ፥ ፊቱንም ከአንተ እንዳይመልስ ሰፈርህ የተቀደሰ ይሁን።'),
  ('d005a74b-3780-55d9-a1fa-62b222fad75e', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 1, 15, '“ከጌታዉ ኰብልሎ ወደ አንተ የተጠጋውን ባሪያ ለጌታው አሳልፈህ አትስጥ።'),
  ('dbf584c0-3aee-528d-aa43-4dde119d2245', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 2, 16, 'ከአንተ ጋር ይኑር፤ በመካከልህም በሚወድዳት በአንዲቱ ስፍራ ይቀመጥ፤ አንተም አታስጨንቀው።'),
  ('1b60290f-cc14-56b8-a890-c13cfe3fcc21', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 3, 17, '“ከእስራኤል ሴቶች ልጆች ሴት አመንዝራ አትገኝ፤ ከእስራኤልም ወንዶች ልጆች ወንድ አመንዝራ አይገኝ።'),
  ('7baed66b-a0e7-50e3-a0da-9636537548cd', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 4, 18, 'ስለ ተሳልኸው ስእለት ሁሉ የአመንዝራዪቱን ዋጋና የውሻውን ዋጋ ወደ አምላክህ ወደ እግዚአብሔር ቤት አታቅርብ፤ ሁለቱም በአምላክህ በእግዚአብሔር ዘንድ የሚያጸይፉ ናቸውና።'),
  ('e36c7704-bb67-532a-a5d9-7d216a717b38', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 5, 19, '“ለወንድምህ በወለድ አታበድር፤ የብር ወይም የእህል፥ ወይም የማናቸውንም ነገር ሁሉ ወለድ አትውሰድ።'),
  ('862d5ee2-8da0-5d16-abb0-21abdc740157', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 6, 20, 'ለእንግዳው በወለድ አበድር፤ ነገር ግን አምላክህ እግዚአብሔር ልትወርሳት በምትገባባት ምድር በሥራህ ሁሉ ይባርክህ ዘንድ ለወንድምህ በወለድ አታበድር።'),
  ('c8df8d56-9475-5c41-acab-54ade7c0eec7', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 7, 21, '“ለአምላክህ ለእግዚአብሔር ስእለት በተሳልህ ጊዜ አምላክህ እግዚአብሔር ከአንተ ፈጽሞ ይሻዋልና፥ ኀጢአትም ይሆንብሃልና መክፈሉን አታዘግይ።'),
  ('c03e05c0-ad93-5a54-a608-6ff7c4278e99', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 8, 22, 'ባትሳል ግን ኀጢአት የለብህም።'),
  ('493880d1-172a-543a-af98-680499da9e1e', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 9, 23, 'በአፍህ የተናገርኸውን ለአምላክህ ለእግዚአብሔር በፈቃድህ ተስለሃልና ከከንፈርህ የወጣውን ታደርግ ዘንድ ጠብቅ።'),
  ('935160e5-da06-564f-a72a-9c5bb4432201', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 10, 24, '“ወደ ባልንጀራህ እርሻ በገባህ ጊዜ እሸቱን በእጅህ ቀጥፈህ ብላ፤ ወዳልታጨደው ወደ ባልንጀራህ እህል ግን ማጭድ አታግባ።'),
  ('cba83ef6-f944-5249-a0fc-ec99b2b65e29', '44bc35ef-c0d5-54d5-af3e-eea7d71fd0eb', 'dc296b9f-254a-5000-a0bc-cd86329c2c82', 11, 25, 'ወደ ባልንጀራህ የወይን ቦታ በገባህ ጊዜ እስክትጠግብ ድረስ ከወይኑ ብላ፤ ወደ ዕቃህ ግን ከእርሱ ምንም አታግባ።'),
  ('7c686163-22b3-57c3-a247-4f88770ce1bf', 'f702d4d8-5d50-5a30-a391-313a50b74767', 'b1de8ddb-5e89-5e17-aacc-ce65c5deaf35', 1, 1, '“አንድ ሰው ሴትን ወስዶ ቢያገባ፥ የእፍረት ነገር ስላገኘባት በእርሱ ዘንድ ሞገስ ባታገኝ፥ የፍችዋን ጽሕፈት ጽፎ በእጅዋ ይስጣት፤ ከቤቱም ይስደዳት።'),
  ('4a982ee0-d52d-512d-ae15-040c4fe6ecad', 'f702d4d8-5d50-5a30-a391-313a50b74767', 'b1de8ddb-5e89-5e17-aacc-ce65c5deaf35', 2, 2, 'ከቤቱም ከወጣች በኋላ ሌላ ወንድ ብታገባ፥'),
  ('ae8b7d23-804c-5997-a3f8-0d9a7036c9e5', 'f702d4d8-5d50-5a30-a391-313a50b74767', 'b1de8ddb-5e89-5e17-aacc-ce65c5deaf35', 3, 3, 'ሁለተኛውም ባል ቢጠላት፥ የፍችዋንም ጽሕፈት ጽፎ በእጅዋ ቢሰጣት ፥ ከቤቱም ቢሰድዳት፥ ወይም ሚስት አድርጎ ያገባት ሁለተኛው ባልዋ ቢሞት፥'),
  ('5b080678-b82e-5e31-ac24-ea12c876dfaa', 'f702d4d8-5d50-5a30-a391-313a50b74767', 'b1de8ddb-5e89-5e17-aacc-ce65c5deaf35', 4, 4, 'የሰደዳት የቀድሞ ባልዋ ከረከሰች በኋላ ደግሞ ያገባት ዘንድ አይገባውም፤ ያ በእግዚአብሔር የተጠላ ነውና፤ አምላክህም እግዚአብሔር ርስት አድርጎ የሰጠህን ምድር አታርክስ።'),
  ('683b683b-0b9d-5171-ad27-7bc89873378b', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 1, 5, '“አዲስ ሚስትም ያገባ ሰው ወደ ጦርነት አይሂድ፤ ምንም ነገር አይጫኑበት፤ ነገር ግን አንድ ዓመት በቤቱ በፈቃዱ ይቀመጥ፤ የወሰዳትንም ሚስቱን ደስ ያሰኛት።'),
  ('69333257-89d1-51e5-a31f-5359968e627c', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 2, 6, '“የሰውን ነፍስ እንደ መውሰድ ነውና ወፍጮ ወይም መጅ ስለ መያዣ ማንም አይውሰድ።'),
  ('d9f97ff6-25ed-50fe-ac9b-586f0144b9e6', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 3, 7, '“ማንም ሰው ከእስራኤል ልጆች ከወንድሞቹ ሰውን አፍኖ ሲሰርቅና ሲሸጥ ቢገኝ ያን የሰረቀውን ሰው ይግደሉት፤ እንዲሁም ክፉውን ነገር ከመካከላችሁ አርቁ።'),
  ('1b1b8cde-3152-509d-a4d7-1e0ce6e4fa5a', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 4, 8, '“ስለ ለምጽ ደዌ ሌዋውያን ካህናት ያስተማሩህን ሁሉ ፈጽመህ እንድትጠብቅ እንድታደርግም ተጠንቀቅ፤ እኔ ያዘዝኋቸውን እንዲሁ ታደርግ ዘንድ ጠብቅ።'),
  ('27a2a5b3-59ae-5929-a271-ef8807ff8fd1', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 5, 9, 'አምላክህ እግዚአብሔር ከግብፅ ባወጣችሁ ጊዜ በመንገድ ሳላችሁ በማርያም ላይ ያደረገውን ዐስብ።'),
  ('2f9661bb-16dc-5d7b-ae92-d1faad3ef816', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 6, 10, '“ለባልንጀራህ ባበደርኸው ጊዜ መያዣውን ልትወስድ ወደ ቤቱ አትግባ።'),
  ('c3ed332e-76d5-532d-a8e0-3e09d7de55fe', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 7, 11, 'አንተ ግን በውጭ ቁም፤ ያበደርኸውም ሰው መያዣውን ወደ ውጭ ያውጣልህ።'),
  ('777e4ec6-9b75-58cc-a391-1ddf3c4946e7', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 8, 12, 'ያም ሰው ድሃ ቢሆን መያዣውን በአንተ ዘንድ አታሳድር።'),
  ('40866810-24a9-532b-a4fc-a47bad8a2062', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 9, 13, 'ለብሶት እንዲተኛ እንዲባርክህም ፀሐይ ሳይገባ መያዣውን ፈጽመህ መልስለት፤ በአምላክህም በእግዚአብሔር ፊት ምጽዋት ይሆንልሃል።'),
  ('5e76939c-7185-5731-a628-6b76c6a5123f', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 10, 14, '“ከወንድሞችህ ወይም በሀገርህ ውስጥ ከአሉት መጻተኞች ድሃና ችግረኛ የሆነውን ምንደኛ ደመወዙን አትከልክለው፤'),
  ('e3dbc0ec-beb9-544d-a3fd-6ac604adb136', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 11, 15, 'ድሃ ነውና፥ ተስፋውም እርሱ ነውና ወደ እግዚአብሔር እንዳይጮኽብህ፥ ኀጢአትም እንዳይሆንብህ ደመወዙን ፀሐይ ሳይገባ በቀኑ ስጠው።'),
  ('e4ba2e63-9f6c-5dcf-a1f9-2c670622801b', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 12, 16, '“አባቶች ስለ ልጆቻቸው አይገደሉ፤ ልጆችም ስለ አባቶቻቸው አይገደሉ፤ ነገር ግን ሁሉ እያንዳንዱ በኀጢአቱ ይገደል።'),
  ('416bb5eb-c566-55ad-af52-d7c959378310', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 13, 17, '“የመጻተኛውንና የድሃ-አደጉን፥ የመበለቲቱንም ፍርድ አታጣምምባቸው፤ የመበለቲቱንም ልብስ ለመያዣ አትውሰድባት።'),
  ('71ca5f94-236e-535e-a9c2-25dfea7c2062', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 14, 18, 'አንተም በግብፅ ባሪያ እንደ ነበርህ፥ አምላክህም እግዚአብሔር ከዚያ እንዳዳነህ ዐስብ፤ ስለዚህ ይህን ነገር ታደርግ ዘንድ አዝዤሃለሁ።'),
  ('90c4df0a-4fd3-5dfe-aeb9-c932eac347be', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 15, 19, '“የእርሻህን መከር ባጨድህ ጊዜ ነዶም ረስተህ በእርሻህ ብታስቀር፥ ትወስደው ዘንድ አትመለስ፤ አምላክህ እግዚአብሔር በእጅህ ሥራ ሁሉ እንዲባርክህ፥ ለመጻተኛና ለድሃ-አደግ፥ ለመበለትም ተወው።'),
  ('3bf3d797-5495-505c-afb5-6139680655cb', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 16, 20, 'የወይራህን ፍሬ በለቀምህ ጊዜ ከቅርንጫፎቹ ላይ አጥርተህ ለመልቀም ዳግመኛ አትመለስ፤ ለመጻተኛና ለድሃ-አደግ፥ ለመበለትም ይሁን።'),
  ('30b52153-dc88-5870-ac68-3628cd04f86d', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 17, 21, 'የወይንህን ፍሬ በቈረጥህ ጊዜ ቃርሚያውን አትልቀመው፤ ለመጻተኛና ለድሃ-አደግ፥ ለመበለትም ይሁን።'),
  ('c599c914-eb80-5e32-a932-c2fcdd206113', 'f702d4d8-5d50-5a30-a391-313a50b74767', '4b427c5e-93cd-5faa-af69-01a428106ba8', 18, 22, 'አንተም በግብፅ ሀገር መጻተኛ እንደ ነበርህ ዐስብ፤ ስለዚህ ይህን ነገር ታደርግ ዘንድ አዝዤሃለሁ።'),
  ('74617a6a-4815-5d9f-adef-c609d9bee40c', '166e9f7b-2561-5170-a029-59148058b96f', 'c7f8d3f3-7269-508d-a6e0-b9bc623b46ee', 1, 1, '“በሰዎች መካከል ጠብ ቢሆን፥ ወደ ፍርድም ቢመጡ፥ ቢፋረዱም ለጻድቁ ይፈረድለት፤ በበደለኛውም ይፈረድበት።'),
  ('e7acaf5d-6503-5d34-a924-e61faef1aa68', '166e9f7b-2561-5170-a029-59148058b96f', 'c7f8d3f3-7269-508d-a6e0-b9bc623b46ee', 2, 2, 'በደለኛውም መገረፍ ቢገባው እንዲገረፍ ፈራጁ በፊቱ በምድር ላይ ያጋድመው፤ የግርፋቱም ቍጥር እንደ ኀጢአቱ መጠን ይሁን።'),
  ('dce07e0c-c43f-53c3-a775-1961950e6b80', '166e9f7b-2561-5170-a029-59148058b96f', 'c7f8d3f3-7269-508d-a6e0-b9bc623b46ee', 3, 3, 'ግርፋቱም አርባ ይሁን፤ ከዚህ በላይ ጨምሮ ብዙ ግርፋት ቢገርፈው ወንድምህ በፊትህ ነውረኛ ይሆናልና ከዚህ በላይ አይጨመርበት።'),
  ('6aabe5f1-960f-56c6-a04c-cb2aa0a03df0', '166e9f7b-2561-5170-a029-59148058b96f', 'c7f8d3f3-7269-508d-a6e0-b9bc623b46ee', 4, 4, '“እህልህን በምታበራይ ጊዜ በሬዉን አፉን አትሰረው።'),
  ('92ec4c46-7767-56fe-ac6c-c37becc4487e', '166e9f7b-2561-5170-a029-59148058b96f', '1112c417-8ddc-5d12-a95d-35a00ae8cc46', 1, 5, '“ወንድማማቾች በአንድነት ቢቀመጡ፥ አንዱም ልጅ ሳይኖረው ቢሞት፥ የሞተው ሰው ሚስት ሌላ ሰው ታገባ ዘንድ ወደ ውጭ አትሂድ፤ ነገር ግን የባልዋ ወንድም ወደ እርስዋ ገብቶ እርስዋን ያግባ፤ ከእርስዋም ጋር ይኑር።'),
  ('e3a73dcb-0eb1-557b-a3c5-b94b31faf249', '166e9f7b-2561-5170-a029-59148058b96f', '1112c417-8ddc-5d12-a95d-35a00ae8cc46', 2, 6, 'የምዋቹ ስም ከእስራኤል ዘንድ እንዳይጠፋ ከእርስዋ የሚወለደው ልጅ በሞተው በወንድሙ ስም ይጠራ።'),
  ('71e42514-1bae-5af1-ab6c-9af458e6e497', '166e9f7b-2561-5170-a029-59148058b96f', '1112c417-8ddc-5d12-a95d-35a00ae8cc46', 3, 7, 'ያም ሰው የወንድሙን ሚስት ማግባት ባይወድድ፥ ዋርሳዪቱ በበሩ አደባባይ ወደሚቀመጡ ሽማግሌዎች ሄዳ፦ ‘ዋርሳዬ በእስራኤል ዘንድ ለወንድሙ ስም ማቆም እንቢ አለ፤ ከእኔም ጋር ሊኖር አልወደደም’ ትበላቸው።'),
  ('1068222c-975f-5141-abf9-0d7394e71ce2', '166e9f7b-2561-5170-a029-59148058b96f', '1112c417-8ddc-5d12-a95d-35a00ae8cc46', 4, 8, 'የከተማውም ሽማግሌዎች ጠርተው ይጠይቁት፤ እርሱም በዚያ ቆሞ፦ ‘አገባት ዘንድ አልወድድም’ ቢል፥'),
  ('584a76f7-fc2b-56b1-a58e-fde1850ddd56', '166e9f7b-2561-5170-a029-59148058b96f', '1112c417-8ddc-5d12-a95d-35a00ae8cc46', 5, 9, 'ዋርሳዪቱ በሽማግሌዎቹ ፊት ወደ እርሱ ቀርባ፦ ‘የወንድሙን ቤት በማይሠራ ሰው ላይ እንዲህ ይደረግበታል’ ስትል የአንድ እግሩን ጫማ ታውጣ፤ በፊቱም እንትፍ ትበልበት።'),
  ('16a7eefb-fa3d-5839-ab54-8809ff4f2ad3', '166e9f7b-2561-5170-a029-59148058b96f', '1112c417-8ddc-5d12-a95d-35a00ae8cc46', 6, 10, 'በእስራኤልም ዘንድ ስሙ ‘የጫማ ፈቱ ቤት’ ተብሎ ይጠራ።'),
  ('e8f78506-2134-5c79-accb-3c942816dd43', '166e9f7b-2561-5170-a029-59148058b96f', 'aa813be3-2703-542f-ac27-a84e471ad446', 1, 11, '“ሁለት ሰዎች እርስ በርሳቸው ቢጣሉ፥ የአንደኛውም ሰው ሚስት ባልዋን ከሚመታው ሰው እጅ ታድነው ዘንድ ብትቀርብ፥ እጅዋንም ዘርግታ ሁለቱን የብልቱን ፍሬዎች ብትይዝ፥'),
  ('bd47a0b5-9950-52c7-a4f4-a80557e3bb40', '166e9f7b-2561-5170-a029-59148058b96f', 'aa813be3-2703-542f-ac27-a84e471ad446', 2, 12, 'እጅዋን ቍረጥ፤ ዐይንህም አትራራላት።'),
  ('06621300-cd98-5992-a5b9-d852507577f9', '166e9f7b-2561-5170-a029-59148058b96f', 'aa813be3-2703-542f-ac27-a84e471ad446', 3, 13, '“በከረጢትህ ውስጥ ታላቅና ታናሽ ሚዛን አይኑርልህ።'),
  ('5ab2b0d4-e64b-57d6-a9b4-111bf8d2d347', '166e9f7b-2561-5170-a029-59148058b96f', 'aa813be3-2703-542f-ac27-a84e471ad446', 4, 14, 'በቤትህ ውስጥ ታላቅና ታናሽ መስፈሪያ አይኑርልህ።'),
  ('3a627371-af5b-5144-ac11-aca5d62be742', '166e9f7b-2561-5170-a029-59148058b96f', 'aa813be3-2703-542f-ac27-a84e471ad446', 5, 15, 'አምላክህ እግዚአብሔር ርስት አድርጎ በሚሰጥህ ምድር ላይ ዕድሜህ ይረዝም ዘንድ እውነተኛና ፍጹም ሚዛን ይሁንልህ፤ እውነተኛና ፍጹም መስፈሪያም ይሁንልህ።'),
  ('af2e5a64-6862-5af8-a3b7-18a3f272897c', '166e9f7b-2561-5170-a029-59148058b96f', 'aa813be3-2703-542f-ac27-a84e471ad446', 6, 16, 'ይህን የሚያደርግ ሁሉ፥ ክፋትንም የሚያደርግ ሁሉ በአምላክህ በእግዚአብሔር ዘንድ የተጠላ ነውና።'),
  ('99d916ff-0423-5163-a459-2b77135420bf', '166e9f7b-2561-5170-a029-59148058b96f', '2b487836-3060-50b6-aba7-26f0e9de2579', 1, 17, '“ከግብፅ በወጣህ ጊዜ ዐማሌቅ በመንገድ ላይ ያደረገብህን ዐስብ፤'),
  ('f33b21df-dda4-5d42-aef5-92b5bacf4b5f', '166e9f7b-2561-5170-a029-59148058b96f', '2b487836-3060-50b6-aba7-26f0e9de2579', 2, 18, 'በመንገድ ላይ እንደ ተቃወመህ፥ አንተም ተርበህና ደክመህ ሳለህ ጓዝህንና ከአንተ በኋላ ደክመው የነበሩትን ሁሉ እንደ መታ፤ እግዚአብሔርንም አልፈራውም።'),
  ('d2a7c8a0-1fab-5e67-a136-8f6b86367601', '166e9f7b-2561-5170-a029-59148058b96f', '2b487836-3060-50b6-aba7-26f0e9de2579', 3, 19, 'ስለዚህ አምላክህ እግዚአብሔር ትወርሳት ዘንድ በሚሰጥህ ምድር ከሚከብቡህ ጠላቶችህ ሁሉ አምላክህ እግዚአብሔር ባሳረፈህ ጊዜ፥ የዐማሌቅን ዝክረ ስሙን ከሰማይ በታች አጥፋው፤ ይህንም አትርሳ።'),
  ('100f42c7-7efe-54eb-a402-0711dab9fd88', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 1, 1, '“አምላክህ እግዚአብሔር ርስት አድርጎ ወደሚሰጥህ ምድር በገባህ ጊዜ፥ በወረስሃትም፥ በኖርህባትም ጊዜ፥'),
  ('80a97f5b-f282-560b-a82b-103721122de4', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 2, 2, 'አምላክህ እግዚአብሔር ከሚሰጥህ ምድር ከምትሰበስበው ፍሬ ሁሉ ቀዳምያት ውሰድ፤ በዕንቅብም አድርገው፤ አምላክህ እግዚአብሔርም ስሙ ይጠራበት ዘንድ ወደ መረጠው ስፍራ ይዘህ ሂድ።'),
  ('6f41c830-70a0-5121-a08b-42c3d7c1bdc3', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 3, 3, 'በዚያም ወራት ወደሚሆነው ካህን መጥተህ፦ ‘እግዚአብሔር ይሰጠን ዘንድ ለአባቶቻችን ወደ ማለላቸው ምድር እንደ ገባሁ ዛሬ በአምላኬ በእግዚአብሔር ፊት አስታውቃለሁ’ በለው።'),
  ('670ffb58-1d13-5171-ad17-f5512552091d', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 4, 4, 'ካህኑም ዕንቅቡን ከእጅህ ወስዶ በአምላክህ በእግዚአብሔር መሠዊያ ፊት ያኑረው፤'),
  ('226b96b9-6fac-57c5-a687-f03c4de8140b', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 5, 5, 'በአምላክህም በእግዚአብሔር ፊት እንዲህ ብለህ ተናገር፦ አባቴ ከሶርያ ወጥቶ ወደ ግብፅ ወረደ፤ በዚያም በቍጥር ጥቂት ሆኖ ኖረ፤ በዚያም ታላቅና የበረታ፥ ብዙም ሕዝብ ሆነ።'),
  ('9730257e-544d-59ac-aae0-0f57f3f6f01e', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 6, 6, 'ግብፃውያንም ክፉ ነገር አደረጉብን፤ አስጨነቁንም፤ በላያችንም ከባድ ሥራን ጫኑብን፤'),
  ('cf9c888c-77c0-5c6d-aebc-995dce1bc7c3', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 7, 7, 'ወደ አባቶቻችንም አምላክ ወደ እግዚአብሔር ጮኽን፤ እግዚአብሔርም ቃላችንን ሰማ፤ ጭንቀታችንንም፥ ድካማችንንም፥ ግፋችንንም አየ፤'),
  ('1a9cea7d-22f0-57b7-a9f2-650d38b2d3f0', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 8, 8, 'እግዚአብሔርም በጸናች እጅና በተዘረጋ ክንድ፥ በታላቅም ግርማ፥ በታላቅ ተአምራትም፥ በድንቅም ከግብፅ አወጣን፤'),
  ('2985d601-47b1-5d45-a0dc-c0eca34d1180', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 9, 9, 'ወደዚህም ስፍራ አገባን፤ ወተትና ማር የምታፈስሰውንም ይህችን ምድር ሰጠን።'),
  ('3c09fa0b-cc82-5cae-a473-033ca3b05b1e', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 10, 10, 'አሁንም እነሆ፥ አቤቱ፥ አንተ የሰጠኸኝን ማርና ወተት የምታፈስሰውን የምድሪቱን ፍሬ ቀዳምያት አቅርቤአለሁ።'),
  ('464885d4-101d-5d23-a94f-5e6eca158333', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 11, 11, 'አንተም በአምላክህ በእግዚአብሔር ፊት አኑረው፥ በአምላክህም በእግዚአብሔር ፊት ስገድ። አንተም፥ በመካከልህም ያለ ሌዋዊና መጻተኛ አምላክህ እግዚአብሔር ለአንተና ለቤትህ በሰጠው ቸርነት ሁሉ ደስ ይበላችሁ።'),
  ('890b6e21-fa25-525a-a236-6e80c6ceed85', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 12, 12, '“ዐሥራት በምታወጣበት በሦስተኛው ዓመት የምድርህን ፍሬ ሁሉ ዐሥራት አውጥተህ በፈጸምህ ጊዜ፥ ሁለተኛ ዐሥራት አውጥተህ በከተሞችህ ውስጥ ይበሉ ዘንድ፥ ይጠግቡም ዘንድ ለሌዋዊው፥ ለመጻተኛውም፥ ለድሃ-አደጉም፥ ለመበለቲቱም ስጣቸው።'),
  ('27eaac8e-e07d-5538-a81b-2ac996709f84', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 13, 13, 'በአምላክህ በእግዚአብሔር ፊት እንዲህ በል፦ የተቀደሰውን ነገር ከቤቴ ለይች ለሌዋዊው፥ ለመጻተኛውም፥ ለድሀ-አደጉም፥ ለመበለቲቱም እንዳዘዝኸኝ ትእዛዝ ሁሉ ሰጥቼአለሁ፤ ትእዛዝህን ምንም አላፈረስሁም፤ አልረሳሁምም፤'),
  ('2174182a-521b-5edd-a248-7cd0ce0806e9', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 14, 14, 'በኀዘኔም ጊዜ እኔ ከእርሱ አልበላሁም፤ ለርኩስም ነገር ከእርሱ የኀጢአት መሥዋዕት አልሠዋሁም፤ ከእርሱም አንዳች ለሞተ ሰው አልሰጠሁም፤ የአምላኬንም የእግዚአብሔርን ቃል ሰምቼአለሁ፤ ያዘዝኸኝንም ሁሉ አድርጌአለሁ።'),
  ('ba5dd00b-383d-519f-a912-665b25c0afd5', '920bc155-be14-59d3-aad5-85f6d1c3b008', '5612ba63-b0c1-57a6-abc4-aab4ea193dfc', 15, 15, 'ከቅዱስ ማደርያህ ከሰማይ ጐብኝ፤ ሕዝብህንም እስራኤልን፥ ወተትና ማር የምታፈስሰውን ምድር ትሰጠን ዘንድ ለአባቶቻችን እንደ ማልህላቸው የሰጠሃቸውንም ምድር ባርክ።'),
  ('1ce9c196-cc8a-58e9-a542-a8fc7ffe9db8', '920bc155-be14-59d3-aad5-85f6d1c3b008', '9d364259-708d-59d0-a4d1-fee3cabd1f0a', 1, 16, '“አምላክህ እግዚአብሔር ይህን ሥርዐትና ፍርድ ታደርግ ዘንድ ዛሬ አዝዞሃል፤ አንተም በፍጹም ልብህና በፍጹም ነፍስህ ጠብቀው፤ አድርገውም።'),
  ('a9580345-29f9-5b8c-a8f0-304ea9386ed4', '920bc155-be14-59d3-aad5-85f6d1c3b008', '9d364259-708d-59d0-a4d1-fee3cabd1f0a', 2, 17, 'አንተም በመንገዱ ትሄድ ዘንድ፥ ሥርዐቱንና ትእዛዙን፥ ፍርዱንም ትጠብቅ ዘንድ፥ ቃሉንም ትሰማ ዘንድ እግዚአብሔር እርሱ አምላክህ እንዲሆን ዛሬ መርጠሃል።'),
  ('d8ab66f3-fc38-57df-a677-01906c357fd2', '920bc155-be14-59d3-aad5-85f6d1c3b008', '9d364259-708d-59d0-a4d1-fee3cabd1f0a', 3, 18, 'እግዚአብሔር እንደ ተናገረ ርስቱና ሕዝቡ ትሆን ዘንድ፥ ትእዛዙንም ሁሉ ትጠብቅ ዘንድ፥ ዛሬ መርጦሃልና፤'),
  ('5cd83211-c64b-50e0-a6e9-132750158c90', '920bc155-be14-59d3-aad5-85f6d1c3b008', '9d364259-708d-59d0-a4d1-fee3cabd1f0a', 4, 19, 'ከአሕዛብ ሁሉ በላይ ትሆን ዘንድ፥ እርሱም እንደ ተናገረ ለአምላክህ ለእግዚአብሔር የተቀደሰ ሕዝብ ትሆን ዘንድ ታላቅ ስምን፥ ምስጋናና ክብርንም አደረገልህ።”'),
  ('d0a07b01-d67f-5958-a0b2-b2da3a55f6bb', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 1, 1, 'ሙሴም የእስራኤልን ሽማግሌዎች እንዲህ ብሎ አዘዛቸው፥ “ዛሬ ያዘዝኋችሁን ትእዛዝ ታደርጉ ዘንድ ዕወቁ፤'),
  ('61b09f69-aa41-50aa-a3ab-163b878f81aa', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 2, 2, 'አምላካችሁ እግዚአብሔር ወደሚሰጣችሁ ምድር ዮርዳኖስን በተሻገራችሁ ጊዜ ታላላቅ ድንጋዮችን ለእናንተ አቁሙ፤ በኖራም ምረጓቸው።'),
  ('50ed5a72-ea8b-513a-a774-e874b414a42a', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 3, 3, 'የአባቶቻችሁ አምላክ እግዚአብሔር እንደ ተናገራችሁ፥ ወተትና ማር ወደምታፈስስ ምድር፥ አምላካችሁ እግዚአብሔር ወደሚሰጣችሁ ምድር ትገቡ ዘንድ በተሻገራችሁ ጊዜ፥ የዚህን ሕግ ቃሎች ሁሉ በድንጋዮች ላይ ጻፉ።'),
  ('a9639a80-c9dc-51a0-a058-4c42935a365e', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 4, 4, 'ዮርዳኖስንም በተሻገራችሁ ጊዜ፥ ዛሬ እንዳዘዝኋችሁ፥ እነዚህን ድንጋዮች በጌባል ተራራ አቁሙ፤ በኖራም ምረጓቸው።'),
  ('1c111945-618e-51f3-a6ba-323fe2064c9d', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 5, 5, 'በዚያም ለአምላክህ ለእግዚአብሔር መሠዊያ ሥራ፤ መሠዊያውም ብረት ካልነካው ድንጋይ ይሁን።'),
  ('4a0609c9-6706-58e3-a7f4-927da9d8a746', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 6, 6, 'ካልተጠረበም ድንጋይ ለአምላክህ ለእግዚአብሔር መሠዊያ ሥራ፤ ለአምላክህም ለእግዚአብሔር የሚቃጠለውን መሥዋዕትህን አቅርብበት፤'),
  ('b2072560-d7f6-55b7-afc3-d15549439e7b', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 7, 7, 'ለአምላክህ ለእግዚአብሔርም የደኅንነት መሥዋዕት ሠዋበት፤ በዚያም ብላ፤ ጥገብም፤ በአምላክህም በእግዚአብሔር ፊት ደስ ይበልህ።'),
  ('45298b74-4b23-529a-a82c-36991d08cf52', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 8, 8, 'የዚህንም ሕግ ቃሎች ሁሉ የተገለጠ አድርገህ በድንጋዮቹ ላይ ጻፍ።”'),
  ('423f1050-38c2-574f-af91-db99bb09d2ae', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 9, 9, 'ሙሴና ሌዋውያን ካህናት ለእስራኤል ሁሉ እንዲህ ብለው ተናገሩ፥ “እስራኤል ሆይ፥ ዝም ብለህ አድምጥ፤ ዛሬ የአምላክህ የእግዚአብሔር ሕዝብ ሆነሃል።'),
  ('cff8e946-8110-5d78-a2c6-3524f5e23584', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '9f670ef1-b30a-5346-a01b-c94eee16a9d6', 10, 10, 'የአምላክህንም የእግዚአብሔርን ቃል ስማ፤ ዛሬም የማዝዝህን ትእዛዙንና ሥርዐቱን አድርግ።”'),
  ('85a54942-d0f2-596b-a7c7-7da503cdce83', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 1, 11, 'ሙሴም በዚያ ቀን እንዲህ ብሎ ሕዝቡን አዘዘ፦'),
  ('6fc88afc-c453-5370-a103-762e7c5d2580', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 2, 12, '“ዮርዳኖስን በተሻገራችሁ ጊዜ ሕዝቡን ይባርኩ ዘንድ በገሪዛን ተራራ ላይ የሚቆሙ እነዚህ ናቸው፤ ስምዖንና ሌዊ፥ ይሁዳና ይሳኮር፥ ዮሴፍና ብንያም።'),
  ('3b5a94a5-045e-56df-a253-e2364b553866', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 3, 13, 'ይረግሙም ዘንድ በጌባል ተራራ ላይ የሚቆሙ እነዚህ ናቸው፤ ሮቤልና ጋድ፥ አሴርና ዛብሎን፥ ዳንና ንፍታሌም።'),
  ('78f7f332-6104-5cb5-ad88-260d8e927b23', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 4, 14, 'ሌዋውያንም ከፍ ባለች ድምፅ ለእስራኤል ሰዎች ሁሉ እንዲህ ብለው ይናገሩ።'),
  ('5e054833-701d-5e62-a0be-ccd3e461f069', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 5, 15, '“በእግዚአብሔር ዘንድ የተጠላ የሠራተኛ እጅ ሥራን፥ የተቀረፀ ወይም ቀልጦ የተሠራ ምስልን የሚያደርግ፥ በስውርም የሚያቆመው ሰው ርጉም ይሁን፤ ሕዝቡም ሁሉ መልሰው አሜን ይላሉ።'),
  ('be6ea143-9644-59eb-ade7-16ebdb14e338', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 6, 16, '“አባቱን ወይም እናቱን የሚያቃልል ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('88f602ce-9bd8-5868-afa7-e466c0ea2e5a', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 7, 17, '“የባልንጀራውን የድንበር ምልክት የሚገፋ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('3f249ddd-3be4-518e-a6e6-430b38b61ef0', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 8, 18, '“ዕውሩን ከመንገድ ፈቀቅ የሚያደርግ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('b9adfe48-0d65-5412-aa8f-9f26ea50ef56', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 9, 19, '“በመጻተኛ፥ በድሃ-አደጉም፥ በመበለቲቱም ላይ ፍርድን የሚያጣምም ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('8cf8edd2-03c5-5795-aff7-ef41f8509295', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 10, 20, '“ከእንጀራ እናቱ ጋር የሚተኛ የአባቱን ኀፍረት ገልጦአልና ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('dbf0cea2-52c4-585d-a322-8a2b49619a0d', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 11, 21, '“ከእንስሳ ሁሉ የሚደርስ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('a31f90d0-fc8e-5d71-a2cc-f6ca003b2fe3', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 12, 22, '“ከአባቱ ወይም ከእናቱ ልጅ ከእኅቱ ጋር የሚተኛ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('2bbc5b8f-56dd-566c-a502-8f0281cc19a0', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 13, 23, '“ከአማቱ ጋር የሚተኛ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ። ከዋርሳው ጋር የሚተኛ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይሁን ይላሉ።'),
  ('7a04f4a3-7f5b-5e5f-ac16-8615ceb02383', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 14, 24, '“ባልንጀራውን በተንኰል የሚመታ ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('e815dc93-c537-5e54-a581-71514a705865', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 15, 25, '“የንጹሑን ሰው ነፍስ ለመግደል ጉቦ የሚቀበል ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('15e0753f-deea-560a-a042-3dba945e12ad', '83c6f83a-4a24-5eec-a1f4-c3a99decb302', '8b98e325-3a9b-51d8-a246-ec69a6e5df7c', 16, 26, '“የዚህን ሕግ ቃሎች ያደርግ ዘንድ የማያጸና ርጉም ይሁን፤ ሕዝቡም ሁሉ አሜን ይላሉ።'),
  ('19942862-165a-5f63-a51f-2991fa23b4d3', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 1, 1, '“እንዲህም ይሆናል፤ የአምላክህን የእግዚአብሔርን ቃል ፈጽመህ ብትሰማ፥ ዛሬም ያዘዝሁህን ትእዛዙን ሁሉ ብታደርግ፥ ብትጠብቅም፥ አምላክህ እግዚአብሔር ከምድር አሕዛብ ሁሉ በላይ ከፍ ከፍ ያደርግሃል።'),
  ('3fa6d097-96fa-552a-a5a1-20c2b455f6dd', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 2, 2, 'የአምላክህንም የእግዚአብሔርን ቃል ብትሰማ እነዚህ በረከቶች ሁሉ ይመጡልሃል፤ ያገኙህማል።'),
  ('9aa44c44-17b6-521c-a5c0-59de679e18fc', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 3, 3, 'አንተ በከተማ ቡሩክ ትሆናለህ፤ በእርሻም ቡሩክ ትሆናለህ።'),
  ('1cbd4ddb-3b54-51d1-a457-4984699b53cf', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 4, 4, 'የሆድህ ፍሬ፥ የምድርህም ፍሬ፥ የከብትህም ፍሬ፥ የላምህም መንጋ፥ የበግህም መንጋ ቡሩክ ይሆናል።'),
  ('e43aee00-0501-5bca-a973-2180a8f8b7ad', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 5, 5, 'መዛግብትህና የቀረውም ሁሉ ቡሩክ ይሆናል።'),
  ('ce4ee8f3-4748-56d8-a0e3-3d7d1bece2b3', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 6, 6, 'አንተም በመግባትህ ቡሩክ ትሆናለህ፥ በመውጣትህም ቡሩክ ትሆናለህ።'),
  ('5030d0b9-c695-5a80-a53d-97fb0ca0a315', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 7, 7, '“እግዚአብሔርም ከእግርህ በታች ይወድቁ ዘንድ የሚቃወሙህን ጠላቶችህን በእጅህ ይጥላቸዋል፤ በአንድ መንገድ ይመጡብሃል፤ በሰባትም መንገድ ከፊትህ ይሸሻሉ።'),
  ('f70b2ebf-3a2b-5fa8-a05c-f233f6807b2d', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 8, 8, 'እግዚአብሔር በረከቱን በአንተ ላይ፥ በጎተራህ፥ በእህልህም ሥራ ሁሉ እንዲወርድ ይልካል፤ አምላክህ እግዚአብሔር በሚሰጥህም ምድር ይባርክሃል።'),
  ('d569d534-f9a8-54e7-acf4-7227124b6422', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 9, 9, 'የአምላክህን የእግዚአብሔርን ትእዛዝ ብትሰማ፥ በመንገዱም ብትሄድ፥ እግዚአብሔር ለአባቶችህ እንደ ማለ ለእርሱ የተቀደሰ ሕዝብ አድርጎ ያቆምሃል።'),
  ('eb047c61-38c4-5252-a87d-8ec7b7c40060', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 10, 10, 'የምድር አሕዛብም ሁሉ የአምላክህ የእግዚአብሔር ስም በአንተ ላይ እንደ ተጠራ አይተው ይፈሩሃል።'),
  ('db23e7f7-66c4-55b6-add0-42f5c1121a39', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 11, 11, 'አምላክህ እግዚአብሔርም እርስዋን ይሰጥህ ዘንድ ለአባቶችህ በማለላቸው በምድርህ ላይ፥ በሆድህ ፍሬ፥ በእርሻህም ፍሬ፥ ከብቶችህን በማብዛት እግዚአብሔር በጎነቱን ያበዛልሃል።'),
  ('4f5c3873-b8ae-5b5d-a6a0-5cef5a5a3f7b', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 12, 12, 'እግዚአብሔርም ለምድርህ በወራቱ ዝናብን ይሰጥ ዘንድ፥ የእጅህንም ሥራ ሁሉ ይባርክ ዘንድ መልካሙን መዝገብ ሰማዩን ይከፍትልሃል፤ ለብዙ አሕዛብም ታበድራለህ፥ አንተ ግን ከማንም አትበደርም፤ ብዙ አሕዛብን ትገዛለህ፥ አንተን ግን እነርሱ አይገዙህም።'),
  ('2579e492-bc27-51e7-a22b-b4513440bcbd', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 13, 13, 'ዛሬም ያዘዝሁህን የአምላክህን የእግዚአብሔርን ትእዛዝ ሰምተህ ብትጠብቃት፥ ብታደርጋትም፥ እግዚአብሔር ራስ ያደርግሃል እንጂ ጅራት አያደርግህም፤ ሁልጊዜም በላይ እንጂ በታች አትሆንም።'),
  ('f2d2e95d-9adb-5290-aa41-59639971db94', '416a0c0c-0823-5518-a73f-f2751004c34f', '669cf8a3-8310-5532-aa59-98bebfb1ee23', 14, 14, 'ዛሬም ካዘዝሁህ ከእነዚህ ቃሎች ወደ ቀኝ፥ ወደ ግራም ፈቀቅ ባትል፥ ታመልካቸውም ዘንድ ሌሎችን አማልክት ባትከተል።'),
  ('1744bd15-618b-50ef-a080-fe7336a3fd25', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 1, 15, '“ነገር ግን የአምላክህን የእግዚአብሔርን ቃል ባትሰማ፥ ዛሬም ያዘዝሁህን ሥርዐቱንና ትእዛዙን ሁሉ ባትጠብቅ፥ ባታደርግም፥ እነዚህ መርገሞች ሁሉ ይመጡብሃል፤ ያገኙህማል።'),
  ('a3a6c516-2d68-5949-abfd-13d7321c233d', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 2, 16, 'በከተማ ርጉም ትሆናለህ፤ በእርሻም ርጉም ትሆናለህ።'),
  ('c26a1668-0b9f-537e-a45f-523abe74a477', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 3, 17, 'መዛግብትህና የቀረውም ርጉማን ይሆናሉ።'),
  ('90040ce4-bec2-5b90-aa4c-33570861a2e6', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 4, 18, 'የሆድህ ፍሬ፥ የምድርህም ፍሬ፥ የላምህም መንጋ፥ የበግህም መንጋ ርጉማን ይሆናሉ።'),
  ('ef8a359e-9cb7-52e1-a808-0a41843e0454', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 5, 19, 'አንተ በመግባትህና በመውጣትህም ርጉም ትሆናለህ።'),
  ('04eadcfa-f439-59e0-a128-877a558f4d6d', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 6, 20, 'እኔን ስለተውኸኝ፥ ስለ ሥራህ ክፋት፥ እስክትጠፋ፥ ፈጥነህም እስክታልቅ ድረስ በምትሠራው ሥራ ሁሉ እግዚአብሔር ችግርን፥ ረኃብን፦ ቸነፈርንም ይልክብሃል።'),
  ('0a24acfe-24e1-534f-acbb-2e8ebc2ee75d', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 7, 21, 'እግዚአብሔር ትወርሳት ዘንድ ከምትገባባት ምድር እስኪያጠፋህ ድረስ ሞትን ያመጣብሃል።'),
  ('bfb42102-a7a2-5550-acde-73441680be97', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 8, 22, 'እግዚአብሔር በክሳት፥ በንዳድም፥ በጥብሳትም፥ በትኵሳትም፥ በድርቅም፥ በዋግም፥ በአረማሞም ይመታሃል፤ እስክትጠፋም ድረስ ያሳድዱሃል።'),
  ('98cf3bce-5824-5330-aae7-cd4067126ddb', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 9, 23, 'በራስህም ላይ ሰማይ ናስ ይሆንብሃል፤ ከእግርህም በታች ምድሪቱ ብረት ትሆንብሃለች።'),
  ('78bdc59c-0cca-5a35-ab61-2e0ff21e1831', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 10, 24, 'እግዚአብሔር የምድርህን ዝናብ ጭጋግ ያደርጋል፤ እስክትጠፋም ድረስ ከሰማይ አፈር ይወርድብሃል።'),
  ('8e0e1961-664e-50f3-a385-f6012f1b8577', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 11, 25, '“እግዚአብሔር ከጠላቶችህ ፊት የተመታህ ያደርግሃል፤ በአንድ መንገድ ትወጣባቸዋለህ፤ በሰባት መንገድም ከእነርሱ ትሸሻለህ፤ በምድርም መንግሥታት ሁሉ የተበተንህ ትሆናለህ።'),
  ('e8d30b7a-8940-5c51-a0a2-f6ab127454eb', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 12, 26, 'ሬሳህ ለሰማይ ወፎች ሁሉ፥ ለምድርም አራዊት መብል ይሆናል፤ የሚቀብርህም አታገኝም።'),
  ('ecddad36-dff8-501f-a0f5-ad16ff23d882', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 13, 27, 'እግዚአብሔር ፈውስ በሌለው በግብፅ ቍስል፥ በእባጭም፥ በቋቁቻም፥ በችፌም ይመታሃል።'),
  ('8a8038c6-a5f2-50bb-ab79-faeefefa82ab', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 14, 28, 'እግዚአብሔር በዕብደት፥ በዕውርነት፥ በልብ ድንጋጤም ይመታሃል።'),
  ('622011ff-c8c0-5e52-a6ed-0aac4c3c0d37', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 15, 29, 'ዕውር በጨለማ እንደሚዳብስ በቀትር ጊዜ ትዳብሳለህ፤ መንገድህም የቀና አይሆንም፤ በዘመንህም ሁሉ የተገፋህ፥ የተዘረፍህም ትሆናለህ፤ የሚረዳህም የለም።'),
  ('653caab0-bcdf-5783-ac57-49b822069577', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 16, 30, 'ሚስት ታገባለህ፤ ሌላም ሰው ይነጥቅሃል፤ ቤት ትሠራለህ፤ በእርሱም አትቀመጥበትም፤ ወይን ትተክላለህ፤ ከእርሱም አትለቅምም።'),
  ('a03b61de-c4ac-5ffb-aa9b-3ea36783d361', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 17, 31, 'በሬህ በፊትህ ይታረዳል፤ ከእርሱም አትበላም። አህያህ ከእጅህ በግድ ይወሰዳል፤ ወደ አንተም አይመለስም፤ በጎችህ ለጠላቶችህ ይሰጣሉ፤ የሚረዳህም አታገኝም።'),
  ('75db91a3-4253-56d1-a5d5-101aff70b59c', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 18, 32, 'ወንዶችና ሴቶች ልጆችህ ለሌላ ሕዝብ ይሰጣሉ፤ ራሳቸውንም ሲመቱአቸው በዐይኖችህ ታያለህ፤ ልታደርገውም የምትችለው የለም።'),
  ('a2a0f7ba-3b01-5064-a1a9-5a01b76cf931', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 19, 33, 'የምድርህን ፍሬ፥ ድካምህንም ሁሉ የማታውቀው ሕዝብ ይበላዋል፤ አንተም ሁልጊዜ የተጨነቅህ፥ የተገፋህም ትሆናለህ።'),
  ('a587169d-c72a-5f70-a150-c883e398bc5f', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 20, 34, 'ዐይኖችህም ከሚያዩት የተነሣ ዕብድ ትሆናለህ።'),
  ('892bbead-581e-5e2c-affa-b3a322ebb2c2', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 21, 35, 'እግዚአብሔር ልትድን በማትችልበት በክፉ ቍስል ጕልበትህንና ጭንህን ከእግርህ ጫማ እስከ አናትህ ድረስ ይመታሃል።'),
  ('3dd8d3c6-f7bb-5f3f-a558-33ca5ec2fb1a', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 22, 36, '“እግዚአብሔርም አንተን፥ በአንተም ላይ የምትሾማቸውን አለቆችህን አንተና አባቶችህ ወዳላወቃችኋቸው ሕዝብ ይወስድሃል፤ በዚያም ሌሎችን የእንጨትና የድንጋይ አማልክትን ታመልካለህ።'),
  ('b64f009f-8d52-5bf9-a23e-884ad5852f67', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 23, 37, 'እግዚአብሔርም ወደ እነርሱ በሚወስድህ አሕዛብ መካከል ሁሉ የደነገጥህ፥ ለምሳሌና ለተረትም ትሆናለህ።'),
  ('401d28c0-4041-5816-ae3f-9acb3658b2cf', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 24, 38, 'ብዙ ዘርም ወደ እርሻ ታወጣለህ፤ አንበጣም ይበላዋልና ጥቂት ትሰበስባለህ።'),
  ('5e9d6727-f216-5d3f-ae93-8e44fa8de324', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 25, 39, 'ወይን ትተክላለህ፤ ታበጀውማለህ፤ ከወይኑም አትጠጣም፤ ክፉ ትልም ይበላዋልና በእርሱ ደስ አይልህም።'),
  ('92849df5-41c8-54f5-a733-b7da2d9f0323', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 26, 40, 'የወይራ ዛፍ በሀገርህ ሁሉ ይሆንልሃል፤ ፍሬውም ይረግፋልና ዘይቱን አትቀባም።'),
  ('3a9afcfe-6144-5802-a1ae-5701cf74ea9c', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 27, 41, 'ወንዶችና ሴቶች ልጆችን ትወልዳለህ፤ ማርከው ይወስዷቸዋልና አይቀሩልህም።'),
  ('f8e94072-6478-5729-aa35-b3a9bc2fd843', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 28, 42, 'ዛፍህን ሁሉ፤ የምድርህንም ፍሬ ሁሉ ኩብኩባ ያጠፋዋል።'),
  ('8fe375c6-4a19-5f8e-a0e6-a710645b8404', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 29, 43, 'በአንተ መካከል ያለ መጻተኛ በአንተ ላይ ከፍ ከፍ ይላል፤ አንተ ግን ዝቅ ዝቅ ትላለህ።'),
  ('57af4906-cabe-5d85-ae86-5d58eaf2f403', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 30, 44, 'እርሱ ያበድርሃል፤ አንተ ግን አታበድረውም፤ እርሱ ራስ ይሆናል፤ አንተም ጅራት ትሆናለህ።'),
  ('2fa06311-116a-5f9e-ac42-9538310d1715', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 31, 45, 'የአምላክህንም የእግዚአብሔርን ቃል ስላልሰማህ፥ ያዘዘህንም ትእዛዙንና ሥርዐቱን ስላልጠበቅህ፥ እስክትጠፋ ድረስ እነዚህ መርገሞች ሁሉ ይወርዱብሃል፤ ያሳድዱህማል፤ ያገኙህማል።'),
  ('8749e858-19d2-5507-a4de-0d644ba52adc', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 32, 46, 'በአንተም በልጅ ልጅህም ላይ ለዘለዓለም ለምልክትና ለድንቅ ይሆናሉ።'),
  ('2f481c92-a44f-5fd2-a6ac-3797fe8b0e27', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 33, 47, '“ሁሉን አብዝቶ ስለ ሰጠህ አምላክህን እግዚአብሔርን በፍሥሓና በቀና ልብ አላመለክኸውምና፥'),
  ('4ccc4ae2-0733-58ad-a314-72d827389cbc', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 34, 48, 'በራብና በጥማት፥ በዕራቁትነትም፥ ሁሉንም በማጣት እግዚአብሔር ለሚልክብህ ለጠላቶችህ ትገዛለህ፤ እስኪያጠፋህም ድረስ በአንገትህ ላይ የብረት ቀንበር ይጭናል።'),
  ('048cf5b6-5aa4-5196-a7e8-6549b3e1f4dd', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 35, 49, 'እግዚአብሔርም ንስር እንደሚበርር ከሩቅ ሀገር፥ ከምድር ዳር ቋንቋቸውን የማትሰማውን ሕዝብ፥'),
  ('446e5b20-f852-5714-a983-e4178e0e810b', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 36, 50, 'ፊቱ የሚያስፈራውን፥ የሽማግሌውንም ፊት የማያፍረውን፥ ሕፃኑንም የማይምረውን ሕዝብ ያመጣብሃል።'),
  ('723ec5ce-2558-53e7-a17d-c23e886c7f2c', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 37, 51, 'እስክትጠፋም ድረስ የከብትህን ፍሬ፥ የምድርህንም ፍሬ ይበላል፤ እስኪያጠፋህም ድረስ እህልህን፥ ወይንህንም፥ ዘይትህንም፥ የላምህንና የበግህንም መንጋ አይተውልህም።'),
  ('92f69156-8340-5c2c-a5d3-f2a1c220c232', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 38, 52, 'በሀገርህ ሁሉ ያሉ፥ ትታመንባቸው የነበሩ፥ የረዘሙ፥ የጸኑም ቅጥሮች እስኪፈርሱ ድረስ፥ በከተሞችህ ሁሉ ያጠፋሃል፤ አምላክህም እግዚአብሔር በሰጠህ ምድር ሁሉ፥ በደጆች ሁሉ ያስጨንቅሃል።'),
  ('3de223d3-9cea-5e85-a452-bbf81ec929ce', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 39, 53, 'ጠላቶችህም በሀገርህ ውስጥ ከብበው ባስጨነቁህና መከራ ባሳዩህ ጊዜ አምላክህ እግዚአብሔር የሚሰጥህን የሆድህን ፍሬ፥ የወንዶችና የሴቶች ልጆችህን ሥጋ ትበላለህ።'),
  ('a04124a2-b5e1-5198-a3a8-6a515cf3087f', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 40, 54, 'በአንተ ዘንድ የተደላደለና የተቀማጠለ ሰው በወንድሙ፥ አብራውም በምትተኛ በሚስቱ፥ በቀሩትም ልጆቹ ይቀናል፤'),
  ('5e8461ff-f55f-5fc1-a23e-94d761bf0de7', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 41, 55, 'በከተሞችህ ሁሉ ውስጥ ጠላቶችህ ከብበው ባስጨነቁህና መከራ ባሳዩህ ጊዜ ሌላ ነገር የቀረው የለምና ከሚበላው ከልጆቹ ሥጋ ለአንዱ አይሰጥም።'),
  ('6c65d679-697a-551a-ad1e-8209c683eedd', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 42, 56, 'በአንተ ዘንድ የተለሳለሰችና የተቀማጠለች፥ ከልስላሴና ከቅምጥልነት የተነሣ የእግር ጫማዋን በምድር ላይ ያላደረገችው ሴት፥ አቅፋ በተኛችው ባልዋ፥ በወንድና በሴት ልጅዋም ትቀናለች፥'),
  ('f9770faf-3a23-5f84-a3c3-02abe2a5b229', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 43, 57, 'ከአካልዋ የሚወጣውን የእንግዴ ልጅ፥ የምትወልዳቸውንም ልጆች፤ በደጆችህ ውስጥ ጠላቶችህ፤ ከብበው ባስጨነቁህና መከራ ባሳዩህ ጊዜ ሁሉን ስላጣች በስውር ትበላቸዋለች።'),
  ('11ff7fac-19d8-5558-ab1d-d6e0228ca3bf', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 44, 58, '“በዚህ መጽሐፍ የተጻፉትን የዚህን ሕግ ቃሎች ሁሉ ታደርግ ዘንድ፥ ይህንም ክቡርና ምስጉን ስም እግዚአብሔር አምላክህን ትፈራ ዘንድ ባትሰማ፥'),
  ('ba795d5d-1269-5ef7-ac2f-42a9ce5dca8d', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 45, 59, 'እግዚአብሔር መቅሠፍትህን፥ የዘርህንም መቅሠፍት፥ ታላቅና የሚያስፈራ መቅሠፍትን፥ ለብዙ ጊዜ የሚኖር ክፉ ደዌና ሕማምን ሁሉ ያመጣብሃል።'),
  ('ee77cd2f-d964-5007-ab17-674b9da494cb', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 46, 60, 'የፈራኸውንም የግብፅ ደዌ ሁሉ እንደገና ያመጣብሃል፤ ያጣብቅብህማል።'),
  ('0347ce91-a2ae-5e6d-a299-4290cb6e5098', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 47, 61, 'ደግሞም ይህ ሕግ ባለበት መጽሐፍ ውስጥ ያልተጻፈውን ደዌ ሁሉ፥ መቅሠፍትንም ሁሉ እስክትጠፋ ድረስ እግዚአብሔር ያመጣብሃል።'),
  ('2185c64d-168b-5578-aa5a-2c5c2a6dd43c', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 48, 62, 'የአምላካችሁን የእግዚአብሔርን ቃል አልሰማችሁምና ከብዛታችሁ የተነሣ እንደ ሰማይ ከዋክብት የነበረው ቍጥራችሁ ጥቂት ሆኖ ይቀራል።'),
  ('5b6cf438-aa22-5cc4-ab21-cfb566fab36c', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 49, 63, 'እግዚአብሔርም በጎ ያደርግልህ ዘንድ፥ ያበዛህም ዘንድ ደስ ይለው እንደ ነበረ፥ እንዲሁ እግዚአብሔር ሲያጠፋህ፥ ሲያፈርስህም ደስ ይለዋል፤ ትወርሳትም ዘንድ ከምትገባባት ምድር ትነቀላለህ ።'),
  ('7523bb50-9492-5c2d-a61c-b5f3550ebb29', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 50, 64, 'እግዚአብሔርም ከምድር ዳር እስከ ዳርቻዋ ድረስ ወደ አሉ አሕዛብ ሁሉ ይበትንሃል፤ በዚያም አንተና አባቶችህ ያላወቃችኋቸውን ሌሎችን አማልክት፥ እንጨትንና ድንጋይን ታመልካለህ።'),
  ('9ec887d5-afb4-52d8-a9f8-f2a412e46cf9', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 51, 65, 'በእነዚያም አሕዛብ መካከል ዕረፍት አታገኝም፤ ለእግርህም ጫማ ማረፊያ አይሆንም፤ በዚያም እግዚአብሔር ተንቀጥቃጭ ልብ ፥ ፈዛዛ ዐይን፥ ደካማም ነፍስ ያመጣብሃል።'),
  ('a114788f-65f8-5a03-a07a-0f2ea1e95adf', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 52, 66, 'ሕይወትህ በዐይኖችህ ፊት የተሰቀለች ትሆናለች፤ ሌሊትና ቀንም ትደነግጣለህ፤ በሕይወትህም አትታመንም፤'),
  ('0ff0f147-57b5-5b4b-a9e8-ea8f5257829f', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 53, 67, 'ከፈራህበት ከልብህ ፍርሀት የተነሣ፥ በዐይንህም ካየኸው የተነሣ፥ ሲነጋ እንዴት ይመሽ ይሆን? ትላለህ፤ ሲመሽም እንዴት ይነጋ ይሆን? ትላለህ።'),
  ('a22129b8-485d-503c-adb5-a473845c4374', '416a0c0c-0823-5518-a73f-f2751004c34f', 'b5fad549-92f8-5e26-a117-8f9a169e7479', 54, 68, 'ከእንግዲህ ወዲህ ተመልሰህ አታያትም ባልሁህ መንገድም እግዚአብሔር በመርከብ ወደ ግብፅ ይመልስሃል፤ በዚያም ለጠላቶቻችሁ ወንዶችና ሴቶች አገልጋዮች ትሆናላችሁ፤ የሚራራላችሁም አይኖርም።”'),
  ('a1435376-3fcb-516c-ac49-a52b2e65700a', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 1, 1, 'እግዚአብሔር በኮሬብ ካደረገው ቃል ኪዳን ሌላ በሞዓብ ምድር ከእስራኤል ልጆች ጋር ያደርገው ዘንድ ሙሴን ያዘዘው የቃል ኪዳኑ ቃሎች እነዚህ ናቸው።'),
  ('342d8f31-4e0b-500c-a319-5dc7cb1797b5', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 2, 2, 'ሙሴም የእስራኤልን ልጆች ሁሉ ጠርቶ አላቸው፥ “እግዚአብሔር በፊታችሁ በግብፅ ምድር፥ በፈርዖንና በሹሞቹ ሁሉ፥ በምድሩም ሁሉ ያደረገውን ሁሉ፥'),
  ('11f9a748-b557-5060-a442-a639c83e5f20', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 3, 3, 'ዐይኖቻችሁም ያዩአቸውን ታላላቆች ፈተናዎችን፥ ታላላቆች ተአምራትንና ድንቆችን አይታችኋል።'),
  ('62f432f9-b8f2-5bd7-a846-ae686a5ab876', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 4, 4, 'እግዚአብሔር ግን ታስተውሉ ዘንድ ልብን፥ ታዩም ዘንድ ዐይንን፥ ትሰሙም ዘንድ ጆሮዎችን እስከ ዛሬ ድረስ አልሰጣችሁም።'),
  ('e6871955-4380-57f0-a21c-798bb911735a', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 5, 5, 'አርባ ዓመት በምድረ በዳ መራችሁ፤ ልብሳችሁም አላረጀባችሁም፤ ጫማችሁም በእግራችሁ ላይ አልተቀደደም።'),
  ('6634f8f9-d261-5b29-ae4d-e7f4d0959f09', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 6, 6, 'አምላካችሁ እግዚአብሔር እንደ ሆነ ታውቁ ዘንድ እዚህ ቦታ እስክትደርሱ ድረስ እንጀራ አልበላችሁም፤ የወይን ጠጅና የሚያሰክረውን መጠጥም አልጠጣችሁም።'),
  ('c5c622dd-45f3-5c96-ab64-d2c6e09a35fb', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 7, 7, 'የሐሴቦን ንጉሥ ሴዎን፥ የባሳንም ንጉሥ ዐግ ሊወጉን ወጡብን፤ እኛም መታናቸው፤'),
  ('7af387d6-45e3-5058-a65b-80375341cbd5', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 8, 8, 'ምድራቸውንም ወስደን ለሮቤልና ለጋድ፥ ለምናሴም ነገድ እኩሌታ ርስት አድርገን ሰጠናቸው።'),
  ('01dd6938-9036-52ac-aaf1-3c43a6677e63', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 9, 9, 'የምታደርጉት ሁሉ ይከናወንላችሁ ዘንድ የዚህን ቃል ኪዳን ቃሎች ታደርጉ ዘንድ ጠብቁ።'),
  ('b28ef89e-7212-5265-a7aa-07c499378269', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 10, 10, 'ሁላችሁ፥ የነገዶቻችሁ አለቆች ሽማግሌዎቻችሁም፥ ሹሞቻችሁም፥ ጻፎቻችሁም፥ የእስራኤል ወንድ ሁሉ ዛሬ በአምላካችሁ በእግዚአብሔር ፊት ቆማችኋል።'),
  ('f84acb23-3ba7-5971-a222-cce084710a04', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 11, 11, 'ሴቶቻችሁም፥ ልጆቻችሁም ከእንጨት ለቃሚያችሁ እስከ ውኃ ቀጃችሁ በሰፈራችሁ ያለ መጻተኛ፤'),
  ('b2d3291e-1d07-52b8-a7a8-10c2a993ca37', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 12, 12, 'ይኸውም አምላክህ እግዚአብሔር ከአንተ ጋር ዛሬ በሚያደርገው ቃል ኪዳንና አምላክህ እግዚአብሔር ከአንተ ጋር በተማማለው መሐላ ትገባ ዘንድ ነው።'),
  ('c4b292a6-c4df-56ad-a5e2-6188edfbfb44', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 13, 13, 'ዛሬ ለእርሱ ሕዝብ ያደርግህ ዘንድ፥ እርሱም ለአንተ እንደ ተናገረ ለአባቶችህም ለአብርሃምና ለይስሐቅ ለያዕቆብም እንደ ማለ አምላክ ይሆንልህ ዘንድ ነው።'),
  ('5ef03d57-fca6-5f1d-a9c5-2c9cbdf283d5', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 14, 14, '“እኔም ይህን ቃል ኪዳንና ይህን መሐላ የማደርገው ከእናንተ ጋር ብቻ አይደለም፤'),
  ('2099dda4-750f-59ec-a11c-6b2208e06728', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 15, 15, 'ነገር ግን ዛሬ በአምላካችሁ በእግዚአብሔር ፊት ከእኛ ጋር በዚህ ከሚቆም ሰው ጋር፥ ዛሬም ከእኛ ጋር በዚህ ከሌለ ሰው ጋር ነው እንጂ፤'),
  ('944be176-991a-5b83-ab46-d8114374973e', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 16, 16, 'ነገር ግን እኛ በግብፅ ምድር እንደ ተቀመጥን በመካከላቸውም ባለፋችሁባቸው አሕዛብ መካከል እንዳለፍን ዐውቃችኋልና፥'),
  ('75767382-3657-504a-a0ff-d456d206d2a2', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 17, 17, 'ርኩስነታቸውንም፥ በእነርሱም ዘንድ የነበሩትን የእንጨትና የድንጋይ፥ የብርና የወርቅም ጣዖቶቻቸውን አይታችኋልና፥'),
  ('8964c7ba-9ee7-5b00-a7fc-3bbd87ebe7ed', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 18, 18, 'ሄዶ የእነዚያን አሕዛብ አማልክት ያመልክ ዘንድ ከአምላካችሁ ከእግዚአብሔር ልቡን ዛሬ የሚያስት ወንድ ወይም ሴት ወይም ወገን ወይም ነገድ አይኑርባችሁ፤ ሐሞትና እሬትም የሚያበቅል ሥር አይሁንባችሁ።'),
  ('434c26f7-2793-5a31-a18a-734ea8190cee', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 19, 19, '“የዚህንም ርግማን ቃሎች በሰማችሁ ጊዜ በልቡ ‘ይህን በልቤ ስንፍና በማድረግ ሄጃለሁና ይቅር ይለኛል’ የሚል ቢኖር የበደለኛ ፍዳ ካልበደለ ጋር እንዳይተካከል፥'),
  ('a0d7f423-d4cf-5286-aed0-e3f4438f5df8', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 20, 20, 'የእግዚአብሔር ቍጣ፥ ቅንአቱም በዚያ ሰው ላይ ይነድዳል እንጂ እግዚአብሔር ይቅርታ አያደርግለትም፤ በዚህም መጽሐፍ የተጻፈው ርግማን ሁሉ በላዩ ይኖራል፤ እግዚአብሔርም ስሙን ከሰማይ በታች ይደመስሰዋል።'),
  ('55bdb43b-344d-5621-a784-a4653bde081e', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 21, 21, 'እግዚአብሔርም በዚህ ሕግ መጽሐፍ እንደ ተጻፈው እንደ ቃል ኪዳኑ ርግማን ሁሉ ከእስራኤል ነገዶች ሁሉ ለጥፋት ይለየዋል።'),
  ('ea1e3214-9bd9-598c-a761-72e4661104ed', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 22, 22, '“ከዚያም በኋላ የሚነሣ ትውልድ፥ ከእናንተም በኋላ የሚሆኑ ልጆቻችሁ ከሩቅ ሀገርም የሚመጣ እንግዳ፥ የዚችን ሀገር መቅሠፍት፥ እግዚአብሔርም በላይዋ የላከውን ሥቃይዋን፥'),
  ('1a9635e5-56e5-593e-a9ea-6656ec429817', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 23, 23, 'ምድርም በሁለንተናዋ ዲንና ጨው፥ መቃጠልም እንደ ሆነባት፥ እንዳይዘራባትም፥ እንዳታበቅልም፥ ማናቸውም ሣርና ልምላሜም እንዳይወጣባት፥ እግዚአብሔር በቍጣውና በመዓቱ እንደ ገለበጣቸው እንደ ሰዶምና ገሞራ፥ እንደ አዳማና እንደ ሲባዮ እንደ ሆነች ባዩ ጊዜ፥'),
  ('d902d0f5-81a0-5c9c-a88d-37c8aa2e3b26', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 24, 24, 'አሕዛብ ሁሉ እግዚአብሔር በዚህች ምድር ስለ ምን እንደዚህ አደረገ? ይህስ የቍጣው ታላቅ መቅሠፍት ምንድን ነው? ይላሉ።'),
  ('4b7501b6-b422-5ec9-a6eb-2a68633eaa96', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 25, 25, 'ሰዎችም እንዲህ ይላሉ፦ የአባቶቻቸው አምላክ እግዚአብሔር ከግብፅ ምድር ባወጣቸው ጊዜ ከአባቶቻቸው ጋር ያደረገውን ቃል ኪዳን ስለተዉ፥'),
  ('30979721-18a9-5cda-a53f-d34bc79ecaae', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 26, 26, 'ሄደውም የማያውቋቸውንና የማይጠቅሟቸውን ሌሎችን አማልክት ስላመለኩና ስለ ሰገዱላቸው፥'),
  ('694a77f4-8c4d-5f06-a251-d715ebb41878', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 27, 27, 'ስለዚህ በዚህ የሕግ መጽሐፍ የተጻፈውን መርገም ሁሉ ያመጣባት ዘንድ የእግዚአብሔር ቍጣ በዚህች ምድር ነደደ፤'),
  ('ff5dfccd-dc95-587e-a15a-444d33677c61', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 28, 28, 'ዛሬም እንዳሉ እግዚአብሔር በቍጣና በመቅሠፍት፥ በታላቅም መዓት ከምድራቸው ነቀላቸው፤ ወደ ሌላም ምድር ጣላቸው።'),
  ('a295e994-112a-54d0-a07a-50baed1f9bfd', '814aaeb2-897f-5e80-a8f7-3f912123529b', '110cc1ab-6803-5ce1-a56f-1ec13c4594cd', 29, 29, '“ምስጢሩ ለአምላካችን ለእግዚአብሔር ነው፤ የተገለጠው ግን የዚህን ሕግ ቃሎች ሁሉ እናደርግ ዘንድ ለእኛና ለልጆቻችን ለዘለዓለም ነው።'),
  ('40286db2-20c3-5ea1-a75b-435dd6bb7539', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 1, 1, '“እንዲህም ይሆናል፤ እኔ በፊትህ ያኖርሁት ይህ ነገር ሁሉ፥ በረከቱና መርገሙ በወረደብህ ጊዜ፥ አምላክህ እግዚአብሔር በሚበትንህ በዚያ በአሕዛብ ሁሉ መካከል ሆነህ በልብህ ዐስበው፤'),
  ('ee3fe216-2b5d-535f-a14d-48007a623ba0', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 2, 2, 'ወደ አምላክህ ወደ እግዚአብሔርም ተመለስ፤ እኔም ዛሬ እንደማዝዝህ ሁሉ አንተና ልጆችህ በፍጹም ልብና በፍጹም ነፍስ ቃሉን ስማ፤'),
  ('a92eb83c-700d-509d-ae5f-7c214c2918a0', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 3, 3, 'እግዚአብሔርም ኀጢአትህን ይቅር ይልሃል ይራራልህማል፤ እግዚአብሔርም አንተን ከበተነበት ከአሕዛብ ሁሉ መካከል መልሶ ይሰበስብሃል።'),
  ('0a45b2ce-8157-5332-aba6-cdae98eeadeb', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 4, 4, 'መበተንህም እስከ ሰማይ ዳርቻ ቢሆን አምላክህ እግዚአብሔር ከዚያ ይሰበስብሃል፤ ከዚያም ያመጣሃል።'),
  ('70bba968-2137-513e-ab20-af807e6bcb4d', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 5, 5, 'አባቶችህም ወደ ወረሱአት ምድር አምላክህ እግዚአብሔር ይወስድሃል፤ ትወርሳትማለህ፤ መልካምም ነገር ያደርግልሃል፤ ከአባቶችህም ይልቅ ያበዛሃል።'),
  ('80488362-b75c-501d-a5e6-8b4b0aa5fa60', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 6, 6, 'በሕይወትም እንድትኖር፥ አምላክህን እግዚአብሔርንም በፍጹም ልብህ፥ በፍጹምም ነፍስህ እንድትወድድ እግዚአብሔር ልብህን፥ የዘርህንም ልብ ያጠራዋል።'),
  ('5846aa89-0176-5c22-ab10-70c26f45d24a', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 7, 7, 'አምላክህም እግዚአብሔር ይህችን መርገም ሁሉ በጠላቶችህና በሚጠሉህ በሚያሳድዱህም ላይ ያመጣታል።'),
  ('0853d5f6-2047-53bd-a09c-a6f9e9cb617c', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 8, 8, 'አንተም ተመልሰህ የአምላክህን የእግዚአብሔርን ቃል ትሰማለህ፤ ዛሬም እኔ የማዝዝህን ትእዛዙን ሁሉ ታደርጋለህ።'),
  ('2dd74c38-8ff2-5e57-ac28-5c2d7471a73f', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 9, 9, 'እግዚአብሔርም በአባቶችህ ደስ እንዳለው በመልካሙ ነገር ሁሉ እንደ ገና በአንተ ደስ ይለዋልና አምላክህ እግዚአብሔር በእጅህ ሥራ ሁሉ፥ በሆድህም ፍሬ፥ በእርሻህም ፍሬ፥ በከብትህም ብዛት እጅግ ይባርክሃል።'),
  ('53a64990-b4af-5a9d-af93-8757db982194', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', '101c7ae9-4392-525f-a9c4-93ae62b48a55', 10, 10, 'በዚህ የሕግ መጽሐፍ የተጻፉትን ትእዛዙን፥ ሥርዐቱንና ፍርዱን ትጠብቅና ታደርግ ዘንድ የአምላክህን የእግዚአብሔርን ቃል ብትሰማ፥ በፍጹም ልብህ፥ በፍጹምም ነፍስህ ወደ አምላክህ ወደ እግዚአብሔር ብትመለስ ይባርክሃል።'),
  ('e9667de2-0d6b-54d0-a7d4-4655d4d6fcfa', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 1, 11, '“እኔ ዛሬ የማዝዝህ ይህች ትእዛዝ ከባድ አይደለችም፤ ከአንተም የራቀች አይደለችም።'),
  ('30cb9fcf-e1af-5e93-a0d8-33f451efde69', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 2, 12, 'ሰምተን እናደርጋት ዘንድ ስለ እኛ ወደ ሰማይ ወጥቶ እርስዋን የሚያመጣልን ማንነው? እንዳትል በሰማይ አይደለችም።'),
  ('3d7c6442-ae1c-55ec-a8dc-71ab5f720028', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 3, 13, 'ሰምተን እናደርጋት ዘንድ ስለ እኛ ባሕሩን ተሻግሮ እርስዋን የሚያመጣልን ማን ነው? እንዳትል ከባሕሩ ማዶ አይደለችም።'),
  ('82ee1c59-8e11-5309-ab1a-381e3621086c', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 4, 14, 'ታደርገው ዘንድ ቃሉ በአፍህና በልብህ፥ በእጅህም ውስጥ ለአንተ እጅግ ቅርብ ነው።'),
  ('51520eb6-7ebf-54fb-a4f3-775fae6deafd', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 5, 15, '“እነሆ፥ ዛሬ በፊትህ ሕይወትንና ሞትን፥ መልካምነትንና ክፉነትን አኑሬአለሁ።'),
  ('bb766a71-e073-5a14-aeb4-2f414b19c822', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 6, 16, 'ዛሬ እኔ የማዝዝህን የአምላክህን የእግዚአብሔርን ትእዛዛት ብትሰማ፥ አምላክህን እግዚአብሔርንም ብትወድድ፥ በመንገዶቹም ሁሉ ብትሄድ፥ ሥርዐቱንና ፍርዱንም ብትጠብቅ በሕይወት ትኖራለህ፤ በቍጥርም ትበዛለህ፤ አምላክህ እግዚአብሔርም ልትወርሳት በምትሄድባት በምድሪቱ ሁሉ ይባርክሃል።'),
  ('7a3d9f10-7c31-5004-ae93-90f8d2aefb01', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 7, 17, 'ልብህ ግን ቢስት፥ አንተም ባትሰማ፥ ብትታለልም፥ ለሌሎች አማልክትም ብትሰግድ፥ ብታመልካቸውም፥'),
  ('38a51b45-918f-5693-a3b3-0be142fd1955', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 8, 18, 'ፈጽመህ እንደምትጠፋ እኔ ዛሬ እነግርሃለሁ፤ ዮርዳኖስን ተሻግረህ ትወርሳት ዘንድ በምትገባባት ምድር ዘመንህ አይረዝምም።'),
  ('3f167ad8-ade7-5f5a-aa94-e7ae8f8bb48a', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 9, 19, 'በፊትህ ሕይወትንና ሞትን፥ በረከትንና መርገምን እንዳስቀመጥሁ እኔ ዛሬ ሰማይንና ምድርን በአንተ ላይ አስመሰክራለሁ፤ እንግዲህ አንተና ዘርህ በሕይወት ትኖሩ ዘንድ ሕይወትን ምረጥ፤'),
  ('80e18b25-655e-5d8a-a771-1c8dc66415b3', '88dbe4b6-e47a-59e7-a051-1e073a1deefb', 'aaa58917-c7a9-5d4b-a15d-30b05ddb4d9e', 10, 20, 'እግዚአብሔርም ለአባቶችህ ለአብርሃምና ለይስሐቅ ለያዕቆብም እንዲሰጣቸው በማለላቸው በምድሪቱ ትቀመጥ ዘንድ፥ እርሱ ሕይወትህ፥ የዘመንህም ርዝመት ነውና አምላክህን እግዚአብሔርን ውደደው፤ ቃሉን ስማው፤ አጥናውም።”'),
  ('f29b0c1b-cb80-5a1a-a3a7-fcbd1e7debf4', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 1, 1, 'ሙሴም ይህን ቃል ለእስራኤል ልጆች ሁሉ ተናግሮ ጨረሰ።'),
  ('c732da05-1236-5a11-a48e-92fae20feb42', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 2, 2, 'አላቸውም፥ “እኔ ዛሬ መቶ ሃያ ዓመት ሆኖኛል፤ ከዚህ በኋላ እወጣና እገባ ዘንድ አልችልም፤ እግዚአብሔርም፦ ‘ይህን ዮርዳኖስን አትሻገርም’ ብሎኛል።'),
  ('3a5e43e2-d8fc-5a61-ae6f-38c4bb747689', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 3, 3, 'አምላክህ እግዚአብሔር እርሱ በፊትህ ያልፋል፤ እርሱ እነዚህን አሕዛብ ከፊትህ ያጠፋቸዋል፤ ትወርሳቸውማለህ፤ እግዚአብሔር እንደ ተናገረ ኢያሱ በፊትህ ይሄዳል።'),
  ('5293961b-e93f-5103-ac30-a5b6c7451ccf', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 4, 4, 'እግዚአብሔር አምላክም ባጠፋቸው በዮርዳኖስ ማዶ በሚኖሩ በሁለቱ በአሞሬዎናውያን ነገሥታት በሴዎንና በዐግ፥ በምድራቸውም እንዳደረገ እንዲሁ ያደርግባቸዋል።'),
  ('7025f171-5e4d-5909-abe9-3993dfa326ff', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 5, 5, 'እግዚአብሔርም በፊታችሁ አሳልፎ ይጥላቸዋል፤ እንዳዘዝኋችሁም ሁሉ ታደርጉባቸዋላችሁ።'),
  ('9e9a66ce-2404-5003-a7e2-76adc99259d8', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 6, 6, 'ጽና፤ በርታ፤ አትፍራ፤ ከፊታቸውም አትደንግጥ፤ አትድከም፤ አምላክህ እግዚአብሔር እርሱ ከአንተ ጋር ይሄዳል፤ አይጥልህም፤ አይተውህምም።'),
  ('4ffcadaf-66b7-537c-a474-70d673fed711', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 7, 7, 'ሙሴም ኢያሱን ጠርቶ በእስራኤል ሁሉ ፊት፦ ‘አንተ ከዚህ ሕዝብ ጋር እግዚአብሔር ለአባቶቻቸው እንዲሰጥ ወደ ማለላቸው ምድር ትገባለህና፥ እርስዋንም ለእነርሱ ታወርሳለህና ጽና፤ በርታ።'),
  ('1fa00ed0-83f0-5447-a007-d7d939ecaaa0', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '835ee8ee-8b9b-5486-ae6e-57d9d02ffe92', 8, 8, 'በፊትህም የሚሄድ እርሱ እግዚአብሔር ነው፤ ከአንተ ጋር ይሆናል፤ አይጥልህም፤ አይተውህም፤ አትፍራ፤ አትደንግጥ’ ” አለው።'),
  ('2dd78c34-dd64-5dc5-a88b-2f73fb4fb2c7', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '97396896-864d-54f9-ab7a-050f63de2a25', 1, 9, 'ሙሴም ይህችን ሕግ ጻፈ፤ የእግዚአብሔርንም የቃል ኪዳኑን ታቦት ይሸከሙ ለነበሩት ለሌዊ ልጆች ለካህናቱ፥ ለእስራኤልም ሽማግሌዎች ሁሉ ሰጣት።'),
  ('3031c428-7e2b-5079-a15c-9342ba56510f', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '97396896-864d-54f9-ab7a-050f63de2a25', 2, 10, 'ሙሴም በዚያች ቀን እንዲህ ብሎ አዘዛቸው፥ “በሰባተኛው ዓመት መጨረሻ በምሕረት ዓመት በዳስ በዓል፥'),
  ('d0881b98-6085-5cf7-a6b3-95168cb62d20', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '97396896-864d-54f9-ab7a-050f63de2a25', 3, 11, 'እስራኤል ሁሉ በአምላክህ በእግዚአብሔር ፊት ይታይ ዘንድ እርሱ በመረጠው ቦታ በአንድነት በሚሄድበት ጊዜ፥ ይህን ሕግ በእስራኤል ሁሉ ፊት በጆሮው አንብበው።'),
  ('5b34664d-8dcc-5211-af0f-7df0066618a1', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '97396896-864d-54f9-ab7a-050f63de2a25', 4, 12, 'ይሰሙና ይማሩ ዘንድ፥ አምላካችሁንም እግዚአብሔርን ይፈሩ ዘንድ፥ የዚህን ሕግ ቃሎች ሁሉ ሰምተው ያደርጉ ዘንድ ሕዝቡን ወንዶችና ሴቶችን፥ ሕፃኖቻችሁንም፥ በሀገራችሁ ደጅ ያለውንም መጻተኛ ሰብስብ።'),
  ('058cf85d-21d2-5992-a466-6be804c1eb59', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '97396896-864d-54f9-ab7a-050f63de2a25', 5, 13, 'የማያውቁ ልጆቻቸውም ዮርዳኖስን ተሻግራችሁ ልትወርሱአት በምትሄዱባት ምድር በምትኖሩበት ዘመን ሁሉ ይስሙ፤ አምላካችሁን እግዚአብሔርንም መፍራት ይማሩ።”'),
  ('ca82c2ed-c7a1-56c4-a323-96a2a87ecd18', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 1, 14, 'እግዚአብሔርም ሙሴን፥ “የምትሞትበት ቀን እነሆ ቀረበ፤ ኢያሱን ጠርተህ እርሱን አዝዘው ዘንድ በምስክሩ ድንኳን ውስጥ ከእርሱ ጋር ቁም” አለው። ሙሴና ኢያሱም ሄደው በምስክሩ ድንኳን ውስጥ ቆሙ።'),
  ('7643a31f-e62d-5124-aa04-fc6bf845939e', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 2, 15, 'እግዚአብሔርም በምስክሩ ድንኳን ውስጥ በደመና ዐምድ ወረደ፤ የደመናውም ዐምድ በምስክሩ ድንኳን ደጃፍ ላይ ቆመ።'),
  ('4af668a9-681a-5a47-a856-a22b297c529e', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 3, 16, 'እግዚአብሔርም ሙሴን አለው፥ “እነሆ፥ ከአባቶችህ ጋር ታንቀላፋለህ፤ ይህም ሕዝብ ይነሣል፤ ይቀመጥባትም ዘንድ በሚሄድባት ምድር መካከል ያሉትን ሌሎችን አማልክት ተከትሎ ያመነዝራል፤ እኔንም ይተወኛል፤ ከእነርሱም ጋር ያደረግሁትን ቃል ኪዳን ያፈርሳሉ።'),
  ('c81ecf18-67b4-555f-adf9-649de8b9dfa3', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 4, 17, 'በዚያም ቀን ቍጣዬ ይነድድባቸዋል፤ እተዋቸውማለሁ፤ ፊቴንም ከእነርሱ እመልሳለሁ፤ ለጠላቶቻቸውም መብል ይሆናሉ፤ በዚያም ቀን፦ በእውነት አምላካችን እግዚአብሔር ትቶናልና፥ በእኛም መካከል የለምና ይህ ክፉ ነገር ሁሉ አገኘን እስኪሉ ድረስ ብዙ ክፉ ነገርና ጭንቀት ይደርስባቸዋል።'),
  ('e9228cc3-f9f6-5f43-a3f3-1a0041a64054', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 5, 18, 'ሌሎችን አማልክት ተከትለዋልና ስላደረጉት ክፋት ሁሉ እኔ በዚያ ቀን ፈጽሜ ፊቴን እሰውራለሁ።'),
  ('3fdf5304-5a1a-52e2-a1d2-498c7db2d2fd', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 6, 19, 'አሁንም ይህችን መዝሙር ለእናንተ ጻፉ፤ ለእስራኤልም ልጆች አስተምሩአቸው፤ ይህችም መዝሙር በእስራኤል ላይ ምስክር ትሆንልኝ ዘንድ በአፋቸው አድርጓት።'),
  ('61a25acb-78d2-544e-a6b6-03c8888ad9c5', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 7, 20, 'ለአባቶቻቸው ወደ ማልሁላቸው፥ ወተትና ማር ወደምታፈስሰው ምድር ካገባኋቸው በኋላ፥ ከበሉም፥ ከጠገቡም በኋላ ይስታሉ፤ ሌሎችን አማልክትም ወደ ማምለክ ይመለሳሉ፤ እኔንም ያስቈጡኛል፤ ቃል ኪዳኔንም ያፈርሳሉ።'),
  ('16882618-9a2d-5381-a73a-106b2d618fcb', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 8, 21, 'ዛሬ ወደ ማልሁላቸው ምድር ገና ሳላገባቸው ክፋታቸውን አውቃለሁና፥ ከአፋቸውና ከልጆቻቸውም አፍ አትረሳምና ብዙ ክፉ ነገርና ጭንቀት በደረሰባቸው ጊዜ ይህች መዝሙር ምስክር ሆና በፊታቸው ትቆማለች።”')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('bdf1d2f2-6a62-561d-ac55-c99dbbbabb5a', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 9, 22, 'ሙሴም በዚያ ቀን ይህችን መዝሙር ጻፈ፤ ለእስራኤልም ልጆች አስተማራት።'),
  ('6a2c0a99-009d-5ff8-acd0-d71e68a0a95f', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 10, 23, 'የነዌንም ልጅ ኢያሱን፥ “የእስራኤልን ልጆች እግዚአብሔር ለአባቶቻቸው ወደ ማለላቸው ምድር ታገባለህና ጽና፤ በርታ፤ እርሱም ከአንተ ጋር ይሆናል” ብሎ አዘዘው።'),
  ('95d54d27-35d6-5e82-ac77-e8abd7916fdd', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 11, 24, 'እንዲህም ሆነ፤ ሙሴ የዚህን ሕግ ቃሎች እስከ መጨረሻ በመጽሐፍ ጽፎ ከፈጸመ በኋላ፥'),
  ('7f15c301-a84d-5ba2-ab44-a657d9ed8a5b', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 12, 25, 'የእግዚአብሔርን ቃል ኪዳን ታቦት የሚሸከሙትን ሌዋውያንን እንዲህ ብሎ አዘዛቸው፦'),
  ('b21e3ca2-3c7e-5a7b-a606-e61695adaf5d', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 13, 26, '“ይህን የሕግ መጽሐፍ ውሰዱ፤ በዚያም በእናንተ ላይ ምስክር እንዲሆን በአምላካችሁ በእግዚአብሔር ቃል ኪዳን ታቦት አጠገብ አኑሩት።'),
  ('fcc83c05-5b16-5b83-ad46-7cec1b4d5085', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 14, 27, 'እኔ ዐመፃችሁንና የአንገታችሁን ድንዳኔ አውቃለሁና፤ እኔም ዛሬ ከእናንተ ጋር ገና በሕይወት ሳለሁ እናንተ በእግዚአብሔር ላይ ዐምፃችኋል፤ ይልቁንስ ከሞትሁ በኋላ እንዴት ይሆናል?'),
  ('66397ca9-36ab-5139-ada8-6e281f33b2c5', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 15, 28, 'ይህን ቃል በጆሮአቸው እነግር ዘንድ፥ ሰማይንና ምድርንም አስመሰክርባቸው ዘንድ የነገዶቻችሁን አለቆች፥ ሽማግሌዎቻችሁን ሁሉ፥ ሹሞቻችሁንም፥ ጻፎቻችሁንም ሰብስቡልኝ፤'),
  ('327ccf90-c58a-5e57-a524-e9097ff7d68c', '170c9dc8-d24a-5d16-abad-4e332b64eb77', '5f9b223b-b223-531a-acb5-7bb697ee5640', 16, 29, 'ከሞትሁ በኋላ ፈጽማችሁ እንድትረክሱ፥ ካዘዝኋችሁም መንገድ ፈቀቅ እንድትሉ አውቃለሁና። በእጃችሁም ሥራ ታስቈጡት ዘንድ በእግዚአብሔር ፊት ክፉ ስላደረጋችሁ፥ በኋለኛው ዘመን ክፉ ነገር ያገኛችኋል።”'),
  ('366a8e7a-5ca3-586c-a47a-08668977dee6', '170c9dc8-d24a-5d16-abad-4e332b64eb77', 'ba04bf9c-ea6e-57c2-ac1f-c08e43bc29ef', 1, 30, 'ሙሴም በእስራኤል ጉባኤ ሁሉ ጆሮ የዚህችን መዝሙር ቃሎች እስከ መጨረሻው ድረስ ተናገረ።'),
