  ('e66c0a15-5db5-50c5-a512-d11911b648a1', 'c8181823-9229-5561-aa87-c00cb6349379', 'f69462dd-a6ba-5817-ac61-2edbf56287bf', 44, 44, 'ሙሴም በዚያች ቀን ይህችን መዝሙር ጻፋት፤ ለእስራኤልም ልጆች አስተማራት፤ ሙሴም ገባ እርሱና የነዌ ልጅ ኢያሱም የዚህችን ሕግ ቃሎች ሁሉ በሕዝቡ ጆሮ ተናገሩ።'),
  ('8c2af331-a0f8-5bcc-aea8-2d83e189cbb3', 'c8181823-9229-5561-aa87-c00cb6349379', 'f8b84e36-b790-56cc-abc1-e273aae768aa', 1, 45, 'ሙሴም ይህን ቃል ሁሉ ለእስራኤል ሁሉ ተናግሮ ፈጸመ።'),
  ('c40f1356-5a75-519c-ab30-a76887ec957d', 'c8181823-9229-5561-aa87-c00cb6349379', 'f8b84e36-b790-56cc-abc1-e273aae768aa', 2, 46, 'እርሱም እንዲህ አላቸው፥ “የዚህን ሕግ ቃሎች ሁሉ ይጠብቁና ያደርጉ ዘንድ ልጆቻችሁን እንድታዝዙበት ዛሬ የምመሰክርላችሁን ቃል ሁሉ በልባችሁ አኑሩት።'),
  ('25a85d04-156c-5683-a896-907b91f59f43', 'c8181823-9229-5561-aa87-c00cb6349379', 'f8b84e36-b790-56cc-abc1-e273aae768aa', 3, 47, 'ይህ ነገር ሕይወታችሁ ነው እንጂ ለእናንተ ከንቱ አይደለምና፤ በዚህም ነገር ትወርሱአት ዘንድ ዮርዳኖስን ተሻግራችሁ በምትገቡባት ምድር ዘመናችሁ ይረዝማል።”'),
  ('68a1c763-67c3-5b8b-ab63-a5b7d2ff8981', 'c8181823-9229-5561-aa87-c00cb6349379', 'd1a93e82-50ae-51bf-a92e-7e4ac8d2ffe5', 1, 48, 'በዚያም ቀን እግዚአብሔር ሙሴን እንዲህ ብሎ ተናገረው፦'),
  ('644e25c0-1ca3-55fb-a2c2-7e58f19e6b8b', 'c8181823-9229-5561-aa87-c00cb6349379', 'd1a93e82-50ae-51bf-a92e-7e4ac8d2ffe5', 2, 49, '“በኢያሪኮ አንጻር በሞዓብ ምድር በዓባሪም ተራራ ውስጥ ወዳለው ወደ ናባው ተራራ ውጣ፤ ለእስራኤልም ልጆች ርስት አድርጌ የምሰጣቸውን የከነዓንን ምድር እያት፤'),
  ('e4bba0ae-7f09-511e-ad64-d614f698971f', 'c8181823-9229-5561-aa87-c00cb6349379', 'd1a93e82-50ae-51bf-a92e-7e4ac8d2ffe5', 3, 50, 'ወንድምህ አሮን በሖር ተራራ እንደ ሞተ፥ ወደ ወገኖቹም እንደ ተጨመረ፥ በወጣህበት ተራራ ሙት፤ ወደ ወገኖችህም ተጨመር፤'),
  ('85c3e064-1f2b-5b27-a1d6-b62a15d1d17e', 'c8181823-9229-5561-aa87-c00cb6349379', 'd1a93e82-50ae-51bf-a92e-7e4ac8d2ffe5', 4, 51, 'በእስራኤል ልጆች መካከል በጺን ምድረ በዳ በቃዴስ ባለው በክርክር ውኃ ለቃሌ አልታዘዛችሁምና፥ በእስራኤልም ልጆች መካከል አልቀደሳችሁኝምና፥'),
  ('b925d900-c558-5837-ae71-6e1e736b9be4', 'c8181823-9229-5561-aa87-c00cb6349379', 'd1a93e82-50ae-51bf-a92e-7e4ac8d2ffe5', 5, 52, 'ምድሪቱን ፊት ለፊት ታያለህ እንጂ ወደዚያች ምድር አትገባም።”'),
  ('e7496cc5-dcec-5e6e-ae1b-6a710b5fa75c', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 1, 1, 'የእግዚአብሔር ሰው ሙሴ ሳይሞት የእስራኤልን ልጆች የባረከባት በረከት ይህች ናት።'),
  ('122b9132-a23f-5993-af3b-a14b53e628cc', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 2, 2, 'እንዲህም አለ፦'),
