  ('452978e9-a4e4-5f8b-ab7c-d93204ec72b7', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 10, 10, 'ፍርድህን ለያዕቆብ፥'),
