  ('ef49d409-b7ad-5a8b-ab06-fc89665eff03', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 15, 15, 'ከቀደሙትም ተራሮች ከፍተኛነት፥'),
  ('c1ab8044-7c7e-5cc6-a8ad-18d7c534bcf0', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 16, 16, 'በየወቅቱም ከምድሪቱ ምላት፥'),
