  ('07aae22b-a82a-5ee9-a8be-35b536b934d8', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 19, 19, 'አሕዛብን ያጠፉአቸዋል፤'),
  ('450d0c2b-945d-5771-af27-3aa5dcf0475a', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 20, 20, 'ስለ ጋድም እንዲህ አለ፦'),
