  ('b9cc5d54-4d3c-561e-a576-af2a4ecf914c', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 22, 22, 'ስለ ዳንም እንዲህ አለ፦'),
  ('028610b9-3ccd-5f66-a0ad-3db6d0aa72a0', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 23, 23, 'ስለ ንፍታሌምም እንዲህ አለ፦'),
  ('1ed5648b-04d0-5309-a638-a1373377bd54', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 24, 24, 'ስለ አሴርም እንዲህ አለ፦'),
  ('6bd52dc1-09f9-5aaf-ac42-6b07a78a2cd1', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 25, 25, 'ጫማህ ብረትና ናስ ይሆናል፤'),
  ('e8af9497-a9e1-5c5b-a425-897963ca7352', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 26, 26, 'እንደ ፍቁሩ አምላክ ማንም የለም፤'),
  ('70c3c8c2-9eb4-5a10-a399-109eacefb3ef', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 27, 27, 'እግዚአብሔርም ፊት ለፊት፥'),
  ('e05a6263-b5d6-5eca-ad9b-f3b576150233', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 28, 28, 'እስራኤልም ተማምኖ፥'),
  ('e85b6405-180b-5509-a085-90f4dec33bd0', '86df8c35-422b-5daa-af38-c56968621c20', 'c354a4ed-7f54-52ad-a0ee-4bd6c5bf0bec', 29, 29, 'እስራኤል ሆይ ብፁዕ ነህ፤'),
  ('2149be64-900f-5c18-ac57-0df43be03041', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 1, 1, 'ሙሴም ከሞዓብ ሜዳ በኢያሪኮ ፊት ለፊት ወዳለው ወደ ናባው ተራራ ወደ ፈስጋ ራስ ወጣ፤ እግዚአብሔርም እስከ ዳን ድረስ ያለውን የገለዓድን ምድር አሳየው፤'),
  ('b5e82837-0c1b-5c2e-aea0-1c563ce8f400', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 2, 2, 'የንፍታሌምንም ምድር ሁሉ፥ የምናሴንም ምድር ሁሉ፥ እስከ ምዕራብም ባሕር ድረስ ያለውን የይሁዳን ምድር ሁሉ፤'),
  ('5096b8e8-7bdc-5ddc-a050-efa1588ed620', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 3, 3, 'ምድረ በዳውን፥ የኢያሪኮን ዙሪያ፥ እስከ ሴይር ዙሪያ ያለውንም የፊንቆንን ከተማ አሳየው፤'),
  ('e5c5858d-d9ba-56b6-aae2-dd3b9b82ea29', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 4, 4, 'እግዚአብሔርም ሙሴን፥ “ለዘርህ እሰጣታለሁ ብዬ ለአብርሃምና ለይስሐቅ ለያዕቆብም የማልሁላቸው ምድር ይህች ናት፤ እነሆም፥ በዐይንህ እንድታያት አደረግሁህ፤ ነገር ግን ወደዚያች አትገባም” አለው።'),
  ('5a6928b2-b117-5d16-a990-cf4aed7b833e', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 5, 5, 'የእግዚአብሔር አገልጋይ ሙሴም እንደ እግዚአብሔር ቃል በዚያ በሞዓብ ምድር ሞተ።'),
  ('e396de61-82d1-5faa-af25-f4ed9beb7415', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 6, 6, 'በቤተ ፌጎርም አቅራቢያ በናባው ምድር ቀበሩት፤ እስከ ዛሬም ድረስ መቃብሩን ማንም የሚያውቅ የለም።'),
  ('db8b9cb7-e8d5-5050-ada0-aacb16800465', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 7, 7, 'ሙሴም በሞተ ጊዜ ዕድሜዉ መቶ ሃያ ዓመት ነበረ፤ ዐይኖቹም አልፈዘዙም፤ ጕልበቱም አልደከመም ነበር።'),
  ('fff67816-f420-59b0-aa3c-866906d47376', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 8, 8, 'የእስራኤልም ልጆች በዮርዳኖስ በኢያሪኮ አቅራቢያ በሞዓብ ሜዳ ሠላሳ ቀን ለሙሴ አለቀሱለት፤ ለሙሴም ያለቀሱለት የልቅሶው ወራት ተፈጸመ።'),
  ('b2922365-135b-50ad-a886-ff69b6220293', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 9, 9, 'ሙሴም እጆቹን ስለ ጫነበት የነዌ ልጅ ኢያሱ የጥበብን መንፈስ ተሞላ፤ የእስራኤልም ልጆች ታዘዙለት፤ እግዚአብሔርም ሙሴን እንዳዘዘው አደረጉ።'),
  ('8305e148-d239-5088-aebc-cdfb5bb0f694', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 10, 10, 'እግዚአብሔር ፊት ለፊት እንደ ተናገረው እንደ ሙሴ ያለ ነቢይ ከዚያ ወዲህ በእስራኤል ዘንድ አልተነሣም፤'),
  ('cdcb3cd0-5b16-565e-a805-fbc3b8430219', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 11, 11, 'በግብፅ ምድር በፈርዖንና በሹሞቹ ሁሉ ላይ፥ በምድሪቱም ሁሉ ላይ ምልክትንና ድንቅን ያደርግ ዘንድ እግዚአብሔር እንደ ላከው ያለ፥'),
  ('ceb7b672-bb79-59f8-a135-797a5a54475c', '763d0b98-15ec-51e4-ab2a-28e8479fe08d', '8b1a7bf0-e8e5-5c3c-a391-a90daddeef3f', 12, 12, 'በእስራኤል ሁሉ ፊት በታላቅ ተአምር ሁሉና በጸናች እጅ፥ በተዘረጋችም ክንድ ሁሉ እንዳደረገው እንደ ሙሴ ያለ ነቢይ አልተነሣም።'),
  ('45e82459-c5a3-5104-a44f-6d7c999340d2', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 1, 1, 'እንዲህም ሆነ፤ የእግዚአብሔር አገልጋይ ሙሴ ከሞተ በኋላ እግዚአብሔር የሙሴን አገልጋይ የነዌን ልጅ ኢያሱን እንዲህ ብሎ ተናገረው፦'),
  ('ac714a2f-3cf9-5af7-a50e-d90d7307244a', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 2, 2, '“አገልጋዬ ሙሴ ሞቶአል፤ አሁንም አንተና ይህ ሕዝብ ሁሉ ተነሥታችሁ ለእስራኤል ልጆች ወደምሰጣቸው ምድር ይህን ዮርዳኖስን ተሻገሩ።'),
  ('352000f7-e27b-58c9-a76b-58a1d1527362', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 3, 3, 'ለሙሴ እንደ ነገርሁት የእግራችሁ ጫማ የሚረግጠውን ቦታ ሁሉ ለእናንተ ሰጥቼአለሁ።'),
  ('ab5486e9-72d4-5db9-a9ed-ea294c443afb', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 4, 4, 'ከሊባኖስ ፊት ለፊት ምድረ በዳ ጀምሮ እስከ ታላቁ ወንዝ እስከ ኤፍራጥስ ድረስ የኬጤዎናውያን ምድር ሁሉ እስከ ፀሐይ መግቢያ እስከ ታላቁ ባሕር ድረስ ወሰናችሁ ይሆናል።'),
  ('3b2c7bc3-1b63-5b1d-a39b-1e163a77f6c8', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 5, 5, 'በሕይወትህ ዘመን ሁሉ የሚቋቋምህ የለም፤ ከሙሴ ጋር እንደ ነበርሁ እንዲሁ ከአንተ ጋር እሆናለሁ፤ አልጥልህም፥ ቸልም አልልህም።'),
  ('8995d2ae-e821-5d12-ab2f-9ceb555b6122', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 6, 6, 'ለአባቶቻቸው እሰጣቸው ዘንድ የማልሁላቸውን ምድር ለዚህ ሕዝብ ታወርሳለህና ጽና፥ በርታ።'),
  ('2affcf7a-3496-5dab-a1b9-1195668aacbd', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 7, 7, 'አገልጋዬ ሙሴ እንደ አዘዘህ ሕግን ሁሉ ትጠብቅና ታደርግ ዘንድ ጽና፤ እጅግም በርታ፤ ሁሉን እንዴት እንደምትሠራ ታውቅ ዘንድ ከእርሱ ወደ ቀኝ ወደ ግራም አትበል።'),
  ('1623e1b8-9bce-5423-a101-b7a13e0c4056', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 8, 8, 'የዚህ ሕግ መጽሐፍ ከአፍህ አይለይ፤ ነገር ግን የተጻፈበትን ሁሉ ትጠብቅና ታደርግ ዘንድ በቀንም በሌሊትም አንብበው፤ የዚያን ጊዜም መንገድህ ይቀናልሃል፤ አስተዋይም ትሆናለህ።'),
  ('56e8309e-ef89-58e3-a693-4b56451098e9', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 9, 9, 'እነሆ አዝዝሃለሁ፤ በምትሄድበት ሁሉ አምላክህ እግዚአብሔር ከአንተ ጋር ነውና ጽና፥ በርታ፤ አትፍራ፥ አትደንግጥም።”'),
  ('972289e3-ccee-5b77-ad11-b9a22c6b9eb0', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 10, 10, 'ኢያሱም የሕዝቡን ጻፎች እንዲህ ብሎ አዘዛቸው፦'),
  ('9bcc3924-6fb2-57c5-a430-ec320fab0abd', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 11, 11, '“በሰፈሩ መካከል ዕለፉ፥ ሕዝቡንም፦ የአባቶቻችሁ አምላክ እግዚአብሔር ርስት አድርጎ ወደሚሰጣችሁ ምድር እስከ ሦስት ቀን ይህን ዮርዳኖስን ተሻግራችሁ ልትወርሱአት ትገቡባታላችሁና ስንቃችሁን አዘጋጁ ብላችሁ እዘዙአቸው።”'),
  ('452d0a10-2c97-51a8-a2ea-c5a4d999d490', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 12, 12, 'ኢያሱም ሮቤልንና ጋድን የምናሴንም ነገድ እኩሌታ እንዲህ ብሎ ተናገራቸው፦'),
  ('bd8f0521-1a80-5867-ad2e-b434367afac3', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 13, 13, '“የእግዚአብሔር አገልጋይ ሙሴ እንዲህ ብሎ ያዘዛችሁን ቃል አስቡ፦ አምላካችሁ እግዚአብሔር ያሳርፋችኋል፤ ይህችንም ምድር ይሰጣችኋል።'),
  ('656fd678-835f-5534-ae2a-06d60bef461d', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 14, 14, 'ሚስቶቻችሁና ልጆቻችሁ ከብቶቻችሁም ሙሴ በዮርዳኖስ ማዶ በሰጣችሁ በዚች ምድር ይቀመጡ፤ እናንተ፥ ጽኑዓን ሁሉ ግን ታጥቃችሁ በወንድሞቻችሁ ፊት ዮርዳኖስን ተሻገሩ፤ ለእነርሱም ተዋጉላቸው።'),
  ('574d8dda-3bf9-55bd-ae8b-d4c9310b63e2', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 15, 15, 'አምላካችን እግዚአብሔር እንደ እናንተ ወንድሞቻችሁን እስኪያሳርፍ ድረስ፥ እነርሱም ደግሞ አምላካችን እግዚአብሔር የሚሰጣቸውን ምድር እስኪወርሱ ድረስ፤ ከዚያም በኋላ ከእናንተ እያንዳንዱ የእግዚአብሔር አገልጋይ ሙሴ በፀሐይ መውጫ በዮርዳኖስ ማዶ ወደ ሰጣችሁ ወደ ርስታችሁ ምድር ትገባላችሁ፤ ትወርሱአትማላችሁ።”'),
  ('fcaf6075-ff27-515b-aea3-8b0e8b4f41c9', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 16, 16, 'እነርሱም ለኢያሱ እንዲህ ብለው መለሱለት፥ “ያዘዝኸንን ነገር ሁሉ እናደርጋለን ወደምትልከንም ስፍራ እንሄዳለን።'),
  ('5b229113-3d10-525f-a0cc-b8638ecba14e', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 17, 17, 'በሁሉም ለሙሴ እንደ ታዘዝን እንዲሁ ለአንተ ደግሞ እንታዘዛለን፤ ብቻ አምላክህ እግዚአብሔር ከሙሴ ጋር እንደ ነበረ ከአንተ ጋር ይሁን።'),
  ('470b57f4-b0c4-5249-acc4-86e4b31ad416', '0f103c5b-9644-55ad-a35e-5660eddf116f', '1501c41f-991f-5b03-a6ce-a5b88dc500c7', 18, 18, 'ለአንተ የማይታዘዝ፥ የምታዝዘውንም ቃል የማይሰማ ሁሉ፥ እርሱ ይገደል፤ አሁንም ጽና፥ በርታ።”'),
  ('a6477b64-2aad-525a-a2ae-fca03f99ee7c', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 1, 1, 'የነዌም ልጅ ኢያሱ፥ “ውጡና ምድሪቱን ኢያሪኮን እዩ” ብሎ ከሰጢም ሁለት ጐልማሶች ሰላዮችን በስውር ላከ። እነዚያም ሁለት ጐልማሶች ሄዱ፤ ወደ ኢያሪኮም ደረሱ፤ ረዓብ ወደሚሉአትም ዘማ ቤት ገቡ፤ በዚያም ዐደሩ።'),
  ('5ddd26fc-2867-5e23-aa1b-9f11381194a2', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 2, 2, 'ለኢያሪኮም ንጉሥ፥ “እነሆ፥ ከእስራኤል ልጆች ሰላዮች ሀገራችንን ሊሰልሉ ወደዚህ በሌሊት ገቡ” ብለው ነገሩት።'),
  ('6fa0dd9c-687e-557c-a8da-28005bf5acc7', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 3, 3, 'የኢያሪኮም ንጉሥ፥ “ሀገራችንን ሁሉ ሊሰልሉ መጥተዋልና ወደ አንቺ የመጡትን በዚችም ሌሊት ወደ ቤትሽ የገቡትን ሰዎች አውጪ በሉአት” ብሎ ወደ ረዓብ ላከ።'),
  ('0831c45c-562c-51d1-a085-7ea6e26fed2b', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 4, 4, 'ሴቲቱም ሁለቱን ሰዎች ወስዳ ሸሸገቻቸው፤ እርስዋም፥ “አዎን፥ ሰዎቹ ወደ እኔ መጡ፤ ከወዴት እንደ ሆኑ ግን አላወቅሁም፤'),
  ('d46769bd-b5f3-593d-ad73-fe75a72e0ac2', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 5, 5, 'በሩም ሲዘጋ፥ ሲጨልምም ሰዎቹ ወጡ፤ ወዴት እንደ ሄዱ አላውቅም፤ ፈጥናችሁ ተከተሉአቸው፤ ምንአልባት ታገኙአቸው ይሆናል” አለቻቸው።'),
  ('7bfcb593-05e7-5908-a470-671a9cd27885', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 6, 6, 'እርስዋ ግን ወደ ሰገነቱ አውጥታ በተከመረ እንጨት መካከል በቀርከሃ ጠቅልላ ደብቃቸው ነበር።'),
  ('58eb504f-2e74-58bb-a047-1aac4371aeba', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 7, 7, 'ሰዎቹም ወደ ዮርዳኖስ መሻገሪያ በሚወስደው መንገድ ተከተሉአቸው፤ በሩም ተቈለፈ።'),
  ('a985575f-47cd-5e14-a1ee-0691aeba0177', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 8, 8, 'እነዚህም ሳይተኙ ሴቲቱ ወደ እነርሱ ወደ ሰገነቱ ወጣች።'),
  ('253f07ab-0a64-57f4-a98c-56e17b06571f', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 9, 9, 'ሰዎቹንም እንዲህ አለቻቸው፥ “እግዚአብሔር ምድሪቱን አሳልፎ እንደ ሰጣችሁ ዐወቅሁ፤ እግዚአብሔር እናንተን መፍራትን በላያችን አምጥትዋልና፥ በምድሪቱም የሚኖሩት ሁሉ ከፊታችሁ የተነሣ ቀልጠዋልና።'),
  ('daaa3060-0d00-524b-a695-09d58a2a21f8', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 10, 10, 'ከግብፅ ምድር በወጣችሁ ጊዜ እግዚአብሔር የኤርትራን ባሕር በፊታችሁ እንዳደረቀ፥ በዮርዳኖስም ማዶ በነበሩት፥ እናንተም ፈጽማችሁ ባጠፋችኋቸው በሁለቱ በአሞራውያን ነገሥታት፥ በሴዎንና በዐግ ያደረጋችሁትን ሰምተናል።'),
  ('fd9167ff-ebb5-51de-a310-a4d3499d8153', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 11, 11, 'ይህንም ነገር ሰምተን በልባችን ደነገጥን፤ አምላካችሁም እግዚአብሔር በላይ በሰማይ፥ በታችም በምድር እርሱ አምላክ ነውና ከእናንተ የተነሣ ከእኛ የአንዱም እንኳን ነፍስ አልቀረም።'),
  ('0891e334-e351-55a9-abca-49bd89ba20f7', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 12, 12, 'አሁንም፥ በእግዚአብሔር ማሉልኝ፤ እኔ ለእናንተ ቸርነት እንደ አደረግሁ እናንተ ደግሞ ለአባቴ ቤት ቸርነት እንድታደርጉ፥ በእውነት ምልክት ስጡኝ።'),
  ('16f7b348-a5ea-5db4-adf5-8813aa0c31cc', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 13, 13, 'የአባቴን ቤት፥ እናቴንም፥ ወንድሞቼንና ቤቴንም ሁሉ፥ ያላቸውንም ሁሉ አድኑ፤ ሰውነታችንንም ከሞት አድኑ።”'),
  ('4d8e89fc-f1f7-5d53-a2d2-eb67e1c98efa', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 14, 14, 'ሰዎቹም፥ “ሕይወታችንን ስለ እናንተ አሳልፈን ለሞት እንሰጣለን” አሉ፤ እርስዋም አለች፥ “እግዚአብሔር ምድሪቱን በሰጣችሁ ጊዜ ቸርነትንና ጽድቅን ታደርጉልናላችሁ።” ሰዎቹም፥ “ይህን ነገራችንን ባትገልጪ እግዚአብሔር ሀገራችሁን በእውነት አሳልፎ ከሰጠን ከአንቺ ጋር ቸርነትን እናደርጋለን” አሏት።'),
  ('11a47bd9-166f-546a-a97d-c9f8f6e3bccc', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 15, 15, 'ቤቷም በከተማ ቅጥር የተጠጋ ነበረና፥ እርስዋም በቅጥሩ ላይ ተቀምጣ ነበርና በመስኮቱ በገመድ አወረደቻቸው።'),
  ('886c9d40-ce60-5a41-acc6-fc1bad460085', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 16, 16, 'እርስዋም፥ “የሚከተሉአችሁ እንዳያገኙአችሁ ወደ ተራራው ሂዱ፤ የሚከተሉአችሁም እስከሚመለሱ ድረስ በዚያ ሦስት ቀን ተሰውራችሁ ተቀመጡ፤ በኋላም መንገዳችሁን ትሄዳላችሁ” አለቻቸው።'),
  ('485c2e3c-e82f-55ad-a4d8-24bbaf2a0a94', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 17, 17, 'ሰዎቹም አሉአት፥ “እኛ ከዚህ ካማልሽን መሐላ ንጹሓን እንሆናለን።'),
  ('434e3c5b-c2a3-5be1-ab22-ed11c214b3ee', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 18, 18, 'እነሆ፥ እኛ ወደ ሀገሩ በገባን ጊዜ ይህን ቀይ ፈትል እኛን ባወረድሽበት መስኮት በኩል እሰሪው፤ አባትሽንም፥ እናትሽንም፥ ወንድሞችሽንም፥ የአባትሽንም ቤተ ሰብ ሁሉ ወደ አንቺ ወደ ቤትሽ ሰብስቢ።'),
  ('acbd68de-41a6-5ab6-a6e2-29261c6ba7db', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 19, 19, 'ከቤትሽም ደጅ ወደ ሜዳ የሚወጣ ሁሉ ደሙ በራሱ ላይ ይሆናል፤ እኛም ከዚህ ካማልሽን መሐላ ንጹሓን እንሆናለን፤ ነገር ግን ከአንቺ ጋር በቤትሽ ውስጥ ያለ ቢሞት ደሙ በእኛ ላይ ነው።'),
  ('ceb2391f-1909-5ce5-ae30-bc084aafdb81', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 20, 20, 'ነገር ግን ይህን ነገራችንን ብትገልጪ ከዚህ ካማልሽን መሐላ ንጹሓን እንሆናለን።”'),
  ('702da4eb-c194-5ceb-a0bd-d92cb8496463', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 21, 21, 'እርስዋም፥ “እንደ ቃላችሁ ይሁን” አለች፤ አሰናበተቻቸውም፤ እነርሱም ሄዱ፤ ቀዩንም ፈትል በመስኮቱ በኩል አንጠለጠለችው።'),
  ('633bffdb-dde4-512f-a9b3-f1c5805ffee4', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 22, 22, 'እነርሱም ወጥተው ወደ ተራራው ሄዱ፤ የሚከተሉአቸውና የሚፈልጉአቸውም እስኪመለሱ ሦስት ቀን በዚያ ተቀመጡ፤ በመንገዱም አላገኙአቸውም።'),
  ('07bd4e7d-c569-5f76-a10c-977ba2533a14', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 23, 23, 'ሁለቱም ጐልማሶች ተመለሱ፤ ከተራራውም ወርደው ተሻገሩ፤ ወደ ነዌም ልጅ ወደ ኢያሱ መጡ፤ የደረሰባቸውንም ሁሉ አወሩለት።'),
  ('79bb0dd1-1c87-5561-a840-ee8f0281967a', '5f57c3b8-545a-526f-aebf-00b6b5d7e0f5', 'b3c84888-5085-539e-ae78-0e0b596a3c80', 24, 24, 'ኢያሱንም፥ “በእውነት እግዚአብሔር ሀገሩን ሁሉ በእጃችን አሳልፎ ሰጥቶአል፤ በዚያች ምድር የሚኖሩ አሕዛብ ሁሉ ከእኛ የተነሣ ደነገጡ” አሉት።'),
  ('c53f6998-a454-5d07-a939-396abe71b552', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 1, 1, 'ኢያሱም ማልዶ ተነሣ፤ እርሱና እስራኤልም ሁሉ ከሰጢም ተጕዘው ወደ ዮርዳኖስ መጡ፤ ሳይሻገሩም በዚያ አደሩ።'),
  ('f1aae744-7637-56e0-ad1e-9e9e0208b305', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 2, 2, 'ከሦስት ቀንም በኋላ ጸሓፊዎች በሰፈሩ መካከል ገቡ።'),
  ('103091b1-e40b-5639-adaf-cc7dc8083cb6', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 3, 3, 'ለሕዝቡም እንዲህ ብለው ዐወጁ፥ “የአምላካችሁን የእግዚአብሔርን የቃል ኪዳኑን ታቦት ሌዋውያንና ካህናት ተሸክመውት ባያችሁ ጊዜ፥ ከሰፈራችሁ ተነሥታችሁ ተከተሉት።'),
  ('0ada54b5-2e0b-5e0e-aa1a-dc61035fe7e6', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 4, 4, 'በእናንተና በታቦቱ መካከል ያለው ርቀት በስፍር ሁለት ሺህ ክንድ ያህል ይሁን፤ በዚህ መንገድ በፊት አልሄዳችሁበትምና የምትሄዱበትን መንገድ እንድታውቁ ወደ ታቦቱ አትቅረቡ።”'),
  ('382c2665-37fa-5718-a68b-440d42d73134', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 5, 5, 'ኢያሱም ሕዝቡን፥ “ነገ እግዚአብሔር በመካከላችሁ ድንቅ ነገር ያደርጋልና ራሳችሁን አንጹ” አለ።'),
  ('9a144029-6460-55da-aac3-da5f15205e06', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 6, 6, 'ኢያሱም ካህናቱን፥ “የእግዚአብሔርን የቃል ኪዳኑን ታቦት ተሸክማችሁ በሕዝቡ ፊት ሂዱ” ብሎ ተናገራቸው፤ ካህናቱም የእግዚአብሔርን የቃል ኪዳኑን ታቦት ተሸክመው በሕዝቡ ፊት ሄዱ።'),
  ('a932141d-725f-5614-a893-9e31c11f72f4', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 7, 7, 'እግዚአብሔርም ኢያሱን፥ “ከሙሴ ጋር እንደ ሆንሁ እንዲሁ ከአንተ ጋር መሆኔን ያውቁ ዘንድ በዚህ ቀን በእስራኤል ልጆች ሁሉ ፊት ከፍ ከፍ አደርግህ ዘንድ እጀምራለሁ።'),
  ('3f1792bc-da98-5466-ad1b-41815b70956e', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 8, 8, 'አሁንም አንተ የቃል ኪዳኑን ታቦት የሚሸከሙትን ካህናት በዮርዳኖስ ውኃ ዳር ስትደርሱ በዮርዳኖስ ውስጥ ቁሙ ብለህ እዘዝ” አለው።'),
  ('764cd674-3e8b-523c-a0ed-87f2d4b4ddba', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 9, 9, 'ኢያሱም ለእስራኤል ልጆች፥ “ወደዚህ ቀርባችሁ የአምላካችንን የእግዚአብሔርን ቃል ስሙ” አለ።'),
  ('b6b0afe3-6b23-518f-a57c-82132697a511', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 10, 10, 'ኢያሱም አለ፥ “ሕያው አምላክ በመካከላችሁ እንደ ሆነ፥ እርሱም ከፊታችሁ ከነዓናዊውን፥ ኬጤዎናዊውንም፥ ኤዌዎናዊውንም፥ ፌርዜዎናዊውንም፥ ጌርጌሴዎናዊውንም፥ አሞሬዎናዊውንም፥ ኢያቡሴዎናዊውንም ፈጽሞ እንዲያጠፋቸው በዚህ ታውቃላችሁ።'),
  ('08d7baba-afc4-5543-aac1-4c6d17e45de0', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 11, 11, 'እነሆ፥ የምድር ሁሉ ጌታ የእግዚአብሔር የቃል ኪዳኑ ታቦት በፊታችሁ ዮርዳኖስን ትሻገራለች።'),
  ('039f5825-1126-5809-ac72-17e1bfb702a6', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 12, 12, 'አሁንም ከእስራኤል ነገዶች ዐሥራ ሁለት ሰዎችን ምረጡ፤ ከየነገዱ አንድ አንድ ሰው ይሁን።'),
  ('33b93ea2-e0ff-5c4b-a021-995b09d6d5e2', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 13, 13, 'እንዲህም ይሆናል፤ የምድርን ሁሉ ጌታ የእግዚአብሔርን ታቦት የተሸከሙ ካህናት እግር ጫማ በዮርዳኖስ ውኃ ውስጥ ሲቆም፥ የዮርዳኖስ ውኃ ይደርቃል፤ ከላይ የሚወርደውም ውኃ ይቆማል።”'),
  ('afc1ee5a-c283-51a8-a1b9-701defe0502e', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 14, 14, 'እንዲህም ሆነ፤ ሕዝቡ ዮርዳኖስን ሊሻገሩ ከየድንኳናቸው በወጡ ጊዜ፥ የቃል ኪዳኑን ታቦት የተሸከሙ ካህናት በሕዝቡ ፊት ይሄዱ ነበር።'),
  ('dafdbf34-069f-55a7-a2c7-a1df55908a98', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 15, 15, 'እንደ ክረምትና እንደ መከር ወራት ሁሉ ዮርዳኖስ እስከ ወሰኑ ሞልቶ ነበርና የእግዚአብሔርን የቃል ኪዳን ታቦት ተሸካሚዎቹ ወደ ዮርዳኖስ በገቡ ጊዜ፥ ታቦቱን የተሸከሙት የካህናቱ እግሮች በውኃዉ ዳር ሲጠልቁ፥'),
  ('3f76cd8c-c19d-5006-afa9-ae8d724a7fb1', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 16, 16, 'ከላይ የሚወርደው ውኃ ቆመ፤ እስከ ቀርያትያርም አውራጃ እጅግ ርቆ እንደ ግድግዳ ቆመ፤ ወደ ዓረባ ባሕር ወደ ጨው ባሕር የሚወርደው ውኃም ፈጽሞ ደረቀ፤ ሕዝቡም በኢያሪኮ ፊት ለፊት ቆሙ።'),
  ('3f1efcfa-8396-5ff0-a460-912e3ba44ecb', 'd936c410-e839-58ad-ad7f-d56a577bae21', 'fdf1f2f7-88ae-51e0-ab4f-6a9698443be3', 17, 17, 'የእግዚአብሔርንም የቃል ኪዳኑን ታቦት የተሸከሙ ካህናት በዮርዳኖስ መካከል በደረቅ መሬት ጸንተው ቆመው ነበር፤ ሕዝቡም ሁሉ ዮርዳኖስን ፈጽመው እስኪሻገሩ ድረስ የእስራኤል ልጆች ሁሉ በደረቅ መሬት ተሻገሩ።'),
  ('ca78dfec-013c-543f-a568-a0c9d878bf9d', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 1, 1, 'እንዲህም ሆነ፤ ሕዝቡ ሁሉ ዮርዳኖስን ፈጽመው በተሻገሩ ጊዜ እግዚአብሔር ኢያሱን እንዲህ ብሎ ተናገረው፦'),
  ('0b9932bd-d4d9-5ab6-aab1-dfc7eea140dc', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 2, 2, '“ከሕዝቡ ከየነገዱ አንድ አንድ ሰው፥ ዐሥራ ሁለት ሰዎችን ውሰድ፦'),
  ('1b0cec9b-c747-5c3b-a342-f645b53df817', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 3, 3, 'በዮርዳኖስ መካከል የካህናት እግር ከቆመበት ስፍራ ዐሥራ ሁለት ቀላል ድንጋዮችን እንዲያነሡ እዘዛቸው፤ ከእናንተም ጋር ውሰዱአቸው፤ ከዚያም ሌሊት በምታድሩበት ቦታ በየነገዳችሁ ጠብቋቸው።”'),
  ('9faa7911-f402-5d2b-ac5d-6236f03029ac', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 4, 4, 'ኢያሱም ከየነገዱ አንድ አንድ ሰው፥ ከእስራኤል ልጆች የታወቁትን ዐሥራ ሁለት ሰዎች ጠራ።'),
  ('3561e0e4-32ff-5f6d-aae3-ed1dbb72c696', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 5, 5, 'ኢያሱም አላቸው፥ “በእኔና በእግዚአብሔር ፊት ወደ ዮርዳኖስ መካከል ዕለፉ፤ እያንዳንዱ ሰው በዐሥራ ሁለቱ ነገደ እስራኤል ቍጥር በትከሻው ላይ አንድ አንድ ድንጋይ ከዚያ ይሸከም።'),
  ('30cb36bb-b705-5779-a7c3-e2351f9ab6b6', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 6, 6, 'እነዚህም ምልክት ይሆኑላችኋል፤ ልጅህ ነገ፦ ‘እነዚህ ድንጋዮች ምንድን ናቸው?’ ብሎ በጠየቀህ ጊዜ፥ ልጅህን እንዲህ ትለዋለህ፦'),
  ('4043d509-1105-5990-a950-2fb3aeb3bdc7', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 7, 7, 'አንተ በምድር ሁሉ ጌታ በእግዚአብሔር ቃል ኪዳን ታቦት ፊት ስንሻገር የዮርዳኖስ ወንዝ ስለ ደረቀ ነው፤ እነዚህ ድንጋዮችም ለእስራኤል ልጆች ለዘለዓለም መታሰቢያ ይሆናሉ።”'),
  ('512d2e35-291f-5cb7-ac78-6896a3a4fa65', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 8, 8, 'የእስራኤልም ልጆች ኢያሱ እንዳዘዛቸው እንዲሁ አደረጉ፤ የእስራኤልም ልጆች ዮርዳኖስን አካትተው በተሻገሩ ጊዜ እግዚአብሔር ኢያሱን እንደ አዘዘው በእስራኤል ነገድ ቍጥር ከዮርዳኖስ መካከል ዐሥራ ሁለት ድንጋዮች አንሥተው ወደ ሰፈራቸው ወሰዱ፤ በዚያም አኖሩአቸው።'),
  ('92bb9bb1-144f-5389-a8e0-e1b086ecb247', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 9, 9, 'ኢያሱም የቃል ኪዳኑን ታቦት የተሸከሙ ካህናት እግሮች በቆሙበት ስፍራ በዮርዳኖስ መካከል ሌሎች ዐሥራ ሁለት ድንጋዮችን አቆመ፤ እስከ ዛሬም ድረስ በዚያ አሉ።'),
  ('7c31b9de-1405-51a0-a983-d63469938376', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 10, 10, 'ኢያሱም ለሕዝቡ እንዲነግር፥ እግዚአብሔር ያዘዘውን ሁሉ እስኪፈጽም ድረስ የቃል ኪዳኑን ታቦት የተሸከሙ ካህናት በዮርዳኖስ መካከል ቆመው ነበር፤ ሕዝቡም ፈጥነው ተሻገሩ።'),
  ('73e14bbc-12be-5de0-a0fd-d8df5a2e176c', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 11, 11, 'ሕዝቡም ሁሉ አካትተው በተሻገሩ ጊዜ ታቦተ ሕጉ ተሻገረች፤ እነዚያም ድንጋዮች በፊታቸው ተሻገሩ።'),
  ('c454d8a5-dcbd-59e4-aad9-881af9f53003', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 12, 12, 'ሙሴም እንዳዘዛቸው የሮቤል ልጆች፥ የጋድም ልጆች፥ የምናሴም ነገድ እኩሌታ ታጥቀው በእስራኤል ልጆች ፊት ተሻገሩ።'),
  ('6d46a4cb-6546-59b3-ab2b-36ef55adf8e0', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 13, 13, 'አርባ ሺህ ያህል ለጦርነት የታጠቁ ሰዎች የኢያሪኮን ሀገር ይወጉ ዘንድ በእግዚአብሔር ፊት ተሻገሩ።'),
  ('575c7a5a-c260-543b-ac53-b29c30bf35b3', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 14, 14, 'በዚያም ቀን እግዚአብሔር ኢያሱን በእስራኤል ልጆች ሁሉ ፊት ከፍ አደረገው፤ ሙሴንም እንደ ፈሩ በዕድሜው ሁሉ ፈሩት።'),
  ('98808daf-6961-5615-aba9-e58b68c2d6d9', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 15, 15, 'እግዚአብሔርም ኢያሱን እንዲህ ብሎ ተናገረው፦'),
  ('e19bc592-9d4d-51f5-a019-bb3b8318ceb2', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 16, 16, '“የቃል ኪዳኑን ታቦት የሚሸከሙትን ካህናት ከዮርዳኖስ እንዲወጡ እዘዛቸው።”'),
  ('14fc6743-f659-5510-adfa-6d1136d53a3e', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 17, 17, 'ኢያሱም ካህናቱን፥ “ከዮርዳኖስ ውጡ” ብሎ አዘዛቸው።'),
  ('96692311-15d6-5c84-af57-aae2146b5b10', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 18, 18, 'የእግዚአብሔርንም የቃል ኪዳን ታቦተ ሕግ የተሸከሙ ካህናት ከዮርዳኖስ መካከል በወጡ ጊዜ፥ በእግራቸውም የብስ በረገጡ ጊዜ፥ የዮርዳኖስ ውኃ ተወርውሮ ወደ ስፍራው ተመለሰ፤ ቀድሞም እንደ ነበረ ሂዶ ዳር እስከ ዳር ሞላ።'),
  ('6a6b2844-c7d4-50b5-a29a-8d1a0596ba94', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 19, 19, 'ሕዝቡም በመጀመሪያው ወር በዐሥረኛው ቀን ከዮርዳኖስ ወጡ፤ በኢያሪኮም በምሥራቅ በኩል በጌልገላ ሰፈሩ።'),
  ('3b223c76-f184-504c-adb6-21ef138980d8', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 20, 20, 'ኢያሱም ከዮርዳኖስ ውስጥ የወሰዱአቸውን እነዚያን ዐሥራ ሁለቱን ድንጋዮች በጌልገላ አቆማቸው።'),
  ('2f6d9adb-ac7e-5b75-ab41-0ed4a8759955', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 21, 21, 'ኢያሱም ለእስራኤል ልጆች እንዲህ ብሎ ተናገራቸው፥ “ልጆቻችሁ፦ ‘እነዚህ ድንጋዮች ምንድን ናቸው?’ ብለው በሚጠይቋችሁ ጊዜ፥'),
  ('1da80bab-00ce-530f-a582-3999fa63d575', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 22, 22, 'ለልጆቻችሁ እንዲህ ብላችሁ ትነግሯቸዋላችሁ፦ ‘እስራኤል ይህን ዮርዳኖስን በደረቅ ተሻገረ፤’'),
  ('3aaf2c0d-a29b-5324-a18d-fd861fa2d522', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 23, 23, 'እስክናልፍ ድረስ አምላካችን እግዚአብሔር የኤርትራን ባሕር ከፊታችን እንዳደረቀ እንዲሁ እስክንሻገር ድረስ አምላካችን እግዚአብሔር የዮርዳኖስን ውኃ ከፊታችን አደረቀ።'),
  ('3101cb3f-05a2-5f5e-a45b-5ff9588944c1', '65095213-2212-5367-a101-4b2ac6731a0b', '1dca219b-127c-57f4-acf4-87cf8bc064b5', 24, 24, 'ይኸውም የእግዚአብሔር ኀይል ጠንካራ እንደ ሆነች የምድር አሕዛብ ሁሉ እንዲያውቁ፥ አምላካችሁንም እግዚአብሔርን በሥራው ሁሉ እንድትፈሩ ነው።”'),
  ('89f76484-da0f-5e46-ad87-ebde8c1c10c3', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '91b3c7e3-a95b-5455-a6ba-6ae33b83432f', 1, 1, 'እንዲህም ሆነ፤ በዮርዳኖስ ማዶ በባሕር በኩል የነበሩት የአሞራውያን ነገሥት ሁሉ፥ በባሕሩም አጠገብ የነበሩ የፊኒቃውያን ነገሥት ሁሉ፥ እግዚአብሔር ከእስራኤል ልጆች ፊት የዮርዳኖስን ውኃ እስኪሻገሩ ድረስ እንዳደረቀ በሰሙ ጊዜ፥ ልባቸው ቀለጠ፤ ከእስራኤልም ልጆች የተነሣ አእምሮአቸውን ሳቱ።'),
  ('eea83583-ea4b-5587-a266-ef96b4be5480', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 1, 2, 'በዚያን ጊዜም እግዚአብሔር ኢያሱን፥ “ከሻፎ ድንጋይ የባልጩት መቍረጫ ሠርተህ የእስራኤልን ልጆች ዳግመኛ ግረዛቸው” አለው።'),
  ('df641abf-e8a5-5ddd-ac3a-7df6c0d29377', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 2, 3, 'ኢያሱም የባልጩት መቍረጫ ሠርቶ የግርዛት ኮረብታ በተባለ ስፍራ የእስራኤልን ልጆች ገረዘ።'),
  ('618912d4-053b-58b0-accd-b21d97f0d347', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 3, 4, 'ኢያሱ ሕዝቡን ሁሉ የገረዘበት ምክንያት ይህ ነው፤ ከግብፅ የወጡ ወንዶች ተዋጊዎች ሁሉ ከግብፅ ከወጡ በኋላ በመንገድ ላይ በምድረ በዳ ሞቱ፤ የወጡትም ወንዶች ሁሉ ተገርዘው ነበር።'),
  ('746f5177-618d-5dcb-a5fc-e48d873afae2', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 4, 5, 'ነገር ግን ከግብፅ ከወጡ በኋላ በመንገድ፥ በምድረ በዳ የተወለዱ ሕዝብ ሁሉ አልተገረዙም ነበርና፥ ኢያሱ እነዚህን ሁሉ ገረዛቸው።'),
  ('5e3facb7-26c3-51bb-aedb-63a8d1a533e7', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 5, 6, 'እግዚአብሔርም ወተትና ማር የምታፈስሰውን ምድር ለእኛ ይሰጠን ዘንድ ለአባቶቻችን የማለላቸውን ምድር እንደማያሳያቸው የማለባቸውን፥ ከግብፅ የወጡ የእግዚአብሔርንም ቃል ያልሰሙ፥ እነዚያ ተዋጊዎች ሁሉ እስኪጠፉ ድረስ የእስራኤል ልጆች አርባ ዓመት በመድበራ ምድረ በዳ ይዞሩ ነበር።'),
  ('f18a09ba-7d14-5d77-ac10-591939952967', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 6, 7, 'ልጆቻቸውን በእነርሱ ፋንታ አስነሣ፤ እነዚህንም ኢያሱ ገረዛቸው፤ በመንገድ ስለተወለዱ አልተገረዙም ነበርና።'),
  ('be50d6b4-68f7-5237-ad38-ab0411550ffd', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 7, 8, 'በተገረዙም ጊዜ እስኪድኑ ድረስ በሰፈር ውስጥ ተቀመጡ።'),
  ('6559a115-7a6f-5281-a47a-dfbd651840a9', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 8, 9, 'እግዚአብሔርም ኢያሱን፥ “ዛሬ የግብፅን ተግዳሮት ከእናንተ ላይ አስወግጃለሁ” አለው፤ ስለዚህ የዚያ ስፍራ ስም እስከ ዛሬ ድረስ ጌልገላ ተብሎ ተጠራ።'),
  ('52d920d3-08ac-55c5-ad6a-33be1f48a245', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 9, 10, 'የእስራኤልም ልጆች በጌልገላ ሰፈሩ፤ ከወሩም በዐሥራ አራተኛው ቀን በመሸ ጊዜ በዮርዳኖስ ማዶ በኢያሪኮ ምዕራብ ፋሲካን አደረጉ።'),
  ('a1ee7868-60ab-5d9e-a261-9e88106abf17', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 10, 11, 'ከምድሪቱም ፍሬ ቂጣና አዲስ እህል በዚያው ቀን በሉ።'),
  ('db7ceb76-5a23-5c2e-a213-bb4e08098c60', '87029c2f-d894-5a4f-a877-93bc0e8daccd', '34dec7a8-5de4-5a39-a677-4c57bea48b13', 11, 12, 'በነጋውም ከምድሪቱ ፍሬ ከበሉ በኋላ መናው ቀረ፤ ከዚያም በኋላ የእስራኤል ልጆች ዳግመኛ መና አላገኙም፤ በዚያው ዓመት የፊኒቆንን ምድር ፍሬ ሰበሰቡ።'),
  ('c4aa49f4-c3a9-5c0f-a2b4-366171cd574c', '87029c2f-d894-5a4f-a877-93bc0e8daccd', 'd0679aa0-a66b-5e77-a1f3-0160d18df32c', 1, 13, 'እንዲህም ሆነ፤ ኢያሱ በኢያሪኮ አጠገብ ሳለ ዐይኑን አንሥቶ ተመለከተ፤ እነሆም፥ የተመዘዘ ሰይፍ በእጁ የያዘ ሰው በፊቱ ቆሞ አየ፤ ኢያሱም ወደ እርሱ ቀርቦ፥ “ከእኛ ወገን ወይስ ከጠላቶቻችን ወገን ነህ?” አለው።'),
  ('20c6cb9e-5f5a-5b35-a48b-66fb2dcfe89a', '87029c2f-d894-5a4f-a877-93bc0e8daccd', 'd0679aa0-a66b-5e77-a1f3-0160d18df32c', 2, 14, 'እርሱም፥ “እኔ የእግዚአብሔር ሠራዊት አለቃ ነኝ፤ አሁንም ወደ አንተ መጥቼአለሁ” አለ። ኢያሱም ወደ ምድር በግምባሩ ተደፍቶ ሰገደና፥ “በባሪያህ ዘንድ ምን አቁሞሃል?” አለው።'),
  ('bffcf47d-b0dd-5c7e-a99e-a61f5ac6441d', '87029c2f-d894-5a4f-a877-93bc0e8daccd', 'd0679aa0-a66b-5e77-a1f3-0160d18df32c', 3, 15, 'የእግዚአብሔርም ሠራዊት አለቃ ኢያሱን፥ “አንተ የቆምህበት ስፍራ የተቀደሰ ነውና ጫማህን ከእግርህ አውልቅ” አለው። ኢያሱም እንዲሁ አደረገ።'),
  ('18427e83-5972-5c49-a3f8-317ea89882b8', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 1, 1, 'ኢያሪኮም በግንብ ታጥራ ተዘግታ ነበር፤ ወደ እርስዋ የሚገባ፥ ከእርስዋም የሚወጣ አልነበረም።'),
  ('539a3a2c-cb0f-52f9-ae97-8123d0dccc01', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 2, 2, 'እግዚአብሔርም ኢያሱን አለው፥ “እነሆ፥ ኢያሪኮንና ንጉሥዋን ጽኑዓን፥ ኀያላንዋንም በእጅህ ሰጥቼአለሁ።'),
  ('d018c9e5-07d9-5d59-aa04-e2bb3f50de2b', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 3, 3, 'አንተም ተዋጊዎችን ሁሉ በዙሪያው አሰልፋቸው። ተዋጊዎቻችሁም ሁሉ በከተማዪቱ ዙሪያ አንድ ጊዜ ይዙሩ፤ እንዲሁም ስድስት ቀን አድርጉ።'),
  ('c2e7c58d-8e5b-5320-acd1-7f64e0f21600', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 4, 4, 'ሰባትም ካህናት ሰባት ቀንደ መለከት በታቦቱ ፊት ይያዙ፤ በሰባተኛውም ቀን ከተማዪቱን ሰባት ጊዜ ዙሩ፤ ካህናቱም ቀንደ መለከቱን ይንፉ።'),
  ('81d37b14-6991-5fc4-a9c4-6f3a6ede47ac', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 5, 5, 'ቀንደ መለከቱም ባለማቋረጥ ሲነፋ፥ የመለከቱን ድምፅ ስትሰሙ፥ ሕዝቡ ሁሉ ታላቅ ጩኸት ይጩኹ፤ የከተማዪቱም ቅጥር ይወድቃል፤ ሕዝቡም ሁሉ እያንዳንዱ ፊት ለፊት እየሮጠ ይገባባታል።”'),
  ('affc85a9-25cd-5428-a7f3-7dd4dd75f693', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 6, 6, 'የነዌም ልጅ ኢያሱ ካህናቱን ጠርቶ፥ “የቃል ኪዳኑን ታቦት ተሸከሙ፤ ሰባትም ካህናት ሰባት ቀንደ መለከት ወስደው በእግዚአብሔር ታቦት ፊት ይሂዱ” አላቸው።'),
  ('24287c2a-0b98-5db8-a5f5-0636c2ab6e85', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 7, 7, 'ሕዝቡንም፥ “ሂዱ፤ ከተማዪቱንም ዙሩ፤ ተዋጊዎችም ከጦር መሣሪያዎቻቸው ጋር በእግዚአብሔር ታቦት ፊት ይሂዱ ብላችሁ እዘዙአቸው” አላቸው።'),
  ('35dd48dc-1872-5606-a814-23ecc9693487', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 8, 8, 'በእግዚአብሔርም ፊት ይሄዱ ዘንድ ኢያሱ እንደ ነገራቸው ሰባቱ ካህናት የተቀደሱ ሰባቱን ቀንደ መለከት ይዘው ሄዱ፤ በሄዱም ጊዜ አሰምተው በምልክት ነፉ፤ የእግዚአብሔርም የሕጉ ታቦት ትከተላቸው ነበር።'),
  ('b864a554-605b-59ca-a235-1eaaf5ff0fa5', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 9, 9, 'ሰልፈኞችም ፊት ፊት ይሄዱ ነበር፤ ካህናቱም ነጋሪት ይመቱ ነበር፤ ከታቦቱ በኋላ ይከተሉ የነበሩትም ቀንደ መለከቱን እየነፉ ይሄዱ ነበር።'),
  ('6521361a-4cee-5d44-ab00-f711ae606b4d', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 10, 10, 'ኢያሱም ሕዝቡን፦ እንዳይጮኹ ማንም ድምፃቸውን እንዳይሰማ፥ እንዲጮኹ እስኪያዛቸውም ድረስ ከአፋቸው ቃል እንዳይወጣ አዘዛቸው።'),
  ('8d4a2d34-8975-5e17-a612-611ae9fb3a80', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 11, 11, 'የእግዚአብሔርም የቃል ኪዳኑ ታቦት ሄደች፤ ከተማዪቱንም ዞረች፤ ወደ ሰፈርም ተመልሳ በዚያ አደረች።'),
  ('8f7f57e2-513a-5efe-ad64-024fd2bb4400', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 12, 12, 'ኢያሱም በማግሥቱ ማለዳ ተነሣ፤ ካህናቱም የእግዚአብሔርን የሕጉን ታቦት ተሸከሙ።'),
  ('03ff925e-446a-53d2-a2c1-b3ca82f8f89b', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 13, 13, 'ሰባቱም ካህናት ሰባቱን ቀንደ መለከት ይዘው በእግዚአብሔር ታቦት ፊት ይሄዱ ነበር፤ ቀንደ መለከቱንም ይነፉ ነበር፤ ተዋጊዎችም በፊታቸው ይሄዱ ነበር፤ የቀሩትም ሕዝብ ከእግዚአብሔር የቃል ኪዳን ታቦት በኋላ ይሄዱ ነበር፤ ካህናቱም ቀንደ መለከቱን ይነፉ ነበር።'),
  ('4d6b9af4-8927-510b-a546-7e72c689b441', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 14, 14, 'በሁለተኛውም ቀን የቀረው ሕዝብ ሁሉ ከተማዪቱን አንድ ጊዜ ዞረው ወደ ሰፈር ተመለሱ፤ ስድስት ቀንም እንዲህ አደረጉ።'),
  ('d910ab86-d93a-5990-aac0-5aabd2f5c49b', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 15, 15, 'በሰባተኛውም ቀን በነጋ ጊዜ ማልደው ተነሡ፤ እንደዚህም ከተማዪቱን ሰባት ጊዜ ዞሩ፤ በዚያም ቀን ብቻ ከተማዪቱን ሰባት ጊዜ ዞሩ።'),
  ('6bef8d3f-8f6c-52c2-a663-c6e8b13f76fc', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 16, 16, 'እንዲህም ሆነ፤ ከተማዪቱን ሰባት ጊዜ በዞሩና ካህናቱ ቀንደ መለከቱን በነፉ ጊዜ፤ ኢያሱ ለእስራኤል ልጆች አለ፥ “እግዚአብሔር ከተማዪቱን ሰጥቶአችኋልና ጩኹ።'),
  ('7ab96910-0967-5959-a5d3-35ae6d96b705', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 17, 17, 'ከተማዪቱም በእርስዋም ያለው ሁሉ ለሠራዊት ጌታ ለእግዚአብሔር እርም ይሆናሉ፤ የላክናቸውን መልእክተኞች ስለ ሸሸገች ዘማዊቱ ረዓብ፥ ከእርስዋም ጋር በቤቷ ውስጥ ያሉ ሁሉ ብቻ በሕይወት ይኖራሉ።'),
  ('ee826618-49d4-546f-a1fe-e4ab12f96a60', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 18, 18, 'እናንተ ግን እርም ብለን ከተውነው እንዳትወስዱ ተጠንቀቁ፤ ከእርሱም ተመኝታችሁ አትውሰዱ፤ ብትወስዱ ግን የእስራኤልን ሰፈር የተረገመች ታደርጓታላችሁ፤ እኛንም ታጠፉናላችሁ።'),
  ('a06af948-0930-5e5f-a71b-bd85b959a37a', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 19, 19, 'ነገር ግን ብርና ወርቅ ሁሉ፥ የናስና የብረትም ዕቃ ለእግዚአብሔር የተቀደሰ ይሁን፤ ወደ እግዚአብሔርም ግምጃ ቤት ይግባ።”'),
  ('d7b88ee4-4605-5c5e-a69c-8c02c7eedacf', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 20, 20, 'ሕዝቡም ጮኹ፥ ካህናቱም ቀንደ መለከቱን ነፉ፤ ሕዝቡም የቀንደ መለከቱን ድምፅ በሰሙ ጊዜ ታላቅ ጩኸት ጮኹ፤ ቅጥሩም ወደቀ፤ ሕዝቡም ሁሉ ወደ ከተማዪቱ ገቡ፤ ሁሉም ወደ ፊታቸው ወደ ከተማዪቱ ሮጡ፤ ከተማዪቱንም እጅ አደረጉ።'),
  ('b82e5d6f-89f6-58e5-a26f-0f7a28b1e7c4', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 21, 21, 'ኢያሱም ከተማዋን፥ በከተማዪቱም ውስጥ የነበሩትን ሁሉ፥ ከወንድ እስከ ሴት፥ ከሕፃን እስከ ሽማግሌ፥ ከበሬ እስከ በግና እስከ አህያ በሰይፍ ስለት ፈጽሞ አጠፋ።'),
  ('7b002d9a-2a1a-5bf4-a972-683a41191735', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 22, 22, 'ኢያሱም ምድሪቱን የሰለሉ ሁለቱን ሰዎች፥ “ወደ ዘማዪቱ ቤት ግቡ፤ ከዚያም ሴቲቱንና ያላትን ሁሉ እንደማላችሁላት አውጡ” አላቸው።'),
  ('3b6ecf02-7532-528f-a7fe-59f69d633bdd', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 23, 23, 'እነዚያም ከተማዪቱን የሰለሉ ሁለቱ ጐልማሶች ወደ ዘማዪቱ ረዓብ ቤት ገብተው ረዓብን፥ አባቷንና እናቷን፥ ወንድሞችዋንም፥ ያላትንም ሁሉ፥ ቤተ ዘመዶችዋንም ሁሉ አወጡአቸው፤ ከእስራኤልም ሰፈር በውጭ አስቀመጡአቸው።'),
  ('05697faa-9308-50e4-a1a0-8705f863bd09', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 24, 24, 'ከተማዪቱንም፥ በእርስዋም የነበረውን ሁሉ በእሳት አቃጠሉ፤ ነገር ግን ብሩንና ወርቁን፥ የናሱንና የብረቱንም ዕቃ በእግዚአብሔር ግምጃ ቤት ውስጥ አገቡ።'),
  ('6d9f8615-a5ab-5809-a61a-2db1ce57006a', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 25, 25, 'ኢያሪኮን ሊሰልሉ ኢያሱ የላካቸውንም መልእክተኞች ስለ ሸሸገች ዘማዊቱን ረዓብን፥ የአባቷንም ቤተ ሰብ፥ ያላትንም ሁሉ ኢያሱ አዳናቸው፤ እርስዋም በእስራኤል መካከል እስከ ዛሬ ድረስ ተቀምጣለች።'),
  ('01a8f0f7-e073-5a87-ae3f-0146f3bcd613', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 26, 26, 'በዚያችም ቀን ኢያሱ፥ “ይህችን ከተማ ኢያሪኮን ለመሥራት የሚነሣ ሰው በእግዚአብሔር ፊት ርጉም ይሁን፤ መሠረቷን በበኵር ልጁ የሚጥል፥ በሮችዋንም በታናሹ ልጁ የሚያቆም ርጉም ይሁን” ብሎ ማለ።'),
  ('4b296386-bbf1-57e9-a113-1adbb5e144f9', '464df088-4400-5529-a545-67a7cbcf40e3', '75c14a15-8c98-5b20-ab46-7de01d6d4ffb', 27, 27, 'እግዚአብሔርም ከኢያሱ ጋር ነበረ፤ ስሙም በምድር ሁሉ ላይ ደረሰ።'),
  ('caaaf000-d959-562d-aebb-e09124ca1981', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 1, 1, 'የእስራኤል ልጆች ግን እርም በሆነው ነገር ታላቅ በደል በደሉ፤ ከይሁዳ ነገድ የሆነ አካን፥ እርሱም የከርሚ ልጅ፥ የዘንበሪ ልጅ፥ የዛራ ልጅ እርም ከሆነው ነገር ወሰደ፤ እግዚአብሔርም በእስራኤል ልጆች ላይ ተቈጣ።'),
  ('055b72df-79e0-5656-a435-32dcad8d5b28', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 2, 2, 'ኢያሱም ከቤቴል በምሥራቅ በኩል በቤትአዊን አጠገብ ወዳለችው ወደ ጋይ ሰዎችን ከኢያሪኮ ልኮ፥ “ውጡ፤ ጋይንም ሰልሉ” ብሎ ተናገራቸው፤ ሰዎቹም ወጡ፤ ጋይንም ሰለሉ።'),
  ('a07a3ed2-4b0a-5fc4-ad85-4ce3868d9e13', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 3, 3, 'ወደ ኢያሱም ተመልሰው፥ “ሁለት ወይም ሦስት ሺህ ያህል ሰው ወጥተው ጋይን ይምቱ እንጂ ሕዝቡ ሁሉ አይውጣ፤ የእግዚአብሔርን ሕዝብ ሁሉ ግን ወደዚያ አትውሰድ፤ ጥቂቶች ናቸውና” አሉት።'),
  ('2cff9e6b-71c3-5f52-a55c-45deb343031c', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 4, 4, 'ሦስት ሺህ ያህል ሰዎችም ወደዚያ ወጡ፤ የጋይም ሰዎች አባረሩአቸው፤ ከፊታቸውም ሸሹ።'),
  ('916b7735-8847-51c3-aafd-668398901334', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 5, 5, 'የጋይ ሰዎችም ከእነርሱ ሠላሳ ስድስት ሰዎችን ገደሉ፤ ከበሩ ጀምረው እስከ አጠፉአቸው ድረስ አባረሩአቸው፤ በቍልቍለቱም ገደሉአቸው፤ የሕዝቡም ልብ ደነገጠ፤ እንደ ውኃም ሆነ።'),
  ('f389022f-75f5-5f4e-a084-bc1fee0e05c7', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 6, 6, 'ኢያሱም ልብሱን ቀደደ፤ እርሱና የእስራኤልም ሽማግሌዎች በእግዚአብሔር ታቦት ፊት እስከ ማታ ድረስ በግንባራቸው ተደፉ፤ በራሳቸውም ላይ ትቢያ ነሰነሱ።'),
  ('72fce4cf-c9f7-5c45-ad7a-4b67f6436995', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 7, 7, 'ኢያሱም አለ፥ “ወዮ! ጌታ እግዚአብሔር ሆይ! በአሞሬዎናውያን እጅ አሳልፈህ ትሰጠን፥ ታጠፋንም ዘንድ አገልጋይህ ይህን ሕዝብ ዮርዳኖስን ለምን አሻገረ? በዮርዳኖስ ማዶ ተቀምጠን በኖርን ነበር እኮ!'),
  ('abeaf92c-39e1-52e4-ae8d-41a034cdbbaf', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 8, 8, 'ጌታ ሆይ! እስራኤል ጀርባውን ወደ ጠላቶቹ ከመለሰ እንግዲህ ምን እላለሁ?'),
  ('273f3bf3-85c1-56d2-a398-00ee2e2c291b', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 9, 9, 'ከነዓናውያንም፥ በምድሪቱም የሚኖሩ ሁሉ ሰምተው ይከብቡናል፤ ከምድርም ያጠፉናል፤ ለታላቁ ስምህም የምታደርገው ምንድር ነው?”'),
  ('eb31512f-f974-556f-aa0e-871d21b47032', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 10, 10, 'እግዚአብሔርም ኢያሱን አለው፥ “ለምን በግንባርህ ተደፍተሃል? ተነሥ!'),
  ('71e0cedd-b32e-554d-aec0-03bc889e361e', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 11, 11, 'ሕዝቡ በድለዋል፤ ከእነርሱም ጋር የገባሁትን ቃል ኪዳኔን አፍርሰዋል፤ እርም ከሆነውም ነገር ሰርቀው ወሰዱ፤ በዕቃቸውም ውስጥ ሸሸጉት።'),
  ('cf309cae-3258-5b1f-ac8f-28d3cf40e46b', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 12, 12, 'ስለዚህም የእስራኤል ልጆች በጠላቶቻቸው ፊት መቆም አይችሉም፤ የተረገሙ ስለሆኑ በጠላቶቻቸው ፊት ይሸሻሉ፤ እርም የሆነውንም ነገር ከመካከላችሁ ካላጠፋችሁ ከዚህ በኋላ ከእናንተ ጋር አልሆንም።'),
  ('0507da81-0914-5015-a5a8-49b8e8a49bf4', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 13, 13, 'ተነሣና ሕዝቡን ቀድስ እንዲህም በላቸው፦ ‘እስራኤል ሆይ! እርም የሆነ ነገር በመካከልህ አለ፤ እርምም የሆነውን ነገር ከመካከላችሁ እስክታጠፉ ድረስ በጠላቶቻችሁ ፊት መቆም አትችሉም’ ብሎ የእስራኤል አምላክ እግዚአብሔር ተናግሮአልና እስከ ነገ ራሳችሁን አንጹ።'),
  ('1a9665d2-8754-56f4-a4ff-ccf731563bb5', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 14, 14, 'ነገም በየነገዳችሁ ትቀርባላችሁ፤ እግዚአብሔርም የሚለየው ነገድ በየወገኖቹ ይቀርባል፤ እግዚአብሔርም የሚለየው ወገን በየቤተ ሰቦቹ ይቀርባል፤ እግዚአብሔርም የሚለየው ቤተ ሰብ በየሰዉ ይቀርባል።'),
  ('9b1e25ca-8409-50dc-aa88-c5166bd86f8c', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 15, 15, 'ምልክት የታየበት ሰው የእግዚአብሔርን ቃል ኪዳን አፍርሶአልና፥ በእስራኤልም ዘንድ በደል አድርጎአልና፥ እርሱና ያለው ሁሉ በእሳት ይቃጠላሉ።”'),
  ('c24a6680-02b7-5ae7-ab72-2b93209f0ff5', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 16, 16, 'ኢያሱም ማልዶ ተነሣ፤ እስራኤልንም በየነገዶቻቸው ሰበሰባቸው፤ በይሁዳም ነገድ ላይ ምልክት ታየ፤'),
  ('99c44de7-5d3c-5b58-a414-8cd71fff932e', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 17, 17, 'የይሁዳም ወገኖች ተለዩ፤ በዛራም ወገን ምልክት ታየ፤ የዛራም ወገን በየቤተ ሰቡ ተለየ፤'),
  ('9df80a37-b63e-5845-a9ca-413b79dfde82', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 18, 18, 'በዘንበሪም ወገን ምልክት ታየ፤ የዘንበሪም ቤተ ሰብ እያንዳንዱ ተለየ፤ ከይሁዳም ወገን በሆነ በከርሚ ልጅ በዘንበሪ ልጅ በዛራ ልጅ በአካን ላይ ምልክት ታየ።'),
  ('c57d5497-de00-5d7e-a949-2d2aa084218e', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 19, 19, 'ኢያሱም አካንን፥ “ልጄ ሆይ! ለእስራኤል አምላክ ለእግዚአብሔር ክብር ስጥ፤ ለእርሱም ተናዘዝ፤ ያደረግኸውንም ንገረኝ፤ አትሸሽገኝም” አለው።'),
  ('dfc5fd34-e613-5acd-ae22-6402fc824ca5', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 20, 20, 'አካንም መልሶ ኢያሱን፥ “በእውነት በእስራኤል አምላክ በእግዚአብሔር ፊት በድያለሁ፤ እንዲህና እንዲህም አድርጌአለሁ።'),
  ('7676c801-e196-5068-aca3-e698e86a267b', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 21, 21, 'በዘረፋ መካከል አንድ ያማረ ካባ፥ ሁለት መቶ ሰቅል ብር፥ ሚዛኑም አምሳ ሰቅል የሆነ ወርቅ አይቼ ተመኘኋቸው፤ ወሰድኋቸውም፤ እነሆም በድንኳኔ ውስጥ በመሬት ተሸሽገዋል፤ ብሩም ከሁሉ በታች ነው” አለው።'),
  ('031e54aa-dcd1-5c54-a971-b4293f4748a9', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 22, 22, 'ኢያሱም መልእክተኞችን ላከ፤ ወደ ሰፈርም ወደ ድንኳኑ ሮጡ፤ እነሆም እርሱ በድንኳኑ ውስጥ ተደብቆ፥ ብሩም በበታቹ ነበረ።'),
  ('235cddde-2b0c-5384-a909-ca97c3182e2a', '832ddca8-3640-55be-a58a-852744f834d1', 'caab2653-6ea8-58bf-aa00-c9a5bc93f8dc', 23, 23, 'ከድንኳኑም ውስጥ አውጥተው ወደ ኢያሱና ወደ እስራኤል ሽማግሌዎች ሁሉ አመጡት፤ በእግዚአብሔርምፊት አኖሩት።')
